class CountVowels {
    /** Helper: is this char a vowel? */
    private static boolean isVowel(char c) {
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u'
            || c == 'A' || c == 'E' || c == 'I' || c == 'O' || c == 'U';
    }

    /**
     * * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        // Nothing can have a neighbour if the string is null, empty or of length 1
        if (testStr == null || testStr.length() < 2) {
            return 0;
        }

        char[] chars = testStr.toCharArray();
        int count = 0;

        for (int i = 0; i < chars.length; i++) {
            // The character itself must NOT be a vowel (only "characters" with vowel neighbours)
            if (isVowel(chars[i])) {
                continue;
            }

            boolean leftIsVowel  = (i > 0) && isVowel(chars[i - 1]);
            boolean rightIsVowel = (i < chars.length - 1) && isVowel(chars[i + 1]);

            if (leftIsVowel || rightIsVowel) {
                count++;
            }
        }

        return count;
    }

    // Quick self-test
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));            // 7
        System.out.println(countVowels("partofthejourneyistheend"));  // 12
        System.out.println(countVowels("amazonprime"));               // 5
    }
}

