    public static List<Integer> countAlphaDigSpl(String string) {
        int alphaCount = 0;
        int digitCount = 0;
        int specialCount = 0;

        if (string != null) {
            for (int i = 0; i < string.length(); i++) {
                char c = string.charAt(i);
                if (Character.isLetter(c)) {
                    alphaCount++;
                } else if (Character.isDigit(c)) {
                    digitCount++;
                } else {
