class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Item 49: check parameters for validity (fail fast).
        if (cost == null) {
            throw new IllegalArgumentException("cost matrix must not be null");
        }
        if (n <= 0) {
            throw new IllegalArgumentException("matrix size must be positive, but was " + n);
        }
        if (cost.size() != n) {
            throw new IllegalArgumentException(
                    "expected " + n + " rows, but found " + cost.size());
        }

        // Every valid top-left -> bottom-right (right/down only) path visits
        // exactly (2n - 1) cells, so maximizing the average == maximizing the sum.
        int[][] dp = new int[n][n];

        for (int i = 0; i < n; i++) {
            List<Integer> row = cost.get(i);
            if (row == null || row.size() != n) {
                throw new IllegalArgumentException("row " + i + " must contain " + n + " elements");
            }
            for (int j = 0; j < n; j++) {
                int cell = row.get(j);

                if (i == 0 && j == 0) {
                    dp[i][j] = cell;                       // source cell
                } else if (i == 0) {
                    dp[i][j] = cell + dp[i][j - 1];        // first row: come from the left
                } else if (j == 0) {
                    dp[i][j] = cell + dp[i - 1][j];        // first column: come from above
                } else {
                    dp[i][j] = cell + Math.max(dp[i - 1][j], dp[i][j - 1]);
                }
            }
        }

        int pathLength = 2 * n - 1;
        // Item 54: never return null; a single-cell matrix yields its own value.
        return dp[n - 1][n - 1] / (double) pathLength;
    }

    // Demonstration harness
    public static void main(String[] args) {
        System.out.println(maxaverageofpath(
                Arrays.asList(Arrays.asList(1, 2, 3),
                              Arrays.asList(6, 5, 4),
                              Arrays.asList(7, 3, 9)), 3));   // 5.2

        System.out.println(maxaverageofpath(
                Arrays.asList(Arrays.asList(2, 3, 4),
                              Arrays.asList(7, 6, 5),
                              Arrays.asList(8, 4, 10)), 3));  // 6.2

        System.out.println(maxaverageofpath(
                Arrays.asList(Arrays.asList(3, 4, 5),
                              Arrays.asList(8, 7, 6),
                              Arrays.asList(9, 5, 11)), 3));  // 7.2
    }
}

