class SeriesSum {
    /**
     * * Write a function to calculate the sum of series 1²+2²+3²+….+n².
     *
     * > seriesSum(6)
     * 91
     * > seriesSum(7)
     * 140
     * > seriesSum(12)
     * 650
     *
     * Uses the closed form n(n+1)(2n+1)/6 so it runs in constant time
     * and returns an exact integer result (no floating point involved).
     *
     * @param number the upper limit n of the series; must be >= 0
     * @return 1² + 2² + ... + number²
     * @throws IllegalArgumentException if {@code number} is negative
     */
    public static int seriesSum(int number) {
        // Item 49: check parameters for validity
        if (number < 0) {
            throw new IllegalArgumentException(
                    "number must be non-negative, but was: " + number);
        }

        // Compute in long to avoid intermediate overflow, then divide exactly.
        long n = number;
        long sum = n * (n + 1) * (2 * n + 1) / 6;

        return (int) sum;
    }
}

