     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null) {
            return "Not matched!";
        }

        // (?i)      -> case-insensitive, so 'Z' counts too
        // (?<=\w)   -> a word character precedes 'z'  => not at the START of the word
        // (?=\w)    -> a word character follows 'z'   => not at the END of the word
        // Because words are maximal runs of \w, both neighbours being \w guarantees
        // the 'z' sits strictly inside a single word.
        Pattern pattern = Pattern.compile("(?i)(?<=\\w)z(?=\\w)");
        Matcher matcher = pattern.matcher(text);

        return matcher.find() ? "Found a match!" : "Not matched!";
    }

    // --- quick self-test -------------------------------------------------
