        System.out.println(textMatchWordzMiddle("  lang  ."));     // Not matched!
        System.out.println(textMatchWordzMiddle("zebra"));         // Not matched! (z at start)
        System.out.println(textMatchWordzMiddle("buzz"));          // Not matched! (z at end)
