        System.out.println(textMatchWordzMiddle("A-Z"));           // Not matched! (- not a word char)
    }
}

public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
    double[][] dp = new double[n][n];

    // Base case: top-left corner
    dp[0][0] = cost.get(0).get(0);

    // Fill first row (can only come from left)
    for (int j = 1; j < n; j++) {
        dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
    }

    // Fill first column (can only come from above)
    for (int i = 1; i < n; i++) {
        dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
    }

    // Fill rest of the table
    for (int i = 1; i < n; i++) {
        for (int j = 1; j < n; j++) {
            dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
        }
    }

    // Total cells visited on any path from (0,0) to (n-1,n-1) = 2n - 1
    int totalCells = 2 * n - 1;
    return dp[n - 1][n - 1] / totalCells;
}

