class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Degenerate inputs: nothing to average.
        if (n <= 0 || cost == null || cost.isEmpty()) {
            return 0.0;
        }

        // Trivial board: the only path is the single cell itself.
        if (n == 1) {
            return (double) cost.get(0).get(0);
        }

        // Every right/down path visits exactly (2n - 1) cells,
        // so maximizing the average == maximizing the total sum.
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                long bestPredecessor;

                if (i == 0 && j == 0) {
                    bestPredecessor = 0L;               // origin has no predecessor
                } else if (i == 0) {
                    bestPredecessor = dp[i][j - 1];      // only reachable from the left
                } else if (j == 0) {
                    bestPredecessor = dp[i - 1][j];      // only reachable from above
                } else {
                    bestPredecessor = Math.max(dp[i - 1][j], dp[i][j - 1]);
                }

                dp[i][j] = bestPredecessor + cost.get(i).get(j);
            }
        }

        double maxSum = dp[n - 1][n - 1];
        int cellsOnPath = 2 * n - 1;

        return maxSum / cellsOnPath;
    }
}

