        Pattern pattern = Pattern.compile("(?<=\\w)[zZ](?=\\w)", Pattern.CASE_INSENSITIVE);
        Matcher matcher = pattern.matcher(text);
        if (matcher.find()) {
            return "Found a match!";
        }
        return "Not matched!";
    }

