     * > seriesSum(6)
     * 91
     * > seriesSum(7)
     * 140
     * > seriesSum(12)
     * 650
     */
    public static int seriesSum(int number) {
        // An empty sum for non-positive input sizes.
        if (number <= 0) {
            return 0;
        }

        // Closed form: 1^2 + 2^2 + ... + n^2 = n * (n + 1) * (2n + 1) / 6
        // Use long arithmetic so the intermediate product cannot overflow int.
        long n = number;
        long total = n * (n + 1) * (2 * n + 1) / 6;

        return (int) total;
    }

    // Simple driver to demonstrate/verify the required examples.
