public static int newmanPrime(int n) {
    List<Integer> list = new ArrayList<>(Arrays.asList(1, 3, 7, 17));

    // Track both subsequences
    int a0 = 1, a1 = 7;   // Subsequence A
    int b0 = 3, b1 = 17;  // Subsequence B
    int nextA = 6 * a1 - a0;  // 41
    int nextB = 6 * b1 - b0;  // 99

    while (list.size() < n) {
        if (nextA < nextB) {
            list.add(nextA);
            a0 = a1;
            a1 = nextA;
            nextA = 6 * a1 - a0;
        } else {
            list.add(nextB);
            b0 = b1;
            b1 = nextB;
            nextB = 6 * b1 - b0;
        }
    }

    return list.get(n - 1);
}

