public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // dp[i][j] = maximum sum to reach cell (i, j)
        int[][] dp = new int[n][n];

        // Initialize starting cell
        dp[0][0] = cost.get(0).get(0);

        // Fill first column (only downward moves possible)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill first row (only rightward moves possible)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill remaining cells: come from above or from left
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
            }
        }

        // All paths have length 2*n - 1, so average = maxSum / pathLength
        int pathLength = 2 * n - 1;
        return (double) dp[n - 1][n - 1] / pathLength;
    }
}

