class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Degenerate input: no path exists.
        if (cost == null || n <= 0) {
            return 0.0;
        }

        // Every top-left -> bottom-right path (right/down moves) has exactly 2n-1 cells,
        // so maximizing the average == maximizing the total sum.
        int[][] dp = new int[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int bestFromPrev;
                if (i == 0 && j == 0) {
                    bestFromPrev = 0;                       // starting cell
                } else if (i == 0) {
                    bestFromPrev = dp[i][j - 1];            // only reachable from the left
                } else if (j == 0) {
                    bestFromPrev = dp[i - 1][j];            // only reachable from above
                } else {
                    bestFromPrev = Math.max(dp[i - 1][j],   // came from above
                                            dp[i][j - 1]);  // came from the left
                }
                dp[i][j] = bestFromPrev + cost.get(i).get(j);
            }
        }

        double bestSum = dp[n - 1][n - 1];
        double cellsOnPath = 2.0 * n - 1.0;

        return bestSum / cellsOnPath;
    }
}

