    public static int newmanPrime(int n) {
        if (n == 1) return 1;
        if (n == 2) return 3;
        int prev2 = 1; // a(n-2)
        int prev1 = 3; // a(n-1)
        int curr = 0;
        for (int i = 3; i <= n; i++) {
