import java.util.*;
import java.math.*;


class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     *
     * The Newman–Shanks–Williams numbers are generated by
     *     S(0) = 1, S(1) = 1, S(n) = 2*S(n-1) + S(n-2),
     * giving 1, 1, 3, 7, 17, 41, 99, 239, ...
     */
    public static int newmanPrime(int n) {
        // Fail fast on invalid input (errors should be detected as soon as possible).
        if (n < 0) {
            throw new IllegalArgumentException("index must be non-negative: " + n);
        }
        if (n <= 1) {          // S(0) = 1, S(1) = 1
            return 1;
        }

        // Iterative evaluation of the recurrence: O(n) time, O(1) space.
        // BigInteger keeps intermediate terms exact -- plain int/long would wrap around.
        BigInteger prev = BigInteger.ONE;   // S(n-2)
        BigInteger curr = BigInteger.ONE;   // S(n-1)

        for (int i = 2; i <= n; i++) {
            BigInteger next = curr.shiftLeft(1).add(prev);   // 2*curr + prev
            prev = curr;
            curr = next;
        }
        return curr.intValue();
    }

    // Quick self-check of the documented examples.
    public static void main(String[] args) {
        System.out.println(newmanPrime(3));  // 7
        System.out.println(newmanPrime(4));  // 17
        System.out.println(newmanPrime(5));  // 41
        System.out.println(newmanPrime(2));  // 3
        System.out.println(newmanPrime(6));  // 99
