class SeriesSum {
    /**
     * * Write a function to calculate the sum of series 1²+2²+3²+….+n².
     *
     * > seriesSum(6)
     * 91
     * > seriesSum(7)
     * 140
     * > seriesSum(12)
     * 650
     */
    public static int seriesSum(int number) {
        if (number <= 0) {
            return 0;
        }
        // Closed form: 1²+2²+...+n² = n*(n+1)*(2n+1)/6
        // Use long arithmetic internally to avoid intermediate overflow,
        // then cast back to int for the result.
        long n = number;
        long sum = n * (n + 1) * (2 * n + 1) / 6;
        return (int) sum;
    }
}

