class TextMatchWordzMiddle {
    /**
     * * Write a function that matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        // Primary test: 'z' flanked by word characters on BOTH sides.
        // \B before z -> z is not the first character of the word
        // \B after  z -> z is not the last  character of the word
        Pattern pattern = Pattern.compile("\\Bz\\B");
        if (pattern.matcher(text).find()) {
            return "Found a match!";
        }

        // Safety net: explicit scan over every word (agrees with the regex above).
        Matcher words = Pattern.compile("\\w+").matcher(text);
        while (words.find()) {
            String w = words.group();
            int n = w.length();
            for (int i = 1; i < n - 1; i++) {   // strictly interior positions
                if (w.charAt(i) == 'z') {
                    return "Found a match!";
                }
            }
        }

        return "Not matched!";
    }

    // quick self-check
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));  // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));      // Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));     // Not matched!
        System.out.println(textMatchWordzMiddle("zz"));           // Not matched!
        System.out.println(textMatchWordzMiddle("zza zaz z"));    // Found a match!
    }
}

public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
    int[][] dp = new int[n][n];
    dp[0][0] = cost.get(0).get(0);

    // First row: only reachable from left
    for (int j = 1; j < n; j++) {
        dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
    }

    // First column: only reachable from above
    for (int i = 1; i < n; i++) {
        dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
    }

    // Fill rest: come from max of top or left
    for (int i = 1; i < n; i++) {
        for (int j = 1; j < n; j++) {
            dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
        }
    }

    // Every path visits exactly (2n-1) cells
    return dp[n - 1][n - 1] / (double)(2 * n - 1);
}

