    public static int countVowels(String testStr) {
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        int n = testStr.length();
        int count = 0;

        for (int i = 0; i < n; i++) {
            char current = testStr.charAt(i);

            // only characters that are not vowels themselves are counted
            if (isVowel(current)) {
                continue;
