class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Base cases of the NSW recurrence: a(1) = 1, a(2) = 3
        if (n <= 1) {
            return 1;
        }
        if (n == 2) {
            return 3;
        }

        // a(n) = 2 * a(n-1) + a(n-2)
        int prev = 1; // a(i-2)
        int curr = 3; // a(i-1)
        for (int i = 3; i <= n; i++) {
            int next = 2 * curr + prev;
            prev = curr;
            curr = next;
        }
        return curr;
    }

    // Quick self-check
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

