class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Trivial / degenerate inputs
        if (cost == null || n <= 0) {
            return 0.0;
        }
        if (n == 1) {
            return (double) cost.get(0).get(0);
        }

        // dp[i][j] = maximum sum of any right/down path ending at cell (i, j)
        long[][] dp = new long[n][n];

        dp[0][0] = cost.get(0).get(0);

        // First column: can only be reached from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // First row: can only be reached from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the rest: come from the better of (up) or (left)
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                long fromUp = dp[i - 1][j];
                long fromLeft = dp[i][j - 1];
                dp[i][j] = cost.get(i).get(j) + Math.max(fromUp, fromLeft);
            }
        }

        // Every path from (0,0) to (n-1,n-1) visiting only right/down moves
        // traverses exactly (n-1) + (n-1) + 1 = 2n - 1 cells, so the denominator
        // is the same for every path => maximizing the average == maximizing the sum.
        int steps = 2 * n - 1;

        return ((double) dp[n - 1][n - 1]) / steps;
    }

    // Optional driver to exercise the examples above
    public static void main(String[] args) {
        System.out.println(maxaverageofpath(
                Arrays.asList(Arrays.asList(1, 2, 3),
                              Arrays.asList(6, 5, 4),
                              Arrays.asList(7, 3, 9)), 3));   // 5.2

        System.out.println(maxaverageofpath(
                Arrays.asList(Arrays.asList(2, 3, 4),
                              Arrays.asList(7, 6, 5),
                              Arrays.asList(8, 4, 10)), 3));  // 6.2

        System.out.println(maxaverageofpath(
                Arrays.asList(Arrays.asList(3, 4, 5),
                              Arrays.asList(8, 7, 6),
                              Arrays.asList(9, 5, 11)), 3));  // 7.2
    }
}

