        if (vowels.indexOf(c) != -1) continue;

        boolean hasVowelNeighbor = false;
        // Check left neighbor
        if (i > 0 && vowels.indexOf(Character.toLowerCase(testStr.charAt(i - 1))) != -1) {
            hasVowelNeighbor = true;
