        // Check right neighbor
        if (!hasVowelNeighbor && i < len - 1 && vowels.indexOf(Character.toLowerCase(testStr.charAt(i + 1))) != -1) {
            hasVowelNeighbor = true;
        }

        if (hasVowelNeighbor) count++;
    }

    return count;
}

