import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class Maxaverageofpath {

    /**
     * Holds the aggregate of a path (its sum and its length) and computes the average.
     * Built via a Builder (Effective Java, Item 2) because a plain constructor would
     * take several parameters of the same type (int sum, int length), which invites
     * silently swapped arguments that the compiler cannot detect.
     */
    private static final class PathSummary {
        private final int sum;
        private final int length;

        private PathSummary(Builder builder) {
            this.sum = builder.sum;
            this.length = builder.length;
        }

        double average() {
            if (length <= 0) {
                return 0.0d;
            }
            return (double) sum / (double) length;
        }

        static Builder builder() {
            return new Builder();
        }

        static final class Builder {
            private int sum = 0;
            private int length = 0;

            Builder sum(int sum) {
                this.sum = sum;
                return this;
            }

            Builder length(int length) {
                this.length = length;
                return this;
            }

            PathSummary build() {
                return new PathSummary(this);
            }
        }
    }

    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // ---- defensive handling of degenerate inputs -------------------------
        if (cost == null || cost.isEmpty() || n <= 0) {
            return 0.0d;
        }
        if (n == 1) {
            return PathSummary.builder()
                    .sum(cost.get(0).get(0))
                    .length(1)
                    .build()
                    .average();
        }

        // ---- DP: maximum path SUM reaching cell (i, j) ----------------------
        // Every such path has exactly (2n - 1) cells, therefore
        // maximizing the sum also maximizes the average.
        int[][] dp = new int[n][n];

        dp[0][0] = cost.get(0).get(0);

        // first row: can only be reached from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column: can only be reached from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // interior cells: best of "from above" vs "from the left"
        for (int i = 1; i < n; i++) {
            List<Integer> row = cost.get(i);
            for (int j = 1; j < n; j++) {
                int bestPrev = Math.max(dp[i - 1][j], dp[i][j - 1]);
                dp[i][j] = bestPrev + row.get(j);
            }
        }

        int bestSum = dp[n - 1][n - 1];
        int pathLength = 2 * n - 1;   // number of cells on any such path

        return PathSummary.builder()
                .sum(bestSum)
                .length(pathLength)
                .build()
                .average();
    }
}

