class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Sequence: f(0)=1, f(1)=1, f(n)=2*f(n-1)+f(n-2)
        //   1, 1, 3, 7, 17, 41, 99, 239, 577, 1393, ...
        // Closed form: f(n) = ((1+sqrt(2))^n + (1-sqrt(2))^n) / 2
        if (n <= 1) {
            return 1;
        }

        long prev = 1;   // f(i-1)
        long curr = 1;   // f(i)

        for (int i = 1; i < n; i++) {
            long next = 2L * curr + prev;   // exact integer recurrence
            prev = curr;
            curr = next;
        }

        return (int) curr;
    }

    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

