     */
    public static String textMatchWordzMiddle(String text) {
        // Guard against null input (defensive programming)
        if (text == null) {
            return "Not matched!";
        }

        // \b  -> word boundary (start of a word)
        // \w+ -> at least one character BEFORE 'z'  (z is not the first char)
        // z   -> the required letter
        // \w+ -> at least one character AFTER 'z'   (z is not the last char)
        // \b  -> word boundary (end of a word)
        Pattern pattern = Pattern.compile("\\b\\w+z\\w+\\b");
        Matcher matcher = pattern.matcher(text);

        // find() searches anywhere in the input, unlike matches()
        if (matcher.find()) {
            return "Found a match!";
        }
        return "Not matched!";
    }
}

