static boolean isPrime(int p) {
    if (p < 2) return false;
    if (p < 4) return true;
    if (p % 2 == 0) return false;
    for (int i = 3; (long) i * i <= p; i += 2)
        if (p % i == 0) return false;
    return true;
}

static boolean isNSW(int p) {
    if (p == 2) return true;
    long p2 = (long) p * p;
    long v1 = (p2 - 1) / 2;
    long r1 = (long) Math.sqrt(v1);
    if (r1 * r1 == v1) return true;
    long v2 = (p2 + 1) / 2;
    long r2 = (long) Math.sqrt(v2);
    return r2 * r2 == v2;
}

