class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Every top-left -> bottom-right path (only right/down moves) contains
        // exactly (2n - 1) cells, so maximizing the average == maximizing the sum.
        if (n <= 0) {
            return 0.0;
        }

        // dp[i][j] = maximum sum of any valid path from (0,0) to (i,j)
        int[][] dp = new int[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int value = cost.get(i).get(j);

                if (i == 0 && j == 0) {
                    dp[i][j] = value;                       // start cell
                } else if (i == 0) {
                    dp[i][j] = dp[i][j - 1] + value;        // only from the left
                } else if (j == 0) {
                    dp[i][j] = dp[i - 1][j] + value;        // only from above
                } else {
                    dp[i][j] = Math.max(dp[i - 1][j],       // come from above
                                        dp[i][j - 1])       // or from the left
                               + value;
                }
            }
        }

        // Average = best path sum / number of cells on the path (2n - 1)
        double pathLength = 2.0 * n - 1.0;
        return dp[n - 1][n - 1] / pathLength;
    }
}

