class CountAlphaDigSpl {

    /* ---- Item 5: dependencies injected, not hard-wired ---- */
    private final BiPredicate<Character, Character> isAlpha;
    private final BiPredicate<Character, Character> isDigit;

    /** Default rules: standard Unicode letter / digit classification. */
    public CountAlphaDigSpl() {
        this((c, n) -> Character.isLetter(c),
             (c, n) -> Character.isDigit(c));
    }

    /**
     * Injected-resource constructor: callers supply the classification
     * rules, so behaviour can be swapped (flexibility + testability).
     */
    public CountAlphaDigSpl(BiPredicate<Character, Character> alphaRule,
                            BiPredicate<Character, Character> digitRule) {
        this.isAlpha = Objects.requireNonNull(alphaRule);
        this.isDigit = Objects.requireNonNull(digitRule);
    }

    /**
     * * Write a function to count alphabets,digits and special charactes in a given string.
     *
     * > countAlphaDigSpl("abc!@#123")
     * [3, 3, 3]
     * > countAlphaDigSpl("dgsuy@#$%&1255")
     * [5, 4, 5]
     * > countAlphaDigSpl("fjdsif627348#%$^&")
     * [6, 6, 5]
     */
    public static List<Integer> countAlphaDigSpl(String string) {
        return new CountAlphaDigSpl().count(string);
    }

    /** Instance version using the injected rules. */
    public List<Integer> count(String string) {
        int alphabets = 0;
        int digits = 0;
        int specials = 0;

        if (string != null) {
            for (int i = 0; i < string.length(); i++) {
                char c = string.charAt(i);
                if (isAlpha.test(c, 'a')) {
                    alphabets++;
                } else if (isDigit.test(c, '0')) {
                    digits++;
                } else {
                    specials++;   // anything left is a special character
                }
            }
        }

        return new ArrayList<>(Arrays.asList(alphabets, digits, specials));
    }

    public static void main(String[] args) {
        System.out.println(countAlphaDigSpl("abc!@#123"));          // [3, 3, 3]
        System.out.println(countAlphaDigSpl("dgsuy@#$%&1255"));    // [5, 4, 5]
        System.out.println(countAlphaDigSpl("fjdsif627348#%$^&")); // [6, 6, 5]
    }
}

