class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // NSW numbers: a(1) = 1, a(2) = 3, a(k) = 2*a(k-1) + a(k-2)
        // 1, 3, 7, 17, 41, 99, 239, ...
        //
        // Computed entirely with primitives: no objects are created per call,
        // so there is nothing to allocate or garbage-collect (Item 6).
        if (n <= 0) {
            return 0;
        }
        if (n == 1) {
            return 1;
        }

        long prev = 1L; // a(1)
        long curr = 3L; // a(2)

        for (int i = 3; i <= n; i++) {
            long next = 2L * curr + prev; // a(i) = 2*a(i-1) + a(i-2)
            prev = curr;
            curr = next;
        }
        return (int) curr;
    }
}

