        // Single pre-sized buffer: keeps exactly ceil(len/2) - ... chars.
        // Number of odd indices in [0, len) is len / 2.
        StringBuilder sb = new StringBuilder(len / 2);

        // Walk only the odd indices, appending the character directly.
        // No temporary String/Character objects are created along the way.
        for (int i = 1; i < len; i += 2) {
            sb.append(str1.charAt(i));
        }

        // One final conversion to String (unavoidable, since Strings are immutable).
        return sb.toString();
    }

    // --- quick self-test -------------------------------------------------
    public static void main(String[] args) {
        System.out.println(removeOdd("python"));   // yhn
        System.out.println(removeOdd("program"));   // rga
        System.out.println(removeOdd("language"));  // agae
        System.out.println("[" + removeOdd("") + "]");      // []
        System.out.println("[" + removeOdd("ab") + "]");    // [b]
        System.out.println("[" + removeOdd(null) + "]");   // []
    }
}

