class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Degenerate inputs: no path exists -> average is undefined, return 0.0
        if (cost == null || cost.isEmpty() || n <= 0) {
            return 0.0;
        }

        // dp[i][j] = maximum sum of any path from (0,0) to (i,j)
        int[][] dp = new int[n][n];

        for (int i = 0; i < n; i++) {
            List<Integer> row = cost.get(i);
            for (int j = 0; j < n; j++) {
                int value = row.get(j);

                // Narrowest possible scope: local scratch variables die at end of iteration,
                // so no obsolete references are retained (Effective Java, Item 7).
                int bestFromTop = Integer.MIN_VALUE;
                int bestFromLeft = Integer.MIN_VALUE;

                if (i > 0) {
                    bestFromTop = dp[i - 1][j];
                }
                if (j > 0) {
                    bestFromLeft = dp[i][j - 1];
                }

                int best = Math.max(bestFromTop, bestFromLeft);
                dp[i][j] = (best == Integer.MIN_VALUE) ? value : value + best;
            }
            // 'row' goes out of scope here naturally; nothing to null out.
        }

        // Every valid path contains exactly (2n - 1) cells, so maximizing the sum
        // is identical to maximizing the average.
        double pathLength = 2.0 * n - 1.0;
        return dp[n - 1][n - 1] / pathLength;
    }
}

