class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Base cases of the Newman-Shanks-Williams recurrence:
        // S(1) = 1, S(2) = 3, S(n) = 2*S(n-1) + S(n-2)
        if (n <= 0) {
            return 1;
        }
        if (n == 1) {
            return 1;
        }
        if (n == 2) {
            return 3;
        }

        // Iterative evaluation of the recurrence (avoids exponential recursion).
        // Use long intermediates since the sequence grows like (1 + sqrt(2))^n.
        long prev = 1L;   // S(i-2)
        long curr = 3L;   // S(i-1)

        for (int i = 3; i <= n; i++) {
            long next = 2L * curr + prev;
            prev = curr;
            curr = next;
        }

        return (int) curr;
    }
}

