class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Trivial / invalid sizes
        if (cost == null || n <= 0) {
            return 0.0;
        }

        // Every top-left -> bottom-right path (only right/down moves)
        // contains exactly (2n - 1) cells, so the average is
        // sum / (2n - 1).  Maximizing the average == maximizing the sum.
        long pathLength = 2L * n - 1;

        // dp[i][j] = maximum sum of any path from (0,0) to (i,j)
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                long bestPrev = Long.MIN_VALUE / 4;   // effectively -infinity

                if (i > 0) {
                    bestPrev = Math.max(bestPrev, dp[i - 1][j]);      // came from above
                }
                if (j > 0) {
                    bestPrev = Math.max(bestPrev, dp[i][j - 1]);      // came from the left
                }

                long here = cost.get(i).get(j);
                // For (0,0) bestPrev stays -inf, so we just take 'here'
                dp[i][j] = (bestPrev == Long.MIN_VALUE / 4) ? here : bestPrev + here;
            }
        }

        double maxSum = (double) dp[n - 1][n - 1];
        return maxSum / pathLength;
    }

    // --- quick self-check -------------------------------------------------
    public static void main(String[] args) {
        System.out.println(maxaverageofpath(
                Arrays.asList(Arrays.asList(1, 2, 3),
                              Arrays.asList(6, 5, 4),
                              Arrays.asList(7, 3, 9)), 3));   // 5.2

        System.out.println(maxaverageofpath(
                Arrays.asList(Arrays.asList(2, 3, 4),
                              Arrays.asList(7, 6, 5),
                              Arrays.asList(8, 4, 10)), 3));  // 6.2

        System.out.println(maxaverageofpath(
                Arrays.asList(Arrays.asList(3, 4, 5),
                              Arrays.asList(8, 7, 6),
                              Arrays.asList(9, 5, 11)), 3));  // 7.2
    }
}

