class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non-negative: " + n);
        }

        // S0 = 1, S1 = 1, Sn = 2*Sn-1 + Sn-2
        int prev2 = 1; // S(n-2)
        int prev1 = 1; // S(n-1)

        if (n == 0) return prev2;
        if (n == 1) return prev1;

        for (int i = 2; i <= n; i++) {
            int current = 2 * prev1 + prev2;
            prev2 = prev1;
            prev1 = current;
        }
        return prev1;
    }

    // Quick self-check
    public static void main(String[] args) {
        System.out.println(newmanPrime(0)); // 1
        System.out.println(newmanPrime(1)); // 1
        System.out.println(newmanPrime(2)); // 3
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
        System.out.println(newmanPrime(6)); // 97
    }
}

