import java.util.*;
import java.math.*;


class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Validate input: need a non-empty, well-formed square matrix.
        if (cost == null || n <= 0 || cost.size() < n) {
            return 0.0;
        }

        // Clamp n to the actual number of rows available.
        int size = n;
        for (int i = 0; i < size; i++) {
            List<Integer> row = cost.get(i);
            if (row == null || row.size() < size) {
                return 0.0;               // malformed / ragged matrix
            }
            size = Math.min(size, row.size());
        }

        if (size == 0) {
            return 0.0;
        }

        // Every path from (0,0) to (size-1,size-1) using only DOWN/RIGHT moves
        // visits exactly (2*size - 1) cells, so all paths share the same length.
        // Maximizing the average therefore reduces to maximizing the SUM.
        long NEG = Long.MIN_VALUE / 4;    // sentinel that cannot underflow on add
        long[][] dp = new long[size][size];

        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                long value = cost.get(i).get(j);
                if (i == 0 && j == 0) {
                    dp[i][j] = value;
                    continue;
                }
                long fromTop  = (i > 0) ? dp[i - 1][j] : NEG;
                long fromLeft = (j > 0) ? dp[i][j - 1] : NEG;
                dp[i][j] = Math.max(fromTop, fromLeft) + value;
            }
        }

        double pathLength = 2.0 * size - 1.0;
