     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n <= 2) {
            return n == 1 ? 1 : 3;
        }
        int prev2 = 1; // a(1)
        int prev1 = 3; // a(2)
        int current = 0;
        for (int i = 3; i <= n; i++) {
            current = 2 * prev1 + prev2;
            prev2 = prev1;
            prev1 = current;
        }
        return current;
    }
}

