class TextMatchWordzMiddle {
    /**
     * * Write a function that matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null) {
            return "Not matched!";
        }

        // 'z' must have a word character on BOTH sides:
        //   lookbehind (?<=\w) -> something word-like before 'z'
        //   lookahead   (?=\w)  -> something word-like after  'z'
        // Both are zero-width assertions, so nothing extra is consumed.
        String regex = "(?<=\\w)z(?=\\w)";

        Matcher matcher = Pattern.compile(regex).matcher(text);
        if (matcher.find()) {
            return "Found a match!";
        }
        return "Not matched!";
    }

    // Equivalent alternative implementations (same results):
    //   Pattern.compile("\\w+z\\w+")      -- at least one word char each side
    //   Pattern.compile("[A-Za-z0-9_]z[A-Za-z0-9_]")

    // ---------- quick self-test ----------
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));     // Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));    // Not matched!

        // Edge cases: 'z' at start or end of a word must NOT match
        System.out.println(textMatchWordzMiddle("zabc."));        // Not matched!
        System.out.println(textMatchWordzMiddle("abcz."));        // Not matched!
        System.out.println(textMatchWordzMiddle("a z b."));       // Not matched! ('z' alone)
        System.out.println(textMatchWordzMiddle("ab z cd."));     // Not matched!
        System.out.println(textMatchWordzMiddle("abzzcd."));      // Found a match!
        System.out.println(textMatchWordzMiddle("az_b."));        // Found a match! ('_' is a word char)
    }
}

public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
    double[][] dp = new double[n][n];

    dp[0][0] = cost.get(0).get(0);

    // First row: can only come from left
    for (int j = 1; j < n; j++) {
        dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
    }

    // First column: can only come from above
    for (int i = 1; i < n; i++) {
        dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
    }

    // Fill rest of the table
    for (int i = 1; i < n; i++) {
        for (int j = 1; j < n; j++) {
            dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
        }
    }

    // Total elements in any path from (0,0) to (n-1,n-1) = 2n - 1
    return dp[n - 1][n - 1] / (2.0 * n - 1);
}

