class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Trivial / degenerate inputs
        if (cost == null || n <= 0 || cost.isEmpty()) {
            return 0.0;
        }

        // dp[i][j] = maximum sum of a path from (0,0) to (i,j)
        double[][] dp = new double[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                double cell = cost.get(i).get(j);

                if (i == 0 && j == 0) {
                    // Starting cell: the path consists only of this value
                    dp[i][j] = cell;
                } else {
                    double best = -Double.MAX_VALUE;
                    // Move down (from above)
                    if (i > 0) {
                        best = Math.max(best, dp[i - 1][j]);
                    }
                    // Move right (from the left)
                    if (j > 0) {
                        best = Math.max(best, dp[i][j - 1]);
                    }
                    dp[i][j] = best + cell;
                }
            }
        }

        // Every right/down path visits exactly (2n - 1) cells,
        // so maximizing the average == maximizing the sum.
        double pathLength = 2.0 * n - 1.0;
        return dp[n - 1][n - 1] / pathLength;
    }

    public static void main(String[] args) {
