public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
    double[][] dp = new double[n][n];

    // Initialize top-left corner
    dp[0][0] = cost.get(0).get(0);

    // First row - can only come from left
    for (int j = 1; j < n; j++) {
        dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
    }

    // First column - can only come from top
    for (int i = 1; i < n; i++) {
        dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
    }

    // Fill the rest using the recurrence:
    // dp[i][j] = max(dp[i-1][j], dp[i][j-1]) + cost[i][j]
    for (int i = 1; i < n; i++) {
        for (int j = 1; j < n; j++) {
            dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
        }
    }

    // Total path length is always (2n - 1) cells
    return dp[n - 1][n - 1] / (double)(2 * n - 1);
}

