class SeriesSum {
    /**
     * * Write a function to calculate the sum of series 1²+2²+3²+….+n².
     *
     * > seriesSum(6)
     * 91
     * > seriesSum(7)
     * 140
     * > seriesSum(12)
     * 650
     */
    public static int seriesSum(int number) {
        if (number <= 0) {
            return 0;
        }
        // Closed-form formula for sum of squares: n(n+1)(2n+1)/6
        // Using long arithmetic internally to avoid intermediate overflow,
        // then casting back to int as required by the signature.
        long n = number;
        long result = n * (n + 1) * (2 * n + 1) / 6;
        return (int) result;
    }
}

