class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Degenerate input: no cells -> no path
        if (n <= 0 || cost == null || cost.isEmpty()) {
            return 0.0;
        }

        // dp[i][j] = maximum sum of any path from (0,0) to (i,j) using only down/right moves
        double[][] dp = new double[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                double cell = (cost.get(i).get(j)).doubleValue();

                if (i == 0 && j == 0) {
                    dp[i][j] = cell;
                    continue;
                }

                double best = Double.NEGATIVE_INFINITY;
                if (i > 0) {
                    best = Math.max(best, dp[i - 1][j]); // came from above
                }
                if (j > 0) {
                    best = Math.max(best, dp[i][j - 1]); // came from the left
                }

                dp[i][j] = best + cell;
            }
        }

        // Every valid path from (0,0) to (n-1,n-1) visits exactly 2n-1 cells,
        // so maximizing the sum also maximizes the average.
        int pathLength = 2 * n - 1;
        double maxSum = dp[n - 1][n - 1];

        return maxSum / pathLength;
    }
}

