class CountVowels {
    /**
     * * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    private static final String VOWELS = "aeiouAEIOU";

    /** Returns true if the given character is a vowel (case-insensitive). */
    private static boolean isVowel(char c) {
        return VOWELS.indexOf(c) != -1;
    }

    public static int countVowels(String testStr) {
        // Guard against null / empty input
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        int len = testStr.length();
        int count = 0;

        for (int i = 0; i < len; i++) {
            char current = testStr.charAt(i);

            // Only consider non-vowel characters themselves
            if (isVowel(current)) {
                continue;
            }

            // Check the left neighbor (if it exists)
            boolean hasVowelNeighbor = (i > 0) && isVowel(testStr.charAt(i - 1));

            // Check the right neighbor (if it exists)
            if (!hasVowelNeighbor && i < len - 1) {
                hasVowelNeighbor = isVowel(testStr.charAt(i + 1));
            }

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }
}

