class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // S(n) = ((1+sqrt(2))^n + (1-sqrt(2))^n)/2 , i.e. 1, 3, 7, 17, 41, 99, 239, ...
        // computed with the exact integer recurrence S(n) = 2*S(n-1) + S(n-2)
        if (n <= 1) {
            return 1;               // S(1) = 1 (and a sane value for n <= 0)
        }

        long prev = 1L;             // S(i-2), starts as S(1) = 1
        long cur  = 3L;             // S(i-1), starts as S(2) = 3

        for (int i = 2; i < n; i++) {
            long next = 2L * cur + prev;   // S(i) = 2*S(i-1) + S(i-2)
            prev = cur;
            cur  = next;
        }
        return (int) cur;
    }
}

