class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Edge case: empty matrix -> average defined as 0.0
        if (n <= 0 || cost == null || cost.isEmpty()) {
            return 0.0;
        }

        // dp[i][j] = maximum sum of any path from (0,0) to (i,j)
        int[][] dp = new int[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int current = cost.get(i).get(j);

                if (i == 0 && j == 0) {
                    dp[i][j] = current;
                    continue;
                }

                int bestFromAbove = (i > 0) ? dp[i - 1][j] : Integer.MIN_VALUE;
                int bestFromLeft  = (j > 0) ? dp[i][j - 1] : Integer.MIN_VALUE;

                // Guard against overflow when both predecessors are absent (impossible here,
                // but keeps the computation deterministic and safe).
                int bestPrev;
                if (i == 0) {
                    bestPrev = bestFromLeft;
                } else if (j == 0) {
                    bestPrev = bestFromAbove;
                } else {
                    bestPrev = Math.max(bestFromAbove, bestFromLeft);
                }

                dp[i][j] = bestPrev + current;
            }
        }

        // Every path from (0,0) to (n-1,n-1) visiting only right/down moves
        // contains exactly (2n - 1) cells, so maximizing the sum maximizes the average.
        int maxSum = dp[n - 1][n - 1];
        int pathLength = 2 * n - 1;

        return ((double) maxSum) / pathLength;
    }
}

