class TextMatchWordzMiddle {

    /**
     * Word containing 'z' that is NOT at the start and NOT at the end:
     *   \b  \w+  z  \w+  \b
     *    ^   ^       ^   ^
     *    |   |       |   at least one word char AFTER 'z'
     *    |   |       the literal 'z'
     *    |   at least one word char BEFORE 'z'
     *    word boundary so the whole word is consumed (stops before '.', etc.)
     */
    private static final Pattern WORD_Z_MIDDLE = Pattern.compile("\\b\\w+z\\w+\\b");

    /**
     * * Write a function that matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // No explicit null check is required for correctness of the pattern itself,
        // but guarding keeps the method total for any input.
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        Matcher matcher = WORD_Z_MIDDLE.matcher(text);
        // find() searches for the pattern anywhere inside the text,
        // so surrounding spaces/punctuation do not matter.
        if (matcher.find()) {
            return "Found a match!";
        }
        return "Not matched!";
    }

    // Quick self-test
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));  // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));      // Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));     // Not matched!
        System.out.println(textMatchWordzMiddle("zab"));           // Not matched! (start)
        System.out.println(textMatchWordzMiddle("abz"));           // Not matched! (end)
        System.out.println(textMatchWordzMiddle("hello a_z world"));// Not matched! (_z is end)
        System.out.println(textMatchWordzMiddle("say abcde now"));// Not matched!
    }
}

