class TextMatchWordzMiddle {
    /**
     * * Write a function that matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Defensive: nothing to search in a null/empty input.
        if (text == null || text.length() == 0) {
            return "Not matched!";
        }

        // (?<=\w) : a word character sits immediately before the 'z'
        //           -> the 'z' cannot be the first character of its word.
        // (?=\w)  : a word character sits immediately after the 'z'
        //           -> the 'z' cannot be the last character of its word.
        // Because 'z' itself is a word character, both neighbours necessarily
        // belong to the very same word, so the 'z' is strictly in the middle.
        java.util.regex.Pattern pattern =
                java.util.regex.Pattern.compile("(?<=\\w)z(?=\\w)");
        java.util.regex.Matcher matcher = pattern.matcher(text);

        if (matcher.find()) {
            return "Found a match!";
        }
        return "Not matched!";
    }
}

