    for (int i = 1; i < n; i++) {
        dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
    }

    // Fill first row (only reachable from left)
    for (int j = 1; j < n; j++) {
        dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
    }

    // Fill rest of the table: come from top or left, whichever gives larger sum
    for (int i = 1; i < n; i++) {
        for (int j = 1; j < n; j++) {
            dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
        }
    }

    // Every path from (0,0) to (n-1,n-1) has exactly (2n-1) cells
    return (double) dp[n - 1][n - 1] / (2 * n - 1);
}

