     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        if (n <= 0) {
            return 0.0;
        }

        // dp[i][j] holds the maximum sum of any right/down path from (0,0) to (i,j)
        int[][] dp = new int[n][n];
        dp[0][0] = cost.get(0).get(0);

        // First row: only reachable from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column: only reachable from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Interior cells: come from above or from the left
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                int fromAbove = dp[i - 1][j];
                int fromLeft = dp[i][j - 1];
                int bestPrev = Math.max(fromAbove, fromLeft);
                dp[i][j] = bestPrev + cost.get(i).get(j);
            }
        }

        // Every valid path visits exactly (2n - 1) cells, so the average
        // is maximized exactly when the sum is maximized.
        int pathLength = 2 * n - 1;
        double total = dp[n - 1][n - 1];
        return total / pathLength;
    }
}

