class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Base cases of the NSW recurrence: S_1 = 1, S_2 = 3
        if (n <= 1) {
            return 1;
        }
        if (n == 2) {
            return 3;
        }

        // Iterate the recurrence S_k = 2 * S_{k-1} + S_{k-2}
        long prev = 1;  // S_{k-2}
        long curr = 3;  // S_{k-1}

        for (int k = 3; k <= n; k++) {
            long next = 2L * curr + prev;
            prev = curr;
            curr = next;
        }

        return (int) curr;
    }
}

