class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Trivial / invalid input guard
        if (cost == null || cost.isEmpty() || n <= 0) {
            return 0.0;
        }

        // dp[i][j] = maximum sum of any right/down path ending at cell (i, j)
        int[][] dp = new int[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {

                // Read the cell value defensively (matrix may be smaller than n)
                int value = 0;
                if (i < cost.size()) {
                    List<Integer> row = cost.get(i);
                    if (row != null && j < row.size() && row.get(j) != null) {
                        value = row.get(j);
                    }
                }

                int best = 0;
                if (i == 0 && j == 0) {
                    best = 0;                       // start cell, nothing to add
                } else {
                    best = Integer.MIN_VALUE;
                    if (i > 0) {                    // came from above
                        best = Math.max(best, dp[i - 1][j]);
                    }
                    if (j > 0) {                    // came from the left
                        best = Math.max(best, dp[i][j - 1]);
                    }
                }

                dp[i][j] = best + value;
            }
        }

        // Every valid path contains exactly (2n - 1) cells, so the average
        // of the best path = (best sum) / (2n - 1).
        double pathLength = 2.0 * n - 1.0;
        return dp[n - 1][n - 1] / pathLength;
    }
}

