     */
    public static String textMatchWordzMiddle(String text) {
        // \b   -> word boundary (start of a word)
        // \w+  -> one or more chars BEFORE the 'z'  (so 'z' is not at the start)
        // z    -> the letter we are looking for
        // \w+  -> one or more chars AFTER the 'z'   (so 'z' is not at the end)
        // \b   -> word boundary (end of a word)
        Pattern pattern = Pattern.compile("\\b\\w+z\\w+\\b",
                                          Pattern.CASE_INSENSITIVE);
        if (text == null) {
            return "Not matched!";
        }
        Matcher matcher = pattern.matcher(text);
        if (matcher.find()) {
            return "Found a match!";
        }
        return "Not matched!";
    }

    // Per Item 12 ("Always override toString"): even though this helper class is
    // used statically, any class that represents real data should expose its
    // interesting state through toString() so logging/debugging output is useful,
    // e.g. "TextMatchWordzMiddle[pattern=\b\w+z\w+\b]" instead of
