class RemoveOdd {
    /**
     * * Write a function to remove odd characters in a string.
     *
     * Returns the subsequence of {@code str1} consisting of all characters
     * located at ODD zero-based positions (indices 1, 3, 5, ...).
     * Every character at an even position (0, 2, 4, ...) is removed.
     *
     * The returned string contains exactly floor(length/2) characters;
     * if the input length is n, the kept indices are 1, 3, ..., 2*floor((n-1)/2)+1.
     * An empty input (or a null input) yields an empty string "".
     *
     * Examples:
     * > removeOdd("python")   -> "yhn"
     * > removeOdd("program")  -> "rga"
     * > removeOdd("language") -> "agae"
     *
     * @param str1 the source string; may be null (treated as "")
     * @return the string formed by the characters at odd indices, never null
     */
    public static String removeOdd(String str1) {
        // Guard: null input behaves like the empty string.
        if (str1 == null) {
            return "";
        }

        int n = str1.length();
        StringBuilder sb = new StringBuilder(n / 2);

        // Keep only characters at odd (1-based-looking) zero-based indices.
        for (int i = 1; i < n; i += 2) {
            sb.append(str1.charAt(i));
        }

        return sb.toString();
    }
}

