class TextMatchWordzMiddle {
    /**
     * Matches a word containing 'z', not at the start or end of the word.
     *
     * The regular expression used is:
     *   \b \w+ z \w+ \b
     *   --- -- - -- ---
     *   |   |  | |  |  word boundary (end of word)
     *   |   |  | |  at least one char AFTER  z  -> z is not last
     *   |   |  | at least one char BEFORE  z   -> z is not first
     *   |   |  the literal letter 'z'
     *   |   at least one word char before 'z'
     *   word boundary (start of word)
     *
     * NOTE: the exact wording of the returned strings is part of this
     * class's contract ("Found a match!" / "Not matched!"); callers that
     * need the actual matching word should use {@link #findMatchedWord(String)}
     * instead of parsing this string.
     */
    private static final Pattern PATTERN_Z_IN_MIDDLE = Pattern.compile("\\b\\w+z\\w+\\b");

    public static String textMatchWordzMiddle(String text) {
        if (text == null) {
            return "Not matched!";
        }
        Matcher matcher = PATTERN_Z_IN_MIDDLE.matcher(text);
        return matcher.find() ? "Found a match!" : "Not matched!";
    }

    /**
     * Programmatic accessor for the information described above:
     * returns the first word that contains a 'z' which is neither at the
     * start nor at the end of the word, or null if there is none.
     * (Item 12: never force callers to parse the toString/label string.)
     */
    public static String findMatchedWord(String text) {
        if (text == null) {
            return null;
        }
        Matcher matcher = PATTERN_Z_IN_MIDDLE.matcher(text);
        return matcher.find() ? matcher.group() : null;
    }

    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));      // Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));    // Not matched!

        // extra sanity checks
        System.out.println(textMatchWordzMiddle("zabc def"));     // Not matched! (z first)
        System.out.println(textMatchWordzMiddle("abcz def"));     // Not matched! (z last)
        System.out.println(textMatchWordzMiddle("a bczd e"));     // Found a match!
        System.out.println(findMatchedWord("hello worzd yes"));   // worzd
    }
}

