class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // DP table: dp[i][j] = max sum to reach cell (i, j)
        int[][] dp = new int[n][n];
        dp[0][0] = cost.get(0).get(0);

        // Fill first column (only reachable from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill first row (only reachable from left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill rest: max from top or left, plus current cell value
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1])
                           + cost.get(i).get(j);
            }
        }

        // Path length is always (2n - 1); average = maxSum / pathLength
        double pathLength = 2.0 * n - 1;
        return dp[n - 1][n - 1] / pathLength;
    }

    /**
     * Returns a brief description of this class instance for debugging purposes.
     * The exact details of the representation are unspecified and subject to change,
     * but the following may be regarded as typical:
     *
     * "[Maxaverageofpath]"
     */
    @Override
    public String toString() {
        return "[Maxaverageofpath]";
    }
}

