class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        if (n <= 0) {
            return 0.0;
        }

        // Every top-left -> bottom-right path (only right/down moves) has 2n-1 cells,
        // so maximizing the average is the same as maximizing the total sum.
        int[][] dp = new int[n][n];

        // Base cases: first column (only downward moves) and first row (only rightward moves)
        dp[0][0] = cost.get(0).get(0);
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the rest: come either from above or from the left, whichever gives the larger sum
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
            }
        }

        double maxSum = dp[n - 1][n - 1];
        double pathLength = 2.0 * n - 1.0;

        return maxSum / pathLength;
    }

    public static void main(String[] args) {
        List<List<Integer>> m1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9));
        System.out.println(maxaverageofpath(m1, 3));   // 5.2

        List<List<Integer>> m2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10));
        System.out.println(maxaverageofpath(m2, 3));   // 6.2

        List<List<Integer>> m3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11));
        System.out.println(maxaverageofpath(m3, 3));   // 7.2
    }
}

public static int countVowels(String testStr) {
        int count = 0;
        String vowels = "aeiouAEIOU";
        for (int i = 0; i < testStr.length(); i++) {
            char c = testStr.charAt(i);
