class CountVowels {
    /**
     * * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        // Nothing to scan: null / empty / single character (no neighbours possible)
        if (testStr == null || testStr.length() < 2) {
            return 0;
        }

        final String VOWELS = "aeiouAEIOU";
        int n = testStr.length();
        int count = 0;

        for (int i = 0; i < n; i++) {
            char c = testStr.charAt(i);

            // A vowel itself is never counted - only its non-vowel neighbours are.
            if (VOWELS.indexOf(c) >= 0) {
                continue;
            }

            // Check the left neighbour (exists only when i > 0)
            boolean leftIsVowel  = (i > 0)     && (VOWELS.indexOf(testStr.charAt(i - 1)) >= 0);
            // Check the right neighbour (exists only when i < n-1)
            boolean rightIsVowel = (i < n - 1) && (VOWELS.indexOf(testStr.charAt(i + 1)) >= 0);

            if (leftIsVowel || rightIsVowel) {
                count++;   // counted at most once, even if both sides are vowels
            }
        }

        return count;
    }
}

