class CountVowels {
    /**
     * * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */

    /** Returns true if the given character is one of a, e, i, o, u (case insensitive). */
    private static boolean isVowel(char c) {
        c = Character.toLowerCase(c);
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }

    public static int countVowels(String testStr) {
        // Fewer than 2 characters => nobody has a neighbour.
        if (testStr == null || testStr.length() < 2) {
            return 0;
        }

        String s = testStr.toLowerCase();
        int n = s.length();
        int count = 0;

        for (int i = 0; i < n; i++) {
            char current = s.charAt(i);

            // Vowel characters themselves are not counted;
            // only consonants that stand next to a vowel are.
            if (isVowel(current)) {
                continue;
            }

            boolean leftIsVowel  = (i > 0)       && isVowel(s.charAt(i - 1));
            boolean rightIsVowel = (i < n - 1)   && isVowel(s.charAt(i + 1));

            if (leftIsVowel || rightIsVowel) {
                count++;          // found a qualifying character
            }
        }

        return count;
    }

    // --- quick self-test -------------------------------------------------
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend"));// 12
        System.out.println(countVowels("amazonprime"));             // 5
        System.out.println(countVowels(""));                        // 0
        System.out.println(countVowels("a"));                       // 0
        System.out.println(countVowels("ba"));                       // 1
    }
}

