class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Degenerate cases: nothing to average over
        if (cost == null || n <= 0 || cost.isEmpty() || cost.get(0).isEmpty()) {
            return 0.0;
        }

        // dp[i][j] = maximum sum of any path from (0,0) to (i,j) using only right/down moves
        long[][] dp = new long[n][n];

        dp[0][0] = cost.get(0).get(0);

        // First column: only reachable from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }
        // First row: only reachable from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the rest of the grid
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                long best = Math.max(dp[i - 1][j], dp[i][j - 1]);
                dp[i][j] = best + cost.get(i).get(j);
            }
        }

        // Every such path visits exactly (2n - 1) cells,
        // so the maximum average = (maximum sum) / (2n - 1)
        int steps = 2 * n - 1;

        return dp[n - 1][n - 1] / (double) steps;
    }
}

