        // z    -> the letter we are looking for
        // \w+  -> at least one char after 'z'   ('z' is not at the end)
        // \b   -> end of the word
        Pattern pattern = Pattern.compile("\\b\\w+z\\w+\\b");
        Matcher matcher = pattern.matcher(text);
        return matcher.find() ? "Found a match!" : "Not matched!";
    }
}

public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
    double[][] dp = new double[n][n];
    dp[0][0] = cost.get(0).get(0);

    // Fill first column (only reachable from above)
    for (int i = 1; i < n; i++) {
        dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
    }

    // Fill first row (only reachable from left)
    for (int j = 1; j < n; j++) {
        dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
    }

    // Fill remaining cells: come from above or left, pick the larger sum
    for (int i = 1; i < n; i++) {
        for (int j = 1; j < n; j++) {
            dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
        }
    }

    // All paths have length 2n-1, so average = maxSum / (2n-1)
    return dp[n - 1][n - 1] / (2.0 * n - 1);
}

