import java.util.regex.Pattern;
import java.util.regex.Matcher;

class TextMatchWordzMiddle {

    /**
     * Matches a word containing 'z', not at the start or end of the word.
     * (?<=\w) : there must be a word character right before the 'z'
     * z       : the literal letter to locate
     * (?=\w)  : there must be a word character right after the 'z'
     * Because both neighbours must be word characters, the 'z' can never
     * be the first or the last character of a word.
     */
    private static final Pattern Z_IN_MIDDLE =
            Pattern.compile("(?<=\\w)z(?=\\w)");

    private static final String FOUND = "Found a match!";
    private static final String NOT_FOUND = "Not matched!";

    /**
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null || text.isEmpty()) {
            return NOT_FOUND;
        }
        Matcher matcher = Z_IN_MIDDLE.matcher(text);
        return matcher.find() ? FOUND : NOT_FOUND;
    }

    // Demonstration / self-test
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));   // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));        // Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));      // Not matched!
        System.out.println(textMatchWordzMiddle("zabc"));           // Not matched! (z starts the word)
        System.out.println(textMatchWordzMiddle("abcz"));           // Not matched! (z ends the word)
        System.out.println(textMatchWordzMiddle("ab_z.cd"));        // Found a match!
        System.out.println(textMatchWordzMiddle("one two three"));  // Not matched!
    }
}

import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Degenerate case: nothing to average.
        if (cost == null || n <= 0 || cost.isEmpty()) {
            return 0.0;
        }

        // dp[i][j] = maximum sum of a top-left -> (i,j) path moving only right/down.
        // Kept local so no extra state is exposed outside this method (ITEM 15).
        int[][] dp = new int[n][n];

        dp[0][0] = cost.get(0).get(0);

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i == 0 && j == 0) {
                    continue; // already seeded
                }

                int fromTop  = (i > 0) ? dp[i - 1][j] : Integer.MIN_VALUE;
                int fromLeft = (j > 0) ? dp[i][j - 1] : Integer.MIN_VALUE;

                dp[i][j] = Math.max(fromTop, fromLeft) + cost.get(i).get(j);
            }
        }

        // Every path from (0,0) to (n-1,n-1) has exactly 2n-1 cells,
        // so the average is simply bestSum / (2n - 1).
        int steps = 2 * n - 1;
        return dp[n - 1][n - 1] / (double) steps;
    }
}

