class TextMatchWordzMiddle {
    /**
     * * Write a function that matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null) {
            return "Not matched!";
        }
        // \b  -> start of a word
        // \w+ -> at least one char BEFORE 'z'   (so 'z' is not the first letter)
        // z   -> the literal letter 'z'
        // \w+ -> at least one char AFTER  'z'   (so 'z' is not the last letter)
        // \b  -> end of the word                (keeps everything inside ONE word)
        Pattern pattern = Pattern.compile("\\b\\w+z\\w+\\b");
        Matcher matcher = pattern.matcher(text);

        if (matcher.find()) {
            return "Found a match!";
        }
        return "Not matched!";
    }

    // quick self-test
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));      // Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));    // Not matched!
        System.out.println(textMatchWordzMiddle("zabcz"));        // Not matched!
        System.out.println(textMatchWordzMiddle("azzb."));        // Found a match!
        System.out.println(textMatchWordzMiddle("abcz"));          // Not matched!
    }
}

public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        double[][] dp = new double[n][n];
        dp[0][0] = cost.get(0).get(0);

        // First row: only reachable from left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column: only reachable from top
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill rest: come from top or left, whichever gives larger sum
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // Path always has (2n - 1) cells; average = total sum / path length
        double totalLength = 2 * n - 1;
        return dp[n - 1][n - 1] / totalLength;
    }
}

public static int countVowels(String testStr) {
    if (testStr == null || testStr.length() < 2) return 0;

    String vowels = "aeiouAEIOU";
    int count = 0;

    for (int i = 0; i < testStr.length(); i++) {
        char ch = testStr.charAt(i);
        // Skip if current character is a vowel
        if (vowels.indexOf(ch) != -1) continue;

        boolean hasVowelNeighbor = false;
        // Check left neighbor
        if (i > 0 && vowels.indexOf(testStr.charAt(i - 1)) != -1) {
            hasVowelNeighbor = true;
        }
        // Check right neighbor
        if (i < testStr.length() - 1 && vowels.indexOf(testStr.charAt(i + 1)) != -1) {
            hasVowelNeighbor = true;
        }

        if (hasVowelNeighbor) count++;
    }

    return count;
}

