    public static String textMatchWordzMiddle(String text) {
        // Guard against null input so the invariant "text is a usable string" holds.
        if (text == null) {
            return "Not matched!";
        }

        // \Bz\B  ==  a word character immediately before z AND immediately after z,
        // which places 'z' strictly inside a word (never first, never last).
        // The lookaround form (?<=\w)z(?=\w) expresses exactly the same thing.
        Pattern pattern = Pattern.compile("\\Bz\\B");
        Matcher matcher = pattern.matcher(text);

        if (matcher.find()) {
            return "Found a match!";
        }
        return "Not matched!";
    }
}

