class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        if (cost == null || cost.isEmpty() || n <= 0) {
            return null;
        }

        // dp[i][j] holds the maximum sum of a path from (0,0) to (i,j)
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                long value = (cost.get(i).get(j) == null) ? 0L : cost.get(i).get(j).longValue();

                long best = 0L;
                boolean hasPrev = false;

                if (i > 0) {                 // coming from above
                    best = dp[i - 1][j];
                    hasPrev = true;
                }
                if (j > 0) {                 // coming from the left
                    long fromLeft = dp[i][j - 1];
                    if (!hasPrev || fromLeft > best) {
                        best = fromLeft;
                    }
                    hasPrev = true;
                }

                dp[i][j] = hasPrev ? (best + value) : value;
            }
        }

        // Every valid path visits exactly (2n - 1) cells, so maximizing the sum
        // maximizes the average.
        int pathLength = 2 * n - 1;
        double total = (double) dp[n - 1][n - 1];

        return total / pathLength;
    }
}

