     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        // (?<=\w)  : a word character must precede the 'z'  -> not at the START of the word
        // z        : the letter 'z'
        // \w+      : at least one word character must follow -> not at the END of the word
        Pattern pattern = Pattern.compile("(?<=\\w)z\\w+");
