class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Degenerate cases: empty matrix -> no path, average is undefined; report 0.0
        if (cost == null || cost.isEmpty() || n <= 0) {
            return 0.0;
        }

        // dp[i][j] = largest sum of any right/down path ending at cell (i, j).
        // A 'long' accumulator keeps large matrices free of integer overflow.
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                long bestPredecessor = 0;
                boolean hasPredecessor = false;

                if (i > 0) {                       // came from above
                    bestPredecessor = dp[i - 1][j];
                    hasPredecessor = true;
                }
                if (j > 0 && (!hasPredecessor || dp[i][j - 1] > bestPredecessor)) {
                    bestPredecessor = dp[i][j - 1]; // came from the left
                    hasPredecessor = true;
                }

                dp[i][j] = bestPredecessor + cost.get(i).get(j);
            }
        }

        // Every valid path visits exactly (2n - 1) cells, so the denominator is fixed:
        // maximizing the average is equivalent to maximizing the path sum.
        int pathLength = 2 * n - 1;
        return dp[n - 1][n - 1] / (double) pathLength;
    }

    // Simple driver to exercise the three documented examples.
    public static void main(String[] args) {
        List<List<Integer>> m1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9));
        List<List<Integer>> m2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10));
        List<List<Integer>> m3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11));

        System.out.println(maxaverageofpath(m1, 3)); // 5.2
        System.out.println(maxaverageofpath(m2, 3)); // 6.2
        System.out.println(maxaverageofpath(m3, 3)); // 7.2
    }
}

