class TextMatchWordzMiddle {

    /**
     * Compiled once: Pattern is immutable and thread-safe, so a single
     * shared instance can be reused freely (ITEM 17 - minimize mutability).
     * \w  -> any word character (letter, digit or '_') before 'z'
     * \w  -> any word character (letter, digit or '_') after  'z'
     * => 'z' sits strictly inside a word (not at its start, not at its end)
     */
    private static final Pattern Z_INSIDE_WORD = Pattern.compile("\\wz\\w");

    /**
     * * Write a function that matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }
        Matcher matcher = Z_INSIDE_WORD.matcher(text);
        return matcher.find() ? "Found a match!" : "Not matched!";
    }

    // quick self-check
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));     // Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));   // Not matched!
        System.out.println(textMatchWordzMiddle("zabc"));        // Not matched! ('z' at start)
        System.out.println(textMatchWordzMiddle("abcz"));        // Not matched! ('z' at end)
        System.out.println(textMatchWordzMiddle("a-z-b"));       // Not matched! (z not inside word)
        System.out.println(textMatchWordzMiddle("zebra zz z"));  // Found a match! ('zz')
    }
}

