     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        if (n == 0) return 0.0;
        if (n == 1) return (double) cost.get(0).get(0);

        // DP table for maximum sum path from (0,0) to (i,j)
        int[][] dp = new int[n][n];
        dp[0][0] = cost.get(0).get(0);

        // Fill first row (only reachable by going right)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill first column (only reachable by going down)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // Every path has exactly (2n - 1) cells
        int totalPathLength = 2 * n - 1;
        return (double) dp[n - 1][n - 1] / totalPathLength;
    }
}

