class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Degenerate input: nothing to average over
        if (n <= 0 || cost == null || cost.isEmpty()) {
            return 0.0;
        }

        // Every top-left -> bottom-right path (moves: right / down) visits exactly
        // (2n - 1) cells, so maximizing the average == maximizing the sum.
        // dp[i][j] = maximum sum achievable reaching cell (i, j).
        int[][] dp = new int[n][n];

        dp[0][0] = cost.get(0).get(0);

        // First row: only reachable from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column: only reachable from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Interior cells: come either from the top or from the left
        for (int i = 1; i < n; i++) {
            List<Integer> row = cost.get(i);
            for (int j = 1; j < n; j++) {
                int fromTop = dp[i - 1][j];
                int fromLeft = dp[i][j - 1];
                dp[i][j] = row.get(j) + (fromTop >= fromLeft ? fromTop : fromLeft);
            }
        }

        int maxSum = dp[n - 1][n - 1];
        int pathLength = 2 * n - 1;

        // Floating-point division: integer division would truncate (e.g. 26/5 -> 5)
        return (double) maxSum / (double) pathLength;
    }
}

