     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Guard against null input: treat it as "no match".
        if (text == null) {
            return "Not matched!";
        }

        // \b  : start of a word
        // \w+ : at least one word character BEFORE 'z'  -> z is not the first letter
        // z   : the literal letter we are looking for
        // \w+ : at least one word character AFTER 'z'   -> z is not the last letter
        // \b  : end of the word
        final Pattern pattern = Pattern.compile("\\b\\w+z\\w+\\b");
        final Matcher matcher = pattern.matcher(text);

        if (matcher.find()) {
            return "Found a match!";
        }
        return "Not matched!";
    }

    // Small self-test harness (optional, mirrors the examples above).
    public static void main(final String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));  // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));       // Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));     // Not matched!
        System.out.println(textMatchWordzMiddle("zabc"));          // Not matched! (z at start)
        System.out.println(textMatchWordzMiddle("abcz"));          // Not matched! (z at end)
        System.out.println(textMatchWordzMiddle("a_z_b"));         // Not matched! ('_' not a word break issue -> actually \w includes '_', so "a_z_b" matches)
    }
}

public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
    double[][] dp = new double[n][n];

    // Initialize base case
    dp[0][0] = cost.get(0).get(0);

    // Fill first row (can only come from left)
    for (int j = 1; j < n; j++) {
        dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
    }

    // Fill first column (can only come from top)
    for (int i = 1; i < n; i++) {
        dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
    }

    // Fill rest of the table
    for (int i = 1; i < n; i++) {
        for (int j = 1; j < n; j++) {
            dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
        }
    }

    // Every path visits exactly (2n - 1) cells
    int pathLength = 2 * n - 1;
    return dp[n - 1][n - 1] / pathLength;
}

