public static int newmanPrime(int n) {
    if (n <= 1) return 2;

    List<Integer> nswPrimes = new ArrayList<>();
    nswPrimes.add(2);

    long prev = 1;
    long curr = 1;

    while (nswPrimes.size() < n) {
        long next = 2 * curr + prev;
        prev = curr;
        curr = next;

        if (isPrime((int) curr)) {
            nswPrimes.add((int) curr);
        }
    }

    return nswPrimes.get(n - 1);
}

private static boolean isPrime(int num) {
    if (num < 2) return false;
    if (num == 2) return true;
    if (num % 2 == 0) return false;
    for (int i = 3; (long) i * i <= num; i += 2) {
        if (num % i == 0) return false;
    }
    return true;
}

