class CountVowels {
    /**
     * * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        // Guard against null / trivially short input
        if (testStr == null || testStr.length() < 2) {
            return 0;
        }

        int count = 0;
        int n = testStr.length();

        for (int i = 0; i < n; i++) {
            char current = testStr.charAt(i);

            // We only count characters that are NOT vowels themselves,
            // but that have a vowel as (at least one of) their neighbor(s).
            if (isVowel(current)) {
                continue;
            }

            boolean leftNeighborIsVowel  = (i > 0)     && isVowel(testStr.charAt(i - 1));
            boolean rightNeighborIsVowel = (i < n - 1)  && isVowel(testStr.charAt(i + 1));

            if (leftNeighborIsVowel || rightNeighborIsVowel) {
                count++;
            }
        }

        return count;
    }

    /** Returns true if the given character is one of a, e, i, o, u (case-insensitive). */
    private static boolean isVowel(char ch) {
        switch (Character.toLowerCase(ch)) {
            case 'a':
            case 'e':
            case 'i':
            case 'o':
            case 'u':
                return true;
            default:
                return false;
        }
    }

    // Quick self-test
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));           // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));              // 5
    }
}

