     *
     * > seriesSum(6)
     * 91
     * > seriesSum(7)
     * 140
     * > seriesSum(12)
     * 650
     */
    public static int seriesSum(int number) {
        // Empty series for non-positive inputs
        if (number <= 0) {
            return 0;
        }

        // Closed form: 1^2 + 2^2 + ... + n^2 = n*(n+1)*(2n+1)/6
        // Computed in long to avoid intermediate int overflow,
        // the division by 6 is always exact.
        long n = number;
        long total = n * (n + 1) * (2 * n + 1) / 6;

        return (int) total;
    }
}

