class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Degenerate case: empty matrix
        if (n <= 0 || cost == null || cost.isEmpty()) {
            return 0.0;
        }

        // dp[i][j] = maximum sum of any path from (0,0) to (i,j) moving only right/down
        int[][] dp = new int[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int current = cost.get(i).get(j);

                if (i == 0 && j == 0) {
                    // Starting cell
                    dp[i][j] = current;
                    continue;
                }

                int best = Integer.MIN_VALUE;

                // Come from the cell above (a down move)
                if (i > 0) {
                    best = Math.max(best, dp[i - 1][j]);
                }

                // Come from the cell to the left (a right move)
                if (j > 0) {
                    best = Math.max(best, dp[i][j - 1]);
                }

                dp[i][j] = best + current;
            }
        }

        // Every valid path contains exactly (2n - 1) cells,
        // so the path with the maximum sum also has the maximum average.
        int pathLength = 2 * n - 1;
        return dp[n - 1][n - 1] / (double) pathLength;
    }
}

