    // Dynamic programming: dp[i][j] = max sum path from (0,0) to (i,j)
    int[][] dp = new int[n][n];

    dp[0][0] = cost.get(0).get(0);

    // First row (only reachable from left)
    for (int j = 1; j < n; j++) {
        dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
    }

    // First column (only reachable from above)
    for (int i = 1; i < n; i++) {
        dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
    }

    // Fill rest: come from either above or left
    for (int i = 1; i < n; i++) {
        for (int j = 1; j < n; j++) {
            dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
        }
    }

    // Every path visits exactly (2*n - 1) cells, so average = maxSum / (2*n - 1)
    double maxSum = dp[n - 1][n - 1];
    int pathLength = 2 * n - 1;

    return maxSum / pathLength;
}

