final class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     *
     * Self-use pattern (documented): this class never invokes an overridable method
     * from within itself; every computation lives in the private static helpers below,
     * so overriding anything here can never alter the behaviour of another method.
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Public entry point only delegates; no self-use of overridable members.
        return computeMaxAverage(cost, n);
    }

    /**
     * Private helper: turns the maximised path sum into the required average.
     * Every path from (0,0) to (n-1,n-1) moving right/down has exactly 2n-1 cells,
     * hence average == maxSum / (2n-1).
     */
    private static Double computeMaxAverage(List<List<Integer>> cost, int n) {
        if (cost == null || cost.isEmpty() || n <= 0) {
            return 0.0;
        }
        if (n == 1) {                       // degenerate single-cell matrix
            return (double) cost.get(0).get(0);
        }
        double[][] maxSum = buildMaxPathSums(cost, n);
        int steps = 2 * n - 1;
        return maxSum[n - 1][n - 1] / steps;
    }

    /**
     * Private helper: classic DP for the maximum-sum monotone path.
     *   dp[0][0] = cost[0][0]
     *   dp[i][j] = cost[i][j] + max(dp[i-1][j], dp[i][j-1])
     */
    private static double[][] buildMaxPathSums(List<List<Integer>> cost, int n) {
        double[][] dp = new double[n][n];

        dp[0][0] = cost.get(0).get(0);

        // first row: can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // first column: can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // interior cells: best of "from above" vs "from the left"
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                double fromAbove = dp[i - 1][j];
                double fromLeft  = dp[i][j - 1];
                dp[i][j] = Math.max(fromAbove, fromLeft) + cost.get(i).get(j);
            }
        }
        return dp;
    }
}

