     */
    public static String textMatchWordzMiddle(String text) {
        // \B before z  -> there is a word character to the left of 'z' (not at word start)
        // \w* z \w*    -> the 'z' sits inside a run of word characters (same word)
        // \B after     -> there is a word character to the right of the 'z' (not at word end)
        Pattern pattern = Pattern.compile("\\B\\w*z\\w*\\B");

        if (text == null) {
            return "Not matched!";
        }

        Matcher matcher = pattern.matcher(text);
        if (matcher.find()) {
            return "Found a match!";
        }
        return "Not matched!";
    }

