/**
 * Contract of an indexed integer sequence.
 * An interface is preferred over an abstract class here (Effective Java, Item 20):
 * it leaves room to extend a class later and lets clients depend only on behaviour.
 */
interface IntSequence {

    /** Primitive operation: the element at zero-based index {@code n}. */
    int at(int n);

    /**
     * Skeletal/default implementation built on the single primitive method
     * {@link #at(int)} -- the Template Method pattern. Implementors inherit it for free.
     */
    default List<Integer> first(int count) {
        if (count < 0) {
            throw new IllegalArgumentException("count < 0: " + count);
        }
        List<Integer> values = new ArrayList<>(count);
        for (int i = 0; i < count; i++) {
            values.add(at(i));
        }
        return values;
    }
}

/**
 * Skeletal implementation of the Newman-Shanks-Williams recurrence,
 * named after the "AbstractInterface" convention (Item 20):
 *
 *     S(0) = 1, S(1) = 1, S(n) = 2*S(n-1) + S(n-2)
 *
 * The work of implementing {@link IntSequence} is done here once, so any client
 * (anonymous subclass, dedicated class, lambda-backed wrapper...) only has to exist.
 */
abstract class AbstractNewmanShanksWilliams implements IntSequence {

    @Override
    public int at(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("index must be non-negative: " + n);
        }
        if (n < 2) {
            return 1;                       // S(0) = S(1) = 1
        }
        long previous = 1;                  // S(i-2)
        long current = 1;                   // S(i-1)
        for (int i = 2; i <= n; i++) {      // linear, no exponential recursion
            long next = 2L * current + previous;
            previous = current;
            current = next;
        }
        return (int) current;               // int range holds for n <= 29
    }
}

class NewmanPrime {
