     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Concrete use of the skeletal implementation, expressed as an
        // anonymous class (Item 24) -- exactly like intArrayAsList(...) in Item 20.
        IntSequence nsw = new AbstractNewmanShanksWilliams() {
        };
        return nsw.at(n);
    }

    public static void main(String[] args) {
        System.out.println(newmanPrime(3));   // 7
        System.out.println(newmanPrime(4));   // 17
        System.out.println(newmanPrime(5));   // 41
        // Bonus: the inherited default skeletal method comes for free.
        System.out.println(
                new AbstractNewmanShanksWilliams() {}.first(6)); // [1, 1, 3, 7, 17, 41]
    }
}

