class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Degenerate input: no cells -> no path
        if (cost == null || n <= 0 || cost.isEmpty() || cost.get(0).isEmpty()) {
            return 0.0;
        }

        // Every top-left -> bottom-right path (only down/right moves)
        // traverses exactly (2n - 1) cells, so the number of cells is
        // constant across all paths.  Maximising the average therefore
        // reduces to maximising the total sum along the path.
        //
        //   dp[i][j] = cost[i][j] + max(dp[i-1][j], dp[i][j-1])
        //
        long[][] dp = new long[n][n];

        dp[0][0] = cost.get(0).get(0);

        // First column: can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // First row: can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the rest of the grid
        for (int i = 1; i < n; i++) {
            List<Integer> row = cost.get(i);
            for (int j = 1; j < n; j++) {
                long fromTop = dp[i - 1][j];
                long fromLeft = dp[i][j - 1];
                dp[i][j] = row.get(j) + Math.max(fromTop, fromLeft);
            }
        }

        long bestSum = dp[n - 1][n - 1];
        int cellsOnPath = 2 * n - 1;

        return ((double) bestSum) / cellsOnPath;
    }
}

