class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Degenerate input: no cells, nothing to average.
        if (cost == null || cost.isEmpty() || n <= 0) {
            return 0.0;
        }

        // dp[i][j] = maximum sum of any path from (0,0) to (i,j)
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                long incoming;
                if (i == 0 && j == 0) {
                    // Starting cell: no predecessor.
                    incoming = 0L;
                } else if (i == 0) {
                    // First row: can only come from the left.
                    incoming = dp[i][j - 1];
                } else if (j == 0) {
                    // First column: can only come from above.
                    incoming = dp[i - 1][j];
                } else {
                    // Otherwise: best of "from above" and "from left".
                    incoming = Math.max(dp[i - 1][j], dp[i][j - 1]);
                }
                dp[i][j] = incoming + cost.get(i).get(j);
            }
        }

        // Every admissible path contains exactly (2n - 1) cells,
        // so the average is maximized exactly when the sum is maximized.
        int cellsOnPath = 2 * n - 1;
        if (cellsOnPath <= 0) {
            return 0.0;
        }

        return (double) dp[n - 1][n - 1] / (double) cellsOnPath;
    }
}

