public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
    // dp[i][j] = maximum sum of any path from (0,0) to (i,j)
    long[][] dp = new long[n][n];

    dp[0][0] = cost.get(0).get(0);

    // Fill first column (only can come from above)
    for (int i = 1; i < n; i++) {
        dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
    }

    // Fill first row (only can come from left)
    for (int j = 1; j < n; j++) {
        dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
    }

    // Fill rest: come from top or left, whichever gives larger sum
    for (int i = 1; i < n; i++) {
        for (int j = 1; j < n; j++) {
            dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
        }
    }

    // Every path visits exactly (2n - 1) cells
    int pathLength = 2 * n - 1;
    return (double) dp[n - 1][n - 1] / pathLength;
}

