class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */

    private static boolean isPrime(int n) {
        if (n < 2) return false;
        if (n == 2) return true;
        if (n % 2 == 0) return false;
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) return false;
        }
        return true;
    }

    public static int newmanPrime(int n) {
        List<Integer> primes = new ArrayList<>();
        primes.add(2); // 1st NSW prime

        int s0 = 1, s1 = 3; // S(1)=1, S(2)=3

        if (isPrime(s0)) primes.add(s0);
        if (isPrime(s1)) primes.add(s1);

        while (primes.size() < n) {
            int s2 = 2 * s1 + s0;
            s0 = s1;
            s1 = s2;
            if (isPrime(s1)) primes.add(s1);
        }

        return primes.get(n - 1);
    }
}

