class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Degenerate case: single cell, the only "path" is that cell itself.
        if (n <= 1) {
            return cost.get(0).get(0).doubleValue();
        }

        // dp[i][j] = maximum sum of any right/down path ending at cell (i, j).
        int[][] dp = new int[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int cellValue = cost.get(i).get(j);

                if (i == 0 && j == 0) {
                    dp[i][j] = cellValue;
                    continue;
                }

                int bestPredecessor = Integer.MIN_VALUE;
                if (i > 0) {
                    bestPredecessor = Math.max(bestPredecessor, dp[i - 1][j]);
                }
                if (j > 0) {
                    bestPredecessor = Math.max(bestPredecessor, dp[i][j - 1]);
                }

                dp[i][j] = bestPredecessor + cellValue;
            }
        }

        // Every valid path contains exactly (2n - 1) cells,
        // so maximizing the average == maximizing the sum.
        double maxSum = dp[n - 1][n - 1];
        double pathLength = 2.0 * n - 1.0;

        return maxSum / pathLength;
    }
}

