        for (int j = 0; j < n; j++) {
            if (i == 0 && j == 0) continue;
            double fromTop = (i > 0) ? dp[i - 1][j] : -1;
            double fromLeft = (j > 0) ? dp[i][j - 1] : -1;
            dp[i][j] = Math.max(fromTop, fromLeft) + cost.get(i).get(j);
        }
    }

    return dp[n - 1][n - 1] / (2 * n - 1);
}

