class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Every path from (0,0) to (n-1,n-1) moving only right/down has
        // exactly (2n - 1) cells, so maximizing the average == maximizing the sum.
        List<List<Long>> dp = new ArrayList<List<Long>>(n);
        for (int i = 0; i < n; i++) {
            List<Long> row = new ArrayList<Long>(n);
            for (int j = 0; j < n; j++) {
                row.add(0L);
            }
            dp.add(row);
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                long cell = (long) cost.get(i).get(j);
                if (i == 0 && j == 0) {
                    dp.get(i).set(j, cell);
                } else if (i == 0) {
                    dp.get(i).set(j, cell + dp.get(i).get(j - 1));
                } else if (j == 0) {
                    dp.get(i).set(j, cell + dp.get(i - 1).get(j));
                } else {
                    long best = Math.max(dp.get(i - 1).get(j), dp.get(i).get(j - 1));
                    dp.get(i).set(j, cell + best);
                }
            }
        }

        double maxSum = (double) dp.get(n - 1).get(n - 1);
        int pathLength = 2 * n - 1;
        return Double.valueOf(maxSum / pathLength);
    }
}

