public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
    // dp[i][j] stores the maximum sum path from (0,0) to (i,j)
    int[][] dp = new int[n][n];

    // Base cases
    dp[0][0] = cost.get(0).get(0);

    // First row: can only come from the left
    for (int j = 1; j < n; j++) {
        dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
    }

    // First column: can only come from above
    for (int i = 1; i < n; i++) {
        dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
    }

    // Fill rest of the table
    for (int i = 1; i < n; i++) {
        for (int j = 1; j < n; j++) {
            dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
        }
    }

    // Every path from (0,0) to (n-1,n-1) visits exactly (2n-1) cells
    int totalSteps = 2 * n - 1;

    return dp[n - 1][n - 1] / (double) totalSteps;
}

