class SeriesSum {
    /**
     * * Write a function to calculate the sum of series 1²+2²+3²+….+n².
     *
     * > seriesSum(6)
     * 91
     * > seriesSum(7)
     * 140
     * > seriesSum(12)
     * 650
     */
    public static int seriesSum(int number) {
        // Empty (or undefined) series contributes nothing.
        if (number <= 0) {
            return 0;
        }

        // Closed form of 1^2 + 2^2 + ... + n^2 = n(n+1)(2n+1)/6
        // Computed in long so the intermediate product n*(n+1)*(2n+1)
        // does not overflow before the division by 6.
        long n = number;
        long sum = n * (n + 1) * (2 * n + 1) / 6;

        return (int) sum;
    }
}

