        // \b  \w+   \B   z   \w+   \b
        //  |    |    |   |    |    |
        // word start, >=1 char before 'z', still inside the word,
        // the 'z', >=1 char after 'z', word end
        Pattern pattern = Pattern.compile("\\b\\w+\\Bz\\w+\\b");
