     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null) {
            return "Not matched!";
        }
        Matcher matcher = Z_IN_MIDDLE.matcher(text);
        if (matcher.find()) {
            return "Found a match!";
        }
        return "Not matched!";
    }
}

