class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Degenerate input: nothing to average.
        if (cost == null || n <= 0) {
            return Double.valueOf(0.0);
        }

        // dp[i][j] = maximum sum of a right/down-only path from (0,0) to (i,j).
        // Every such path visits exactly (2n - 1) cells, so maximizing the sum
        // is identical to maximizing the average.
        int[][] dp = new int[n][n];

        dp[0][0] = cost.get(0).get(0);

        // First row: only reachable from the left.
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column: only reachable from above; interior cells: max of both.
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
            }
        }

        int pathLength = 2 * n - 1;                 // number of cells on every path
        double bestSum = (double) dp[n - 1][n - 1]; // widen before dividing to avoid integer truncation
        return Double.valueOf(bestSum / pathLength);
    }

    // ---------------------------------------------------------------------
    // Simple self-test harness
    // ---------------------------------------------------------------------
    private static List<List<Integer>> toMatrix(int[] flat, int n) {
        List<List<Integer>> m = new ArrayList<List<Integer>>(n);
        for (int i = 0; i < n; i++) {
            List<Integer> row = new ArrayList<Integer>(n);
            for (int j = 0; j < n; j++) {
                row.add(Integer.valueOf(flat[i * n + j]));
            }
            m.add(row);
        }
        return m;
    }

    public static void main(String[] args) {
        System.out.println(maxaverageofpath(toMatrix(new int[]{1, 2, 3, 6, 5, 4, 7, 3, 9}, 3), 3)); // 5.2
        System.out.println(maxaverageofpath(toMatrix(new int[]{2, 3, 4, 7, 6, 5, 8, 4, 10}, 3), 3)); // 6.2
        System.out.println(maxaverageofpath(toMatrix(new int[]{3, 4, 5, 8, 7, 6, 9, 5, 11}, 3), 3)); // 7.2
    }
}

