public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
    // dp[i][j] = maximum sum of path from (0,0) to (i,j)
    List<List<Integer>> dp = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        dp.add(new ArrayList<>());
        for (int j = 0; j < n; j++) {
            dp.get(i).add(0);
        }
    }

    dp.get(0).set(0, cost.get(0).get(0));

    // Fill first row (only reachable from left)
    for (int j = 1; j < n; j++) {
        dp.get(0).set(j, dp.get(0).get(j - 1) + cost.get(0).get(j));
    }

    // Fill first column (only reachable from top)
    for (int i = 1; i < n; i++) {
        dp.get(i).set(0, dp.get(i - 1).get(0) + cost.get(i).get(0));
    }

    // Fill rest of the table
    for (int i = 1; i < n; i++) {
        for (int j = 1; j < n; j++) {
            int fromTop = dp.get(i - 1).get(j);
            int fromLeft = dp.get(i).get(j - 1);
            dp.get(i).set(j, cost.get(i).get(j) + Math.max(fromTop, fromLeft));
        }
    }

    // Every path has exactly (2n - 1) elements
    int totalSteps = 2 * n - 1;
    double maxSum = dp.get(n - 1).get(n - 1);
    return maxSum / totalSteps;
}

