    public static String textMatchWordzMiddle(String text) {
        // Pattern: \b\w+z\w+\b
        // - \b         : word boundary (start of a word)
        // - \w+        : one or more word chars BEFORE 'z' (ensures z is not at start)
        // - z          : literal 'z'
