    // Fill first column (only reachable from above)
    for (int i = 1; i < n; i++) {
        dp[i][0] = dp[i - 1].length > 0 ? dp[i - 1][0] + cost.get(i).get(0) : 0;
    }

    // Fill rest of the table
    for (int i = 1; i < n; i++) {
