public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
    // DP table: dp[i][j] = max sum to reach cell (i,j)
    List<List<Double>> dp = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        List<Double> row = new ArrayList<>();
        for (int j = 0; j < n; j++) {
            row.add(0.0);
        }
        dp.add(row);
    }

    // Base case
    dp.get(0).set(0, (double) cost.get(0).get(0));

    // Fill first column (only from above)
    for (int i = 1; i < n; i++) {
        dp.get(i).set(0, dp.get(i - 1).get(0) + cost.get(i).get(0));
    }

    // Fill first row (only from left)
    for (int j = 1; j < n; j++) {
        dp.get(0).set(j, dp.get(0).get(j - 1) + cost.get(0).get(j));
    }

    // Fill rest of the table
    for (int i = 1; i < n; i++) {
        for (int j = 1; j < n; j++) {
            double fromAbove = dp.get(i - 1).get(j);
            double fromLeft = dp.get(i).get(j - 1);
            double best = Math.max(fromAbove, fromLeft);
            dp.get(i).set(j, best + cost.get(i).get(j));
        }
    }

    // Every path from (0,0) to (n-1,n-1) visits exactly 2n-1 cells
    double totalSum = dp.get(n - 1).get(n - 1);
    double pathLength = 2.0 * n - 1;

    return totalSum / pathLength;
}

