class CountVowels {

    /* Prefer a List over an array (Item 28): no array covariance,
       no unchecked casts, and a clean contains() lookup. */
    private static final List<Character> VOWELS =
            Collections.unmodifiableList(Arrays.asList('a', 'e', 'i', 'o', 'u'));

    private static boolean isVowel(char ch) {
        return VOWELS.contains(Character.toLowerCase(ch));
    }

    /**
     * * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        if (testStr == null) {
            return 0;
        }
        int n = testStr.length();
        int count = 0;

        for (int i = 0; i < n; i++) {
            char cur = testStr.charAt(i);

            // Only consonant-like characters are candidates for counting.
            if (isVowel(cur)) {
                continue;
            }

            boolean leftIsVowel  = (i > 0)      && isVowel(testStr.charAt(i - 1));
            boolean rightIsVowel = (i < n - 1)  && isVowel(testStr.charAt(i + 1));

            if (leftIsVowel || rightIsVowel) {
                count++;
            }
        }
        return count;
    }

    // quick self-check
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));              // 5
        System.out.println(countVowels(""));                         // 0
        System.out.println(countVowels("xyz"));                      // 0
    }
}

