class CountVowels {
    /**
     * * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    private static final String VOWELS = "aeiou";

    public static int countVowels(String testStr) {
        // Guard clauses: nothing can have a neighbor in a null/short string
        if (testStr == null || testStr.length() < 2) {
            return 0;
        }

        String s = testStr.toLowerCase();
        int len = s.length();
        int count = 0;

        for (int i = 0; i < len; i++) {
            char current = s.charAt(i);

            // Only consonants are candidates; vowels themselves are not counted
            if (VOWELS.indexOf(current) != -1) {
                continue;
            }

            // Look at the left neighbor (if it exists)
            boolean leftIsVowel = (i > 0) && (VOWELS.indexOf(s.charAt(i - 1)) != -1);

            // Look at the right neighbor (if it exists)
            boolean rightIsVowel = (i < len - 1) && (VOWELS.indexOf(s.charAt(i + 1)) != -1);

            if (leftIsVowel || rightIsVowel) {
                count++;
            }
        }

        return count;
    }
}

