class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // NSW numbers: S0 = 1, S1 = 1, Sn = 2*S(n-1) + S(n-2)
        //   -> 1, 1, 3, 7, 17, 41, 99, 239, ...
        if (n < 1) {
            return 0;              // undefined for non-positive index
        }

        long prev = 1;             // S0
        long curr = 1;             // S1

        for (int i = 2; i <= n; i++) {
            long next = 2L * curr + prev;   // exact integer recurrence
            prev = curr;
            curr = next;
        }

        return (int) curr;
    }

    // quick self-test
    public static void main(String[] args) {
        System.out.println(newmanPrime(3));  // 7
        System.out.println(newmanPrime(4));  // 17
        System.out.println(newmanPrime(5));  // 41
        System.out.println(newmanPrime(1));  // 1
        System.out.println(newmanPrime(2));  // 3
        System.out.println(newmanPrime(6));  // 99
        System.out.println(newmanPrime(7));  // 239
    }
}

