class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n <= 0) return 0;

        int count = 0;

        // 2 is the first NSWP prime
        count++;
        if (count == n) return 2;

        // Generate terms of recurrence a(k) = 2*a(k-1) + a(k-2), a(0)=1, a(1)=1
        int a = 1, b = 1;
        while (true) {
            int c = 2 * b + a;
            a = b;
            b = c;
            if (isPrime(c)) {
                count++;
                if (count == n) return c;
            }
        }
    }

    private static boolean isPrime(int num) {
        if (num < 2) return false;
        if (num == 2) return true;
        if (num % 2 == 0) return false;
        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) return false;
        }
        return true;
    }
}

