    for (int i = 0; i < len; i++) {
        char c = testStr.charAt(i);
        // Only consider non-vowel characters
        if (vowels.indexOf(c) != -1) continue;

        boolean hasVowelNeighbor = false;
        // Check left neighbor
        if (i > 0 && vowels.indexOf(testStr.charAt(i - 1)) != -1) {
            hasVowelNeighbor = true;
        }
        // Check right neighbor
        if (i < len - 1 && vowels.indexOf(testStr.charAt(i + 1)) != -1) {
            hasVowelNeighbor = true;
        }

        if (hasVowelNeighbor) count++;
    }

    return count;
}

