     */
    public static int lenLog(List<String> list1) {
        if (list1 == null || list1.isEmpty()) {
            return 0;
        }

        // Use Collections.max with a comparator to find the longest word,
        // leveraging generic method support from the standard library
        String longestWord = Collections.max(list1, new Comparator<String>() {
            @Override
