import java.lang.*;
import java.util.*;
import java.math.*;


class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths
     * for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Degenerate input: nothing to average
        if (cost == null || cost.isEmpty() || n <= 0) {
            return 0.0;
        }

        // dp[i][j] = maximum sum of any right/down path from (0,0) to (i,j)
        int[][] dp = new int[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int current = cost.get(i).get(j);

                if (i == 0 && j == 0) {
                    dp[i][j] = current;                       // start cell
                } else if (i == 0) {
                    dp[i][j] = dp[i][j - 1] + current;        // first row: only from left
                } else if (j == 0) {
                    dp[i][j] = dp[i - 1][j] + current;        // first column: only from above
                } else {
                    // both predecessors exist -> take the better one
                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + current;
                }
            }
        }

        // Every valid top-left -> bottom-right path visits exactly (2n - 1) cells,
        // so maximizing the sum is the same as maximizing the average.
        double bestSum = dp[n - 1][n - 1];
        double pathLength = 2.0 * n - 1.0;

        return bestSum / pathLength;
    }

    // Quick self-test exercising the three documented examples
    public static void main(String[] args) {
        System.out.println(maxaverageofpath(
                Arrays.asList(Arrays.asList(1, 2, 3),
                              Arrays.asList(6, 5, 4),
                              Arrays.asList(7, 3, 9)), 3));   // 5.2

        System.out.println(maxaverageofpath(
                Arrays.asList(Arrays.asList(2, 3, 4),
                              Arrays.asList(7, 6, 5),
                              Arrays.asList(8, 4, 10)), 3));  // 6.2

        System.out.println(maxaverageofpath(
                Arrays.asList(Arrays.asList(3, 4, 5),
                              Arrays.asList(8, 7, 6),
                              Arrays.asList(9, 5, 11)), 3));   // 7.2
    }
}

