import java.util.*;
import java.math.*;


class TextMatchWordzMiddle {

    /** Words are maximal runs of word characters (letters, digits, '_'). */
    private static final Pattern WORD_PATTERN = Pattern.compile("\\w+");

    /**
     * Write a function that matches a word containing 'z',
     * not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null) {
            return "Not matched!";
        }
        Matcher matcher = WORD_PATTERN.matcher(text);
        while (matcher.find()) {
            if (hasInnerZ(matcher.group())) {
                return "Found a match!";
            }
        }
        return "Not matched!";
    }

    /**
     * True iff the word contains 'z' with at least one character
     * before and one character after it.
     *
     * Bounded type parameter (<T extends CharSequence>) keeps the API
     * flexible: String, StringBuilder, StringBuffer, ... all work,
     * with zero copying.
     */
    private static <T extends CharSequence> boolean hasInnerZ(T word) {
        int len = word.length();
        for (int i = 1; i < len - 1; i++) {   // skip first and last positions
            if (word.charAt(i) == 'z') {
                return true;
            }
        }
        return false;
    }

    /**
     * Extra (bounded-wildcard flavour): check a whole batch of candidates
     * at once — Iterable<? extends CharSequence> accepts List<String>,
     * List<StringBuilder>, List<CharSequence>, ...
     */
    public static boolean anyWordHasInnerZ(Iterable<? extends CharSequence> words) {
        for (CharSequence w : words) {
            if (hasInnerZ(w)) {
                return true;
            }
        }
        return false;
    }
}

import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<? extends List<? extends Integer>> cost, int n) {
        // dp[i][j] = maximum sum to reach cell (i, j) moving only right or down
        long[][] dp = new long[n][n];

        dp[0][0] = cost.get(0).get(0);

        // Fill first row (only reachable by moving right)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill first column (only reachable by moving down)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // Every path from (0,0) to (n-1,n-1) has exactly (2n-1) cells,
        // so average = total_sum / (2n - 1)
        double average = (double) dp[n - 1][n - 1] / (2 * n - 1);
        return average;
