     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null) {
            return "Not matched!";
        }
        // \w+ before 'z'  -> 'z' is NOT at the start of the word
        // \w+ after  'z'  -> 'z' is NOT at the end   of the word
        // \w never crosses whitespace/punctuation, so the whole match stays inside one word.
        Pattern pattern = Pattern.compile("\\w+z\\w+");
        Matcher matcher = pattern.matcher(text);

        if (matcher.find()) {
            return "Found a match!";
        }
        return "Not matched!";
    }

    // Quick self-test
