class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        TreeSet<Integer> allPrimes = new TreeSet<>();

        // First NSW sequence: 2, 7, 41, 239, 1393, ...
        long a = 2, b = 7;
        if (isPrime(a)) allPrimes.add((int) a);
        if (isPrime(b)) allPrimes.add((int) b);
        for (int i = 0; i < 60; i++) {
            long next = 6L * b - a;
            if (next > Integer.MAX_VALUE || next < 0) break;
            a = b; b = next;
            if (isPrime(b)) allPrimes.add((int) b);
        }

        // Second NSW sequence: 1, 3, 17, 99, 577, ...
        a = 1; b = 3;
        if (isPrime(a)) allPrimes.add((int) a);
        if (isPrime(b)) allPrimes.add((int) b);
        for (int i = 0; i < 60; i++) {
            long next = 6L * b - a;
            if (next > Integer.MAX_VALUE || next < 0) break;
            a = b; b = next;
            if (isPrime(b)) allPrimes.add((int) b);
        }

        // Pick the nth prime from the merged, sorted set
        int count = 1;
        for (int p : allPrimes) {
            if (count == n) return p;
            count++;
        }
        return -1;
    }

    private static boolean isPrime(long n) {
        if (n < 2) return false;
        if (n < 4) return true;
        if (n % 2 == 0 || n % 3 == 0) return false;
        for (long i = 5; i * i <= n; i += 6) {
            if (n % i == 0 || n % (i + 2) == 0) return false;
        }
        return true;
    }
}

