class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Closed form: f(n) = ((1+sqrt(2))^n + (1-sqrt(2))^n) / 2
        // which satisfies the exact integer recurrence
        //     f(n) = 2*f(n-1) + f(n-2),   f(1) = 1, f(2) = 3
        // Sequence: 1, 3, 7, 17, 41, 99, 239, 577, 1393, ...
        // (odd-indexed terms are the Newman-Shanks-Willams numbers 1, 7, 41, 239, ...)
        // The recurrence is used instead of floating point so the result is exact.

        if (n <= 1) {
            return 1;                       // f(0) = f(1) = 1
        }
        if (n == 2) {
            return 3;                       // f(2) = 3
        }

        long prevPrev = 1L;                 // f(n-2)
        long prev     = 3L;                 // f(n-1)  == f(2)

        for (int i = 3; i <= n; i++) {
            long cur = 2L * prev + prevPrev; // f(i) = 2*f(i-1) + f(i-2)
            prevPrev = prev;
            prev = cur;
        }

        return (int) prev;
    }
}

