class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        if (n <= 0) {
            return 0.0;
        }

        // dp[i][j] = maximum sum of any path from (0,0) to (i,j)
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                long val = cost.get(i).get(j);
                long best = Long.MIN_VALUE;

                if (i == 0 && j == 0) {
                    best = 0L;                       // starting cell
                } else if (i == 0) {
                    best = dp[i][j - 1];             // only from the left
                } else if (j == 0) {
                    best = dp[i - 1][j];             // only from above
                } else {
                    best = Math.max(dp[i - 1][j], dp[i][j - 1]);
                }

                dp[i][j] = val + best;
            }
        }

        // Every path from (0,0) to (n-1,n-1) visits exactly 2n-1 cells,
        // so maximizing the average == maximizing the sum.
        int pathLength = 2 * n - 1;
        double total = (double) dp[n - 1][n - 1];
        double average = total / pathLength;

        // Round to one decimal place as shown in the examples
        return Math.round(average * 10.0) / 10.0;
    }
}

