class CountAlphaDigSpl {
    /**
     * * Write a function to count alphabets,digits and special charactes in a given string.
     *
     * > countAlphaDigSpl("abc!@#123")
     * [3, 3, 3]
     * > countAlphaDigSpl("dgsuy@#$%&1255")
     * [5, 4, 5]
     * > countAlphaDigSpl("fjdsif627348#%$^&")
     * [6, 6, 5]
     */
    public static List<Integer> countAlphaDigSpl(String string) {
        int alpha = 0;   // alphabetic characters
        int digit = 0;   // numeric characters
        int special = 0; // everything else

        if (string != null) {
            for (int i = 0; i < string.length(); i++) {
                char ch = string.charAt(i);
                if (Character.isLetter(ch)) {
                    alpha++;
                } else if (Character.isDigit(ch)) {
                    digit++;
                } else {
                    special++;
                }
            }
        }

        // Type-safe assembly: List.of is @SafeVarargs annotated, so the
        // compiler can prove this construction is safe -- no arrays, no
        // unchecked cast, no @SafeVarargs needed here.
        return List.of(alpha, digit, special);
    }

    // Quick self-check of the documented examples
    public static void main(String[] args) {
        System.out.println(countAlphaDigSpl("abc!@#123"));           // [3, 3, 3]
        System.out.println(countAlphaDigSpl("dgsuy@#$%&1255"));      // [5, 4, 5]
        System.out.println(countAlphaDigSpl("fjdsif627348#%$^&"));   // [6, 6, 5]
    }
}

