class CountVowels {
    /**
     * * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        int len = testStr.length();
        int count = 0;

        for (int i = 0; i < len; i++) {
            char current = Character.toLowerCase(testStr.charAt(i));

            // A vowel itself is never counted: only its consonant neighbours are.
            if (isVowel(current)) {
                continue;
            }

            boolean leftIsVowel  = (i > 0)          && isVowel(Character.toLowerCase(testStr.charAt(i - 1)));
            boolean rightIsVowel = (i < len - 1)    && isVowel(Character.toLowerCase(testStr.charAt(i + 1)));

            if (leftIsVowel || rightIsVowel) {
                count++;   // this character has a vowel as a neighbour
            }
        }

        return count;
    }

    /** Single source of truth for "what is a vowel" ('y' is treated as a consonant). */
    private static boolean isVowel(char c) {
        switch (c) {
            case 'a': case 'e': case 'i': case 'o': case 'u':
                return true;
            default:
                return false;
        }
    }
}

