import java.lang.*;
import java.util.*;
import java.math.*;


class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        if (n <= 0 || cost == null || cost.isEmpty()) {
            return 0.0;
        }

        // dp[i][j] = maximum sum of any path from (0,0) to (i,j) using only right/down moves
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            List<Integer> row = cost.get(i);
            for (int j = 0; j < n; j++) {
                int cur = (row != null && j < row.size()) ? row.get(j) : 0;

                if (i == 0 && j == 0) {
                    dp[i][j] = cur;
                    continue;
                }

                long best = Long.MIN_VALUE / 4;
                if (i > 0) {                       // come from above
                    best = Math.max(best, dp[i - 1][j]);
                }
                if (j > 0) {                       // come from the left
                    best = Math.max(best, dp[i][j - 1]);
                }
                dp[i][j] = best + cur;
            }
        }

        // Every path from top-left to bottom-right has exactly (2n - 1) cells,
        // so maximizing the sum is equivalent to maximizing the average.
        int pathLength = 2 * n - 1;
        return dp[n - 1][n - 1] / (double) pathLength;
    }

    public static void main(String[] args) {
        List<List<Integer>> m1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9));
        List<List<Integer>> m2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10));
        List<List<Integer>> m3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11));

        System.out.printf("%.1f%n", maxaverageofpath(m1, 3)); // 5.2
        System.out.printf("%.1f%n", maxaverageofpath(m2, 3)); // 6.2
        System.out.printf("%.1f%n", maxaverageofpath(m3, 3)); // 7.2
    }
}

public static int countVowels(String testStr) {
    int count = 0;
    String vowels = "aeiouAEIOU";
    int len = testStr.length();

    for (int i = 0; i < len; i++) {
        char c = testStr.charAt(i);
        // Skip if current character is a vowel
        if (vowels.indexOf(c) != -1) continue;

        boolean hasVowelNeighbor = false;
        // Check left neighbor
        if (i > 0 && vowels.indexOf(testStr.charAt(i - 1)) != -1) {
            hasVowelNeighbor = true;
        }
        // Check right neighbor
        if (i < len - 1 && vowels.indexOf(testStr.charAt(i + 1)) != -1) {
            hasVowelNeighbor = true;
        }

        if (hasVowelNeighbor) {
            count++;
        }
    }
    return count;
}

