class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n == 0) return 1;
        if (n == 1) return 1;
        int a = 1, b = 1;
        for (int i = 2; i <= n; i++) {
            int c = 2 * b + a;
            a = b;
            b = c;
        }
        return b;
    }
}

