class TextMatchWordzMiddle {
    /**
     * * Write a function that matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // \B  -> the match cannot start at a word boundary, so at least one
        //        word character precedes the 'z'  => 'z' is not the first char
        // \w* -> any leading word characters inside the word
        //  z  -> the letter we are looking for
        // \w* -> any trailing word characters inside the word
        // \B  -> the match cannot end at a word boundary, so at least one
        //        word character follows the 'z'    => 'z' is not the last char
        String regex = "\\B\\w*z\\w*\\B";

        Pattern pattern = Pattern.compile(regex);
        Matcher matcher = pattern.matcher(text);

        if (matcher.find()) {
            return "Found a match!";
        }
        return "Not matched!";
    }

    // --- quick self-test -------------------------------------------------
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));      // Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));    // Not matched!
        System.out.println(textMatchWordzMiddle("zabc."));        // Not matched!
        System.out.println(textMatchWordzMiddle("abcz."));        // Not matched!
        System.out.println(textMatchWordzMiddle("azb zz zz zzz"));// Found a match!
    }
}

import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Degenerate case: no cells -> no path.
        if (n <= 0 || cost == null || cost.isEmpty()) {
            return 0.0;
        }

        // dp[i][j] = maximum sum of any path from (0,0) to (i,j) moving only down/right.
        int[][] dp = new int[n][n];

        for (int i = 0; i < n; i++) {
            List<Integer> row = cost.get(i);
            for (int j = 0; j < n; j++) {
                int cell = row.get(j);

                if (i == 0 && j == 0) {
                    dp[i][j] = cell;
                    continue;
                }

                int fromTop   = (i > 0) ? dp[i - 1][j] : Integer.MIN_VALUE;
                int fromLeft  = (j > 0) ? dp[i][j - 1] : Integer.MIN_VALUE;

                // Pick the better predecessor and add the current cell.
                int best = Math.max(fromTop, fromLeft);
                if (best == Integer.MIN_VALUE) {
                    best = 0; // unreachable in practice for a well-formed matrix
                }
                dp[i][j] = best + cell;
            }
        }

        // Every path contains exactly (2n - 1) cells, so maximizing the sum
        // maximizes the average as well.
        int pathLength = 2 * n - 1;
        double total = dp[n - 1][n - 1];

        return total / pathLength;
    }
}

