/* Enum used instead of raw String/int constants (see: int/string enum pitfalls).
   Compile-time type safety, printable names, no hard-coded literals in clients. */
enum MatchResult {
    FOUND("Found a match!"),
    NOT_FOUND("Not matched!");

    private final String message;

    MatchResult(String message) {
        this.message = message;
    }

    @Override
    public String toString() {
        return message;
    }
}

class TextMatchWordzMiddle {

    /* Matches a word containing 'z' that is NOT at the start or the end of the word.
       \b      -> word boundary (start of the word)
       \w+     -> at least one word char BEFORE the 'z'
       z       -> the letter 'z'
       \w+     -> at least one word char AFTER the 'z'
       \b      -> word boundary (end of the word)                                */
    private static final Pattern WORD_WITH_Z_IN_MIDDLE =
            Pattern.compile("\\b\\w+z\\w+\\b");

    /**
     * * Write a function that matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null || text.isEmpty()) {
            return MatchResult.NOT_FOUND.toString();
        }
        Matcher matcher = WORD_WITH_Z_IN_MIDDLE.matcher(text);
        return matcher.find() ? MatchResult.FOUND.toString()
                              : MatchResult.NOT_FOUND.toString();
    }

    // Simple self-test / driver
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));     // Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));    // Not matched!

        // Extra checks: 'z' only at start / end / alone must NOT match
        System.out.println(textMatchWordzMiddle("zabc."));        // Not matched!
        System.out.println(textMatchWordzMiddle("abcz."));        // Not matched!
        System.out.println(textMatchWordzMiddle("a z b c"));      // Not matched!
        System.out.println(textMatchWordzMiddle("abZcd."));       // Found a match!
    }
}

