import java.math.*;


class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Trivial / degenerate input: nothing to average.
        if (n <= 0 || cost == null || cost.isEmpty()) {
            return 0.0;
        }

        // dp[i][j] = maximum SUM of any path from (0,0) to (i,j)
        // (only "down" and "right" moves are allowed).
        int[][] dp = new int[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int cell = cost.get(i).get(j);

                if (i == 0 && j == 0) {
                    dp[i][j] = cell;                 // starting cell
                    continue;
                }

                int bestPrev = Integer.MIN_VALUE;
                if (i > 0) {                          // came from above
                    bestPrev = Math.max(bestPrev, dp[i - 1][j]);
                }
                if (j > 0) {                          // came from the left
                    bestPrev = Math.max(bestPrev, dp[i][j - 1]);
                }
                dp[i][j] = cell + bestPrev;
            }
        }

        // Every valid path has exactly (2n - 1) cells, so the denominator is
        // constant => maximizing the average == maximizing the sum.
        int pathLength = 2 * n - 1;
        return dp[n - 1][n - 1] / (double) pathLength;
    }

    public static void main(String[] args) {
        System.out.println(maxaverageofpath(
                Arrays.asList(Arrays.asList(1, 2, 3),
                              Arrays.asList(6, 5, 4),
                              Arrays.asList(7, 3, 9)), 3));   // 5.2

        System.out.println(maxaverageofpath(
                Arrays.asList(Arrays.asList(2, 3, 4),
                              Arrays.asList(7, 6, 5),
                              Arrays.asList(8, 4, 10)), 3));  // 6.2

        System.out.println(maxaverageofpath(
                Arrays.asList(Arrays.asList(3, 4, 5),
                              Arrays.asList(8, 7, 6),
                              Arrays.asList(9, 5, 11)), 3));  // 7.2
    }
}

