class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Newman-Shanks-Williams sequence:
        //   S(1) = 1, S(2) = 1 (base), S(k) = 2*S(k-1) + S(k-2)
        // yielding 1, 1, 3, 7, 17, 41, 99, 239, 577, ...
        if (n <= 1) {
            return 1;
        }

        int prev2 = 1; // S(k-2)
        int prev1 = 1; // S(k-1)

        for (int k = 2; k <= n; k++) {
            int current = 2 * prev1 + prev2;
            prev2 = prev1;
            prev1 = current;
        }

        return prev1;
    }

    // quick self-check against the documented examples
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

