class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        if (n <= 0 || cost == null || cost.isEmpty()) {
            return 0.0;
        }

        // dp[i][j] = maximum path sum reaching cell (i, j)
        double[][] dp = new double[n][n];

        dp[0][0] = cost.get(0).get(0);

        // Fill first row: can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill first column: can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill the rest: best of (above, left)
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                double fromAbove = dp[i - 1][j];
                double fromLeft  = dp[i][j - 1];
                dp[i][j] = cost.get(i).get(j) + Math.max(fromAbove, fromLeft);
            }
        }

        // Every right/down path through an n*n grid visits exactly (2n - 1) cells,
        // so the path with the maximum sum also has the maximum average.
        double pathLength = 2.0 * n - 1.0;

        return dp[n - 1][n - 1] / pathLength;
    }
}

