class Maxaverageofpath {

    /**
     * Directions used to walk backwards from a cell to its predecessors.
     * Values are stored in instance fields (constructor arguments),
     * NOT derived from ordinal() -- see Effective Java, Item 35.
     */
    private enum Move {
        DOWN(1, 0),
        RIGHT(0, 1);

        private final int dr;
        private final int dc;

        Move(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }

        public int dr() { return dr; }
        public int dc() { return dc; }
    }

    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        if (n <= 0 || cost == null || cost.isEmpty()) {
            return 0.0;
        }

        // Every path (only right/down moves) visits exactly 2n-1 cells,
        // so maximizing the average is equivalent to maximizing the sum.
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                long cellValue = cost.get(i).get(j);

                if (i == 0 && j == 0) {
                    dp[i][j] = cellValue;
                    continue;
                }

                long bestPredecessor = Long.MIN_VALUE;
                for (Move m : Move.values()) {          // instance-field driven, ordinal-free
                    int pi = i - m.dr();
                    int pj = j - m.dc();
                    if (pi >= 0 && pj >= 0) {
                        bestPredecessor = Math.max(bestPredecessor, dp[pi][pj]);
                    }
                }
                dp[i][j] = bestPredecessor + cellValue;
            }
        }

        int pathLength = 2 * n - 1;
        return dp[n - 1][n - 1] / (double) pathLength;
    }
}

