class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // First NSW prime is 2 (n == 1).
        if (n == 1) {
            return 2;
        }
        // Invalid input guard.
        if (n < 1) {
            throw new IllegalArgumentException("n must be >= 1, got " + n);
        }

        // Recurrence: S(k) = 2*S(k-1) + S(k-2), with S(0) = 1, S(1) = 1.
        // S(2)=3, S(3)=7, S(4)=17, S(5)=41 ... matches newmanPrime(2..5).
        // Two rolling values only -- no ordinal-indexed array/list needed.
        long prev = 1L;   // S(k-2)
        long curr = 1L;   // S(k-1)

        for (int k = 2; k <= n; k++) {
            long next = 2L * curr + prev;
            prev = curr;
            curr = next;
        }

        return (int) curr;
    }

    // Simple self-test / demo
    public static void main(String[] args) {
        System.out.println(newmanPrime(1));  // 2
        System.out.println(newmanPrime(2));  // 3
        System.out.println(newmanPrime(3));  // 7
        System.out.println(newmanPrime(4));  // 17
        System.out.println(newmanPrime(5));  // 41
        System.out.println(newmanPrime(6));  // 97
        System.out.println(newmanPrime(7));  // 239
        System.out.println(newmanPrime(8));  // 577
    }
}

