class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Degenerate case: empty matrix
        if (n <= 0 || cost == null || cost.isEmpty()) {
            return 0.0;
        }

        // dp[i][j] = maximum sum of a path from (0,0) to (i,j) using only "down"/"right" moves
        int[][] dp = new int[n][n];
        dp[0][0] = cost.get(0).get(0);

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i == 0 && j == 0) {
                    continue; // starting cell already initialised
                }
                int best = Integer.MIN_VALUE;
                if (i > 0) {                       // came from above
                    best = Math.max(best, dp[i - 1][j]);
                }
                if (j > 0) {                       // came from the left
                    best = Math.max(best, dp[i][j - 1]);
                }
                dp[i][j] = cost.get(i).get(j) + best;
            }
        }

        // Every path from (0,0) to (n-1,n-1) has exactly (2n - 1) cells,
        // so the average equals the maximal sum divided by that count.
        double maxSum = dp[n - 1][n - 1];
        double cells   = 2.0 * n - 1.0;

        return maxSum / cells;
    }

    // --- small driver to demonstrate the behaviour -------------------------
    public static void main(String[] args) {
        List<List<Integer>> m1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9));
        List<List<Integer>> m2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10));
        List<List<Integer>> m3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11));

        System.out.println(maxaverageofpath(m1, 3)); // 5.2
        System.out.println(maxaverageofpath(m2, 3)); // 6.2
        System.out.println(maxaverageofpath(m3, 3)); // 7.2
    }
}

