class CountVowels {
    /**
     * * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        // A string with fewer than 2 characters cannot have any neighbour pairs.
        if (testStr == null || testStr.length() < 2) {
            return 0;
        }

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char current = testStr.charAt(i);

            // We only count non-vowel characters that touch a vowel.
            if (isVowel(current)) {
                continue;
            }

            boolean leftNeighbourIsVowel  = (i > 0)      && isVowel(testStr.charAt(i - 1));
            boolean rightNeighbourIsVowel = (i < len - 1) && isVowel(testStr.charAt(i + 1));

            if (leftNeighbourIsVowel || rightNeighbourIsVowel) {
                count++;
            }
        }

        return count;
    }

    /** Case-insensitive vowel check. */
    private static boolean isVowel(char c) {
        switch (Character.toLowerCase(c)) {
            case 'a':
            case 'e':
            case 'i':
            case 'o':
            case 'u':
                return true;
            default:
                return false;
        }
    }
}

