public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
    if (cost == null || cost.isEmpty() || n <= 0) {
        return 0.0;
    }
    if (n == 1) {
        return cost.get(0).get(0).doubleValue();
    }

    // dp[i][j] = maximum sum of any path from (0,0) to (i,j)
    long[][] dp = new long[n][n];
    dp[0][0] = cost.get(0).get(0);

    // first column: only reachable from above
    for (int i = 1; i < n; i++) {
        dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
    }

    // first row: only reachable from the left
    for (int j = 1; j < n; j++) {
        dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
    }

    // interior cells
    for (int i = 1; i < n; i++) {
        for (int j = 1; j < n; j++) {
            long fromTop = dp[i - 1][j];
            long fromLeft = dp[i][j - 1];
            dp[i][j] = cost.get(i).get(j) + Math.max(fromTop, fromLeft);
        }
    }

    // every path visits exactly (2n - 1) cells
    int length = 2 * n - 1;
    return dp[n - 1][n - 1] / (double) length;
}

