class TextMatchWordzMiddle {

    /**
     * Matches a word containing 'z', not at the start or end of the word.
     *
     * (?<=\w)  -> there must be a word character before the 'z' (not word-start)
     * z        -> the literal 'z'
     * (?=\w)   -> there must be a word character after the 'z' (not word-end)
     *
     * Because both neighbours must be word characters, the 'z' necessarily lies
     * strictly inside a single word (whitespace/punctuation delimit the word).
     */
    private static final Pattern Z_INSIDE_WORD = Pattern.compile("(?<=\\w)z(?=\\w)");

    /**
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }
        Matcher matcher = Z_INSIDE_WORD.matcher(text);
        return matcher.find() ? "Found a match!" : "Not matched!";
    }

    // quick self-check
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));  // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));      // Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));     // Not matched!
        System.out.println(textMatchWordzMiddle("zabc def"));      // Not matched!
        System.out.println(textMatchWordzMiddle("abcz def"));      // Not matched!
        System.out.println(textMatchWordzMiddle("cat zebra"));      // Not matched!
        System.out.println(textMatchWordzMiddle("foo baz bar"));   // Found a match!
    }
}

