class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Degenerate inputs: empty matrix or null
        if (cost == null || cost.isEmpty() || n <= 0) {
            return 0.0;
        }

        // Guard against a matrix smaller than the declared size n
        int rows = Math.min(n, cost.size());
        int cols = rows;
        for (List<Integer> row : cost) {
            if (row != null) {
                cols = Math.min(cols, row.size());
            }
        }
        rows = cols;
        if (rows == 0) {
            return 0.0;
        }

        // Every right/down path contains exactly (2*rows - 1) cells,
        // so maximizing the average == maximizing the total sum.
        int[][] dp = new int[rows][cols];

        dp[0][0] = value(cost, 0, 0);

        // First column: can only be reached from the cell above
        for (int i = 1; i < rows; i++) {
            dp[i][0] = dp[i - 1][0] + value(cost, i, 0);
        }
        // First row: can only be reached from the cell on the left
        for (int j = 1; j < cols; j++) {
            dp[0][j] = dp[0][j - 1] + value(cost, 0, j);
        }
        // General case: come from either the top or the left
        for (int i = 1; i < rows; i++) {
            for (int j = 1; j < cols; j++) {
                dp[i][j] = value(cost, i, j)
                        + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        int maxSum = dp[rows - 1][cols - 1];
        int pathLength = rows + cols - 1;   // == 2*n - 1 for a square matrix

        return maxSum / (double) pathLength;
    }

    /** Safe accessor returning 0 for missing/null entries. */
    private static int value(List<List<Integer>> cost, int i, int j) {
        List<Integer> row = cost.get(i);
        if (row == null || j >= row.size() || row.get(j) == null) {
            return 0;
        }
        return row.get(j);
    }

    // Quick self-check
