class CountVowels {
    /**
     * * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */

    /** Returns true if the given character is a vowel (case-insensitive). */
    private static boolean isVowel(char ch) {
        switch (Character.toLowerCase(ch)) {
            case 'a':
            case 'e':
            case 'i':
            case 'o':
            case 'u':
                return true;
            default:
                return false;
        }
    }

    public static int countVowels(String testStr) {
        if (testStr == null || testStr.length() < 2) {
            return 0;   // no character can have a neighbour at all
        }

        int len = testStr.length();
        int count = 0;

        for (int i = 0; i < len; i++) {
            boolean hasVowelNeighbor = false;

            // look at the left neighbour (if any)
            if (i > 0 && isVowel(testStr.charAt(i - 1))) {
                hasVowelNeighbor = true;
            }

            // look at the right neighbour (if any)
            if (!hasVowelNeighbor && i < len - 1 && isVowel(testStr.charAt(i + 1))) {
                hasVowelNeighbor = true;
            }

            if (hasVowelNeighbor) {
                count++;   // counted at most once per position
            }
        }

        return count;
    }
}

