        System.out.println(textMatchWordzMiddle("zabc."));         // Not matched!
        System.out.println(textMatchWordzMiddle("abcz."));         // Not matched!
        System.out.println(textMatchWordzMiddle("zzz"));           // Found a match!
        System.out.println(textMatchWordzMiddle("a-z az"));        // Not matched!
    }
}

