class TextMatchWordzMiddle {
    /**
     * * Write a function that matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null) {
            return "Not matched!";
        }
        // \b  \w+   z   \w+  \b
        //  ^   ^     ^    ^   ^
        //  |   |     |    |   end of word
        //  |   |     |    at least one char AFTER z  -> z is not the last letter
        //  |   |     the literal 'z'
        //  |   at least one char BEFORE z           -> z is not the first letter
        //  start of word
        java.util.regex.Pattern pattern = java.util.regex.Pattern.compile("\\b\\w+z\\w+\\b");
        java.util.regex.Matcher matcher = pattern.matcher(text);
        return matcher.find() ? "Found a match!" : "Not matched!";
    }

    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));     // Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));   // Not matched!
    }
}

public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
    double[][] dp = new double[n][n];

    // Base case: top-left corner
    dp[0][0] = cost.get(0).get(0);

    // Fill first row (only reachable from left)
    for (int j = 1; j < n; j++) {
        dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
    }

    // Fill first column (only reachable from above)
    for (int i = 1; i < n; i++) {
        dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
    }

    // Fill rest of the table
    for (int i = 1; i < n; i++) {
        for (int j = 1; j < n; j++) {
            dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
        }
    }

    // Average = max sum / number of cells in path (always 2n-1)
    return dp[n - 1][n - 1] / (2.0 * n - 1);
}

public static int countVowels(String testStr) {
    String vowels = "aeiouAEIOU";
    int count = 0;
    for (int i = 0; i < testStr.length(); i++) {
        char c = testStr.charAt(i);
        if (vowels.indexOf(c) != -1) {
            continue; // skip vowels themselves
        }
        boolean hasVowelNeighbor = false;
        if (i > 0 && vowels.indexOf(testStr.charAt(i - 1)) != -1) {
            hasVowelNeighbor = true;
        }
        if (i < testStr.length() - 1 && vowels.indexOf(testStr.charAt(i + 1)) != -1) {
            hasVowelNeighbor = true;
        }
        if (hasVowelNeighbor) {
            count++;
        }
    }
    return count;
}

