public static int newmanPrime(int n) {
    if (n == 0 || n == 1) return 1;
    int sPrev = 1; // S₀
    int sCurr = 1; // S₁
    for (int i = 2; i <= n; i++) {
        int next = 2 * sCurr + sPrev;
        sPrev = sCurr;
        sCurr = next;
    }
    return sCurr;
}

