class CountVowels {
    /** True if c is one of the five English vowels (case-insensitive). */
    private static boolean isVowel(char c) {
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u'
            || c == 'A' || c == 'E' || c == 'I' || c == 'O' || c == 'U';
    }

    /**
     * * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        // No neighbours exist for null / empty / single-character input.
        if (testStr == null || testStr.length() < 2) {
            return 0;
        }

        int n = testStr.length();
        int count = 0;

        for (int i = 0; i < n; i++) {
            char c = testStr.charAt(i);

            // Only characters that are themselves NOT vowels are counted;
            // a vowel is never counted, even when it sits next to another vowel.
            if (isVowel(c)) {
                continue;
            }

            boolean leftVowel  = (i > 0)          && isVowel(testStr.charAt(i - 1));
            boolean rightVowel = (i < n - 1)      && isVowel(testStr.charAt(i + 1));

            if (leftVowel || rightVowel) {
                count++;
            }
        }

        return count;
    }

    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));            // 7
        System.out.println(countVowels("partofthejourneyistheend"));  // 12
        System.out.println(countVowels("amazonprime"));               // 5
        System.out.println(countVowels(""));                          // 0
        System.out.println(countVowels("xyz"));                       // 0
    }
}

public static List<Integer> countAlphaDigSpl(String string) {
    int alphaCount = 0;
