    int splCount = 0;

    for (int i = 0; i < string.length(); i++) {
        char ch = string.charAt(i);
        if ((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z')) {
            alphaCount++;
        } else if (ch >= '0' && ch <= '9') {
            digitCount++;
        } else {
            splCount++;
        }
    }

    List<Integer> result = new ArrayList<>();
    result.add(alphaCount);
    result.add(digitCount);
    result.add(splCount);
    return result;
}

