public static int newmanPrime(int n) {
    if (n <= 0) return 1;
    if (n == 1) return 1;

    // Recurrence: S(n) = 2*S(n-1) + S(n-2), with S(0)=1, S(1)=1
    int prevPrev = 1; // S(n-2)
    int prev = 1;     // S(n-1)
    int current = 1;

    for (int i = 2; i <= n; i++) {
        current = 2 * prev + prevPrev;
        prevPrev = prev;
        prev = current;
    }

    return current;
}

