class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Degenerate cases: nothing to average
        if (cost == null || cost.isEmpty() || n <= 0) {
            return 0.0;
        }

        // Every top-left -> bottom-right path (only right / down moves)
        // visits exactly (2n - 1) cells, so maximizing the average is
        // the same as maximizing the total sum of the path.
        int pathLength = 2 * n - 1;

        // dp[j] holds the best sum reachable at column j of the current row
        int[] prev = new int[n];
        int[] curr = new int[n];

        prev[0] = cost.get(0).get(0);
        for (int j = 1; j < n; j++) {                 // first row: only from the left
            prev[j] = prev[j - 1] + cost.get(0).get(j);
        }

        for (int i = 1; i < n; i++) {
            List<Integer> row = cost.get(i);
            curr[0] = prev[0] + row.get(0);           // first column: only from above
            for (int j = 1; j < n; j++) {
                curr[j] = row.get(j) + Math.max(prev[j],   // from above
                                                 curr[j - 1]); // from the left
            }
            // roll the rows
            int[] tmp = prev;
            prev = curr;
            curr = tmp;
        }

        double maxSum = prev[n - 1];
        return maxSum / pathLength;
    }

    // Optional driver to exercise the three documented examples
    public static void main(String[] args) {
        System.out.println(maxaverageofpath(Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)), 3));          // 5.2

        System.out.println(maxaverageofpath(Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)), 3));         // 6.2

        System.out.println(maxaverageofpath(Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)), 3));         // 7.2
    }
}

