class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Base cases: S(1) = 1, S(2) = 3
        if (n <= 1) {
            return 1;
        }
        if (n == 2) {
            return 3;
        }

        // NSW recurrence: S(k) = 2*S(k-1) + S(k-2)
        // (integer equivalent of ((1+sqrt(2))^k + (1-sqrt(2))^k) / 2)
        long prev = 1;   // S(k-2)
        long curr = 3;   // S(k-1)

        for (int k = 3; k <= n; k++) {
            long next = 2 * curr + prev;
            prev = curr;
            curr = next;
        }

        return (int) curr;
    }
}

