class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Base cases of the NSW recurrence:  S(1) = 1, S(2) = 3
        if (n < 1) {
            throw new IllegalArgumentException("n must be >= 1, got " + n);
        }
        if (n == 1) {
            return 1;
        }
        if (n == 2) {
            return 3;
        }

        // Iterative form of  S(k) = 2*S(k-1) + S(k-2)
        long prev = 1;   // S(k-2)
        long curr = 3;   // S(k-1)
        for (int k = 3; k <= n; k++) {
            long next = 2 * curr + prev;
            prev = curr;
            curr = next;
        }
        return (int) curr;
    }

    // Optional convenience: the sequence itself (1, 3, 7, 17, 41, 99, ...)
    public static List<Integer> newmanPrimesUpTo(int count) {
        List<Integer> seq = new ArrayList<>();
        for (int i = 1; i <= count; i++) {
            seq.add(newmanPrime(i));
        }
        return seq;
    }

    public static void main(String[] args) {
        System.out.println(newmanPrime(3));  // 7
        System.out.println(newmanPrime(4));  // 17
        System.out.println(newmanPrime(5));  // 41
        System.out.println(newmanPrimesUpTo(8)); // [1, 3, 7, 17, 41, 99, 239, 577]
    }
}

