class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Degenerate input: nothing to average.
        if (cost == null || cost.isEmpty() || n <= 0) {
            return 0.0;
        }

        // Every right/down path from (0,0) to (n-1,n-1) has exactly 2n-1 cells,
        // so maximizing the average == maximizing the sum.
        final long NEG_INF = Long.MIN_VALUE / 2; // safe for additions
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                long fromTop  = (i > 0) ? dp[i - 1][j] : NEG_INF;
                long fromLeft = (j > 0) ? dp[i][j - 1] : NEG_INF;
                long bestPrev = (i == 0 && j == 0) ? 0L : Math.max(fromTop, fromLeft);
                dp[i][j] = bestPrev + cost.get(i).get(j);
            }
        }

        long maxSum = dp[n - 1][n - 1];
        double average = (double) maxSum / (double) (2 * n - 1);

        return average;
    }

    // Quick self-check of the documented examples.
    public static void main(String[] args) {
        List<List<Integer>> m1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9));
        List<List<Integer>> m2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10));
        List<List<Integer>> m3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11));

        System.out.println(maxaverageofpath(m1, 3)); // 5.2
        System.out.println(maxaverageofpath(m2, 3)); // 6.2
        System.out.println(maxaverageofpath(m3, 3)); // 7.2
    }
}

