class TextMatchWordzMiddle {
    /** The 'z' must be flanked by word characters on both sides:
     *  look-behind (?<=\w) guarantees it's not at the start of a word,
     *  look-ahead  (?=\w)  guarantees it's not at the end of a word. */
    private static final Pattern Z_IN_MIDDLE = Pattern.compile("(?<=\\w)z(?=\\w)");

    /**
     * * Write a function that matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null) {
            return "Not matched!";
        }
        Matcher matcher = Z_IN_MIDDLE.matcher(text);
        return matcher.find() ? "Found a match!" : "Not matched!";
    }
}

public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
    // dp[i][j] = maximum sum of a path from (0,0) to (i,j) moving only right or down
    int[][] dp = new int[n][n];

    dp[0][0] = cost.get(0).get(0);

    // First column: only reachable from above
    for (int i = 1; i < n; i++) {
        dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
    }

    // First row: only reachable from left
    for (int j = 1; j < n; j++) {
        dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
    }

    // Fill the rest
    for (int i = 1; i < n; i++) {
        for (int j = 1; j < n; j++) {
            dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
        }
    }

    // Every path visits exactly (2n - 1) cells
    return dp[n - 1][n - 1] / (double)(2 * n - 1);
}

