class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // dp[i][j] = max sum of path from (0,0) to (i,j) moving only right or down
        int[][] dp = new int[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int val = cost.get(i).get(j);
                if (i == 0 && j == 0) {
                    dp[i][j] = val;
                } else if (i == 0) {
                    dp[i][j] = dp[i][j - 1] + val;
                } else if (j == 0) {
                    dp[i][j] = dp[i - 1][j] + val;
                } else {
                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + val;
                }
            }
        }

        // Path always visits exactly 2*n - 1 cells
        int totalCells = 2 * n - 1;
        return dp[n - 1][n - 1] / (double) totalCells;
    }
}

