class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n <= 0) throw new IllegalArgumentException("n must be positive");
        if (n == 1) return 1;
        if (n == 2) return 3;

        // Favor the standard BiFunction functional interface (Item 44)
        // instead of declaring a custom recurrence interface.
        java.util.function.BiFunction<Integer, Integer, Integer> recurrence =
                (prev, curr) -> 2 * curr + prev;

        int a = 1; // a(1)
        int b = 3; // a(2)
        for (int i = 3; i <= n; i++) {
            int c = recurrence.apply(a, b);
            a = b;
            b = c;
        }
        return b;
    }
}

