import java.util.function.*;   // standard functional interfaces (Item 44)
import java.math.*;


class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // degenerate inputs
        if (cost == null || cost.isEmpty() || n <= 0) {
            return 0.0;
        }

        /*
         * Item 44: favor the use of standard functional interfaces.
         * Both primitives of the recurrence are plain (int, int) -> int functions,
         * so java.util.function.IntBinaryOperator covers them -- no custom
         * interface such as "PathCombiner" needs to be declared.
         */
        final IntBinaryOperator betterPredecessor = Math::max;      // choose the richer incoming path
        final IntBinaryOperator accumulate = (sum, value) -> sum + value;  // add current cell to the path

        int[][] dp = new int[n][n];
        dp[0][0] = cost.get(0).get(0);

        // first column: only moves from above are possible
        for (int i = 1; i < n; i++) {
            dp[i][0] = accumulate.applyAsInt(dp[i - 1][0], cost.get(i).get(0));
        }

        // first row: only moves from the left are possible
        for (int j = 1; j < n; j++) {
            dp[0][j] = accumulate.applyAsInt(dp[0][j - 1], cost.get(0).get(j));
        }

        // interior cells: come from up or left, whichever yields the larger sum
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                int bestIncoming = betterPredecessor.applyAsInt(dp[i - 1][j], dp[i][j - 1]);
                dp[i][j] = accumulate.applyAsInt(cost.get(i).get(j), bestIncoming);
            }
        }

        // every admissible path visits exactly (2n - 1) cells, so the averages
        // are comparable: maximising the average == maximising the sum.
        int cellsOnPath = 2 * n - 1;
        return (double) dp[n - 1][n - 1] / cellsOnPath;
    }
}

