public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
    // dp[i][j] = maximum sum to reach cell (i,j) from (0,0)
    int[][] dp = new int[n][n];

    dp[0][0] = cost.get(0).get(0);

    // First column: only from above
    for (int i = 1; i < n; i++) {
        dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
    }

    // First row: only from left
    for (int j = 1; j < n; j++) {
        dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
    }

    // Fill remaining cells: come from top or left, whichever gives larger sum
    for (int i = 1; i < n; i++) {
        for (int j = 1; j < n; j++) {
            dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
        }
    }

    // Every path from (0,0) to (n-1,n-1) has exactly (2n-1) elements
    // Average = max_sum / (2n - 1)
    int pathLength = 2 * n - 1;
    return dp[n - 1][n - 1] / (double) pathLength;
}

