class CountVowels {
    /**
     * * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */

    /** A purpose-built functional interface (annotated, single abstract method). */
    @FunctionalInterface
    interface CharacterPredicate {
        boolean test(char c);
    }

    private static final String VOWELS = "aeiou";

    /** Predicate recognizing vowels; y is treated as a consonant. */
    private static final CharacterPredicate IS_VOWEL =
            c -> VOWELS.indexOf(Character.toLowerCase(c)) >= 0;

    public static int countVowels(String testStr) {
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }
        String s = testStr;
        int n = s.length();

        // Indexes of characters that are NOT vowels but have a vowel neighbour.
        IntStream indexes = IntStream.range(0, n);

        return (int) indexes
                .filter(i -> !IS_VOWEL.test(s.charAt(i)))                 // the char itself is a consonant
                .filter(i -> (i > 0 && IS_VOWEL.test(s.charAt(i - 1)))    // left neighbour is a vowel
                          || (i + 1 < n && IS_VOWEL.test(s.charAt(i + 1)))) // right neighbour is a vowel
                .count();
    }

    // Quick self-check against the documented examples
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

