class CountVowels {

    /** Returns true if the given character is one of a, e, i, o, u (case insensitive). */
    private static boolean isVowel(char ch) {
        switch (Character.toLowerCase(ch)) {
            case 'a':
            case 'e':
            case 'i':
            case 'o':
            case 'u':
                return true;
            default:
                return false;
        }
    }

    /**
     * * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        // Degenerate inputs: nothing can have a neighbor.
        if (testStr == null || testStr.length() < 2) {
            return 0;
        }

        final String str = testStr;
        final int len = str.length();

        // Flat pipeline: source -> filter (not a vowel) -> filter (has a vowel neighbor) -> count
        return (int) IntStream.range(0, len)
                .filter(i -> !isVowel(str.charAt(i)))                       // skip the vowels themselves
                .filter(i -> (i > 0 && isVowel(str.charAt(i - 1)))          // left neighbor is a vowel
                        || (i < len - 1 && isVowel(str.charAt(i + 1))))     // or right neighbor is a vowel
                .count();
    }

    // Simple driver to demonstrate / self-test
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));             // 5
        System.out.println(countVowels(""));                        // 0
        System.out.println(countVowels(null));                      // 0
    }
}

