class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n == 1) return 1;
        if (n == 2) return 3;
        int prev2 = 1; // a(n-2)
        int prev1 = 3; // a(n-1)
        int current = 0;
        for (int i = 3; i <= n; i++) {
            current = 2 * prev1 + prev2;
            prev2 = prev1;
            prev1 = current;
        }
        return current;
    }
}

