class RemoveOdd {
    /**
     * * Write a function to remove odd characters in a string.
     *
     * > removeOdd("python")
     * "yhn"
     * > removeOdd("program")
     * "rga"
     * > removeOdd("language")
     * "agae"
     */
    public static String removeOdd(String str1) {
        // Guard against null / empty input.
        if (str1 == null || str1.isEmpty()) {
            return "";
        }

        // Helper: does this index belong to a character we want to KEEP?
        // Indices are 0-based, so the characters at positions 1, 3, 5, ... (1-based)
        // correspond to indices 1, 3, 5, ... which are exactly the ODD indices.
        // Everything at an even index (0, 2, 4, ...) is removed.
        final int length = str1.length();

        // Build the result with a stream over the character indices.
        // Using a named helper predicate keeps the pipeline readable.
        String result = java.util.stream.IntStream.range(0, length)
                .filter(RemoveOdd::isKeptIndex)          // keep odd 0-based indices
                .mapToObj(i -> String.valueOf(str1.charAt(i)))
                .collect(java.util.stream.Collectors.joining());

        return result;
    }

    /**
     * Named helper: returns true when the 0-based index holds a character
     * that must survive the filtering (odd 1-based position => odd 0-based index).
     * A named method is used instead of an inline lambda so the stream pipeline
     * stays short and self-documenting.
     */
    private static boolean isKeptIndex(int index) {
        return index % 2 == 1;
    }

    // Simple driver to verify the documented examples.
    public static void main(String[] args) {
        System.out.println(removeOdd("python"));    // yhn
        System.out.println(removeOdd("program"));   // rga
        System.out.println(removeOdd("language"));  // agae
        System.out.println(removeOdd("a"));         // ""  (only index 0, removed)
        System.out.println(removeOdd("ab"));        // "b"
        System.out.println(removeOdd(""));          // ""
    }
}

