     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */

    // \b\w+z\w+\b :
    //   \b  -> match must begin at a word start
    //   \w+ -> at least one character BEFORE the 'z'  (z not first)
    //   z   -> the letter we are looking for
    //   \w+ -> at least one character AFTER the 'z'   (z not last)
    //   \b  -> match must end at a word end
    private static final Pattern Z_IN_MIDDLE =
            Pattern.compile("\\b\\w+z\\w+\\b");

    public static String textMatchWordzMiddle(String text) {
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }
        Matcher matcher = Z_IN_MIDDLE.matcher(text);
        return matcher.find() ? "Found a match!" : "Not matched!";
    }

    // quick self-check
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));      // Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));     // Not matched!
        System.out.println(textMatchWordzMiddle("zab"));          // Not matched!
        System.out.println(textMatchWordzMiddle("az"));           // Not matched!
        System.out.println(textMatchWordzMiddle("abz"));          // Not matched!
        System.out.println(textMatchWordzMiddle("ab zc d"));      // Found a match!
    }
}

public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
    int[][] dp = new int[n][n];
    dp[0][0] = cost.get(0).get(0);

    // Initialize first row (only reachable from left)
    for (int j = 1; j < n; j++) {
        dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
    }

    // Initialize first column (only reachable from above)
    for (int i = 1; i < n; i++) {
        dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
    }

    // Fill remaining cells: max(sum from top, sum from left) + current cell
    for (int i = 1; i < n; i++) {
        for (int j = 1; j < n; j++) {
            dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
        }
    }

    return (double) dp[n - 1][n - 1] / (2 * n - 1);
}

