import java.math.*;


class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        if (n <= 0) {
            return 0.0;
        }

        // dp[i][j] = maximum sum of any path from (0,0) to (i,j)
        int[][] dp = new int[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int fromTop = Integer.MIN_VALUE;
                int fromLeft = Integer.MIN_VALUE;

                if (i > 0) {
                    fromTop = dp[i - 1][j];   // came down
                }
                if (j > 0) {
                    fromLeft = dp[i][j - 1];   // came right
                }

                int best;
                if (i == 0 && j == 0) {
                    best = 0;                  // starting cell, nothing to add
                } else if (i == 0) {
                    best = fromLeft;
                } else if (j == 0) {
                    best = fromTop;
                } else {
                    best = Math.max(fromTop, fromLeft);
                }

                dp[i][j] = best + cost.get(i).get(j);
            }
        }

        // Every admissible path visits exactly (2n - 1) cells,
        // so maximizing the sum also maximizes the average.
        int maxSum = dp[n - 1][n - 1];
        int pathLength = 2 * n - 1;

        return (double) maxSum / pathLength;
    }
}

