     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        // Nothing to count for null / too-short strings (no pair of neighbors exists)
        if (testStr == null || testStr.length() < 2) {
            return 0;
        }

        final Set<Character> vowels =
                new HashSet<>(Arrays.asList('a', 'e', 'i', 'o', 'u'));

        final char[] chars = testStr.toLowerCase().toCharArray();

        // Pipeline: every valid index -> keep non-vowels -> keep those touching a vowel -> count
        return (int) IntStream.range(0, chars.length)
                .filter(i -> !vowels.contains(chars[i]))                       // the char itself is not a vowel
                .filter(i -> (i > 0 && vowels.contains(chars[i - 1]))          // left neighbor is a vowel
                          || (i < chars.length - 1 && vowels.contains(chars[i + 1]))) // right neighbor is a vowel
                .count();
    }
}

