class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n == 1) return 2;

        int count = 1;       // already counted 2
        int sPrev = 1;       // S_1 = 1
        int sCurr = 3;       // S_2 = 3

        while (true) {
            if (isPrime(sCurr)) {
                count++;
                if (count == n) return sCurr;
            }
            int sNext = 2 * sCurr + sPrev;
            sPrev = sCurr;
            sCurr = sNext;
        }
    }

    private static boolean isPrime(int num) {
        if (num < 2) return false;
        if (num % 2 == 0) return num == 2;
        for (int i = 3; (long) i * i <= num; i += 2) {
            if (num % i == 0) return false;
        }
        return true;
    }
}

