class RemoveOdd {
    /**
     * * Write a function to remove odd characters in a string.
     *
     * > removeOdd("python")
     * "yhn"
     * > removeOdd("program")
     * "rga"
     * > removeOdd("language")
     * "agae"
     */
    public static String removeOdd(String str1) {
        if (str1 == null) {
            return "";
        }
        // Pure stream pipeline: indices -> filter odd ones -> map to char -> join.
        // No side effects anywhere; the whole result comes from the terminal collect().
        return IntStream.range(0, str1.length())
                .filter(i -> i % 2 != 0)      // keep characters at odd indices
                .mapToObj(i -> String.valueOf(str1.charAt(i)))
                .collect(Collectors.joining());
    }

    // Optional driver for quick verification
    public static void main(String[] args) {
        System.out.println(removeOdd("python"));   // yhn
        System.out.println(removeOdd("program"));  // rga
        System.out.println(removeOdd("language")); // agae
    }
}

