class TextMatchWordzMiddle {
    /**
     * * Write a function that matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Side-effect-free stream pipeline:
        //   1) tokenize the text into words (\w+),
        //   2) keep only words long enough to have a "middle",
        //   3) ask whether any interior character is 'z'.
        boolean found = Pattern.compile("\\w+")
                .matcher(text)
                .results()                                   // Stream<MatchResult>
                .map(MatchResult::group)                     // Stream<String>  -- the words
                .anyMatch(word -> word.length() > 2 &&       // needs a start, a middle and an end
                        IntStream.range(1, word.length() - 1) // interior indices only
                                 .anyMatch(i -> word.charAt(i) == 'z'));

        return found ? "Found a match!" : "Not matched!";
    }

    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));     // Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));   // Not matched!
        // corner cases: z at the very start / very end / alone -> not matched
        System.out.println(textMatchWordzMiddle("zabc def"));    // Not matched!
        System.out.println(textMatchWordzMiddle("abc zzz def")); // Found a match!
    }
}

