class CountVowels {
    /**
     * * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.length() < 2) return 0;

        Set<Character> vowels = new HashSet<>(Arrays.asList(
            'a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'));

        char[] chars = testStr.toCharArray();

        return (int) IntStream.range(0, chars.length)
            // Character is NOT a vowel
            .filter(i -> !vowels.contains(chars[i]))
            // At least one existing neighbor IS a vowel
            .filter(i -> (i > 0 && vowels.contains(chars[i - 1])) ||
                         (i < chars.length - 1 && vowels.contains(chars[i + 1])))
            .count();
    }
}

