        System.out.println(textMatchWordzMiddle("  lang  ."));   // Not matched!
        System.out.println(textMatchWordzMiddle("z abcz"));      // Not matched! (z at edges)
        System.out.println(textMatchWordzMiddle("a zebra"));     // Found a match!
    }
}

import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;
import java.util.stream.*;


class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        if (n <= 0) {
            return 0.0;
        }

        // Side-effect-free pipeline: copy the boxed matrix into a primitive grid.
        int[][] grid = IntStream.range(0, n)
                .mapToObj(i -> cost.get(i).stream()
                        .limit(n)
                        .mapToInt(Integer::intValue)
                        .toArray())
                .toArray(int[][]::new);

        // dp[i][j] = largest sum of any (right/down only) path from (0,0) to (i,j).
        // Every such path has exactly 2n-1 cells, so maximizing the average
        // is the same as maximizing the sum.
        int[] prev = new int[n];               // dp values of the previous row

        for (int i = 0; i < n; i++) {
            final int row = i;
            final int[] above = prev;

            // first cell of this row: only reachable from above (or it is the origin)
            int first = (row == 0 ? 0 : above[0]) + grid[row][0];

            // Fold over the remaining columns: accumulator carries the row built
            // so far and returns a NEW list each time (no side effects at all).
            List<Integer> cur = IntStream.range(1, n)
                    .boxed()
                    .reduce(Collections.singletonList(first),
                            (acc, j) -> {
                                int left = acc.get(acc.size() - 1);          // dp[i][j-1]
                                int best = (row == 0) ? left                 // first row: from left only
                                                      : Math.max(above[j], left); // else max(up, left)
                                List<Integer> next = new ArrayList<>(acc);
                                next.add(best + grid[row][j]);
                                return next;
                            },
                            (a, b) -> a);                                    // unused (sequential)

            prev = cur.stream().mapToInt(Integer::intValue).toArray();
        }

        long cells = 2L * n - 1;                 // length of every valid path
        return prev[n - 1] / (double) cells;
    }
}

