import static java.util.stream.Collectors.counting;
import static java.util.stream.Collectors.toList;

class CountAlphaDigSpl {
    /**
     * * Write a function to count alphabets,digits and special charactes in a given string.
     *
     * > countAlphaDigSpl("abc!@#123")
     * [3, 3, 3]
     * > countAlphaDigSpl("dgsuy@#$%&1255")
     * [5, 4, 5]
     * > countAlphaDigSpl("fjdsif627348#%$^&")
     * [6, 6, 5]
     */
    public static List<Integer> countAlphaDigSpl(String string) {
        if (string == null) {
            return Arrays.asList(0, 0, 0);
        }

        // Pure predicates, no side effects anywhere in the pipeline (Item 46)
        int alphabets = (int) string.chars()
                .filter(Character::isLetter)
                .count();

        int digits = (int) string.chars()
                .filter(Character::isDigit)
                .count();

        // The three classes are mutually exclusive and exhaustive,
        // so the remainder is, by definition, "special characters".
        int specials = string.length() - alphabets - digits;

        // Terminal result gathered with a collector, not accumulated imperatively
        return Arrays.asList(alphabets, digits, specials)
                .stream()
                .collect(toList());
    }

    // ---------- demo ----------
    public static void main(String[] args) {
        System.out.println(countAlphaDigSpl("abc!@#123"));          // [3, 3, 3]
        System.out.println(countAlphaDigSpl("dgsuy@#$%&1255"));     // [5, 4, 5]
        System.out.println(countAlphaDigSpl("fjdsif627348#%$^&")); // [6, 6, 5]
        System.out.println(countAlphaDigSpl(""));                   // [0, 0, 0]
        System.out.println(countAlphaDigSpl("Hello, World! 123"));  // [10, 3, 4]
    }
}

