class CountVowels {
    /** Characters that are not vowels but have a vowel as a neighbour. */
    private static final String VOWELS = "aeiouAEIOU";

    /**
     * * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        // Nothing can have a neighbour without at least two characters.
        if (testStr == null || testStr.length() < 2) {
            return 0;
        }

        char[] chars = testStr.toCharArray();
        int count = 0;

        for (int i = 0; i < chars.length; i++) {
            char c = chars[i];

            // Vowels themselves are never counted; only characters whose
            // *neighbour* is a vowel.
            if (VOWELS.indexOf(c) >= 0) {
                continue;
            }

            boolean leftIsVowel  = i > 0                    && VOWELS.indexOf(chars[i - 1]) >= 0;
            boolean rightIsVowel = i < chars.length - 1     && VOWELS.indexOf(chars[i + 1]) >= 0;

            if (leftIsVowel || rightIsVowel) {
                count++;
            }
        }

        return count;
    }

    // Optional: stream-style equivalent of the loop above
    private static int countVowelsStream(String testStr) {
        if (testStr == null || testStr.length() < 2) return 0;
        char[] chars = testStr.toCharArray();
        return (int) java.util.stream.IntStream.range(0, chars.length)
                .filter(i -> VOWELS.indexOf(chars[i]) < 0)                       // consonants only
                .filter(i -> (i > 0 && VOWELS.indexOf(chars[i - 1]) >= 0)        // left neighbour
                        || (i < chars.length - 1 && VOWELS.indexOf(chars[i + 1]) >= 0)) // right neighbour
                .count();
    }
}

