import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;
import java.util.stream.*;


class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths
     * for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Degenerate inputs: nothing to average.
        if (cost == null || cost.isEmpty() || n <= 0) {
            return 0.0;
        }

        int size = Math.min(n, cost.size());

        // dp[i][j] = maximum sum of any down/right path ending at cell (i, j)
        int[][] dp = new int[size][size];
        dp[0][0] = cost.get(0).get(0);

        for (int i = 0; i < size; i++) {
            List<Integer> row = cost.get(i);
            for (int j = 0; j < size; j++) {
                if (i == 0 && j == 0) {
                    continue;                       // already seeded
                }
                int best = Integer.MIN_VALUE;
                if (i > 0) {                        // came from above
                    best = Math.max(best, dp[i - 1][j]);
                }
                if (j > 0) {                        // came from the left
                    best = Math.max(best, dp[i][j - 1]);
                }
                dp[i][j] = best + row.get(j);
            }
        }

        // Every admissible path contains exactly (2n - 1) cells,
        // so the average = maxSum / (2n - 1).
        double steps = 2.0 * size - 1.0;
        return dp[size - 1][size - 1] / steps;
    }

    /* ------------------------------------------------------------------
     * Supporting helpers (illustrating the Iterable <-> Stream adapters)
     * ------------------------------------------------------------------ */

    /** Adapter from Stream<E> to Iterable<E> so a stream can drive a for-each loop. */
    public static <E> Iterable<E> iterableOf(Stream<E> stream) {
        return stream::iterator;
    }

    /** Adapter from Iterable<E> to Stream<E>. */
    public static <E> Stream<E> streamOf(Iterable<E> iterable) {
        return StreamSupport.stream(iterable.spliterator(), false);
    }

    /** Brute-force cross-check: enumerates every path with a DFS and averages them. */
    private static double bruteForce(List<List<Integer>> cost, int n) {
        int[] bestSum = {Integer.MIN_VALUE};
        dfs(cost, n, 0, 0, 0, bestSum);
        return bestSum[0] / (2.0 * n - 1.0);
    }

    private static void dfs(List<List<Integer>> cost, int n,
                            int i, int j, int sum, int[] bestSum) {
        int next = sum + cost.get(i).get(j);
        if (i == n - 1 && j == n - 1) {
            bestSum[0] = Math.max(bestSum[0], next);
            return;
        }
        if (i + 1 < n) dfs(cost, n, i + 1, j, next, bestSum);   // move down
        if (j + 1 < n) dfs(cost, n, i, j + 1, next, bestSum);   // move right
    }

    private static List<List<Integer>> m(int[]... rows) {
        List<List<Integer>> out = new ArrayList<>();
        for (int[] r : rows) {
            List<Integer> line = new ArrayList<>();
            for (int v : r) line.add(v);
            out.add(line);
        }
        return out;
    }

    public static void main(String[] args) {
        double a = maxaverageofpath(m(new int[]{1, 2, 3},
                                      new int[]{6, 5, 4},
                                      new int[]{7, 3, 9}), 3);
        double b = maxaverageofpath(m(new int[]{2, 3, 4},
                                      new int[]{7, 6, 5},
                                      new int[]{8, 4, 10}), 3);
        double c = maxaverageofpath(m(new int[]{3, 4, 5},
                                      new int[]{8, 7, 6},
                                      new int[]{9, 5, 11}), 3);

        System.out.println(a);   // 5.2
        System.out.println(b);   // 6.2
        System.out.println(c);   // 7.2

        // Cross-check against the exhaustive search.
        assert Math.abs(a - bruteForce(m(new int[]{1, 2, 3},
                                         new int[]{6, 5, 4},
                                         new int[]{7, 3, 9}), 3)) < 1e-9;

        // Demonstrating the iterableOf adapter: iterate a stream with for-each.
        for (String s : iterableOf(Stream.of("dp", "is", "O(n^2)"))) {
            System.out.print(s + " ");
        }
        System.out.println();
    }
}

