class RemoveOdd {

    /**
     * * Write a function to remove odd characters in a string.
     *
     * > removeOdd("python")
     * "yhn"
     * > removeOdd("program")
     * "rga"
     * > removeOdd("language")
     * "agae"
     */
    public static String removeOdd(String str1) {
        // Defensive handling of null / empty input.
        if (str1 == null || str1.isEmpty()) {
            return "";
        }
        // The result can never be longer than half of the input (+1 for odd lengths).
        StringBuilder sb = new StringBuilder((str1.length() >> 1) + 1);
        for (int i = 1; i < str1.length(); i += 2) {   // keep odd indices only
            sb.append(str1.charAt(i));
        }
        return sb.toString();
    }

    /**
     * Companion method returning a Collection instead of a String,
     * so callers may either iterate over it directly or obtain a
     * Stream from it (Effective Java, Item 47).
     */
    public static List<Character> oddCharacters(String str1) {
        List<Character> result = new ArrayList<>();
        if (str1 == null) {
            return result;
        }
        for (int i = 1; i < str1.length(); i += 2) {
            result.add(str1.charAt(i));
        }
        return result;
    }

    // Quick self-test
    public static void main(String[] args) {
        System.out.println(removeOdd("python"));    // yhn
        System.out.println(removeOdd("program"));   // rga
        System.out.println(removeOdd("language"));  // agae
        System.out.println(removeOdd(""));          // (empty)
        System.out.println(removeOdd("ab"));        // b
        // Both usage styles supported by the Collection-returning variant:
        oddCharacters("python").forEach(System.out::print);                 // iterate
        System.out.println();
        oddCharacters("python").stream()
                               .map(String::valueOf)
                               .reduce("", String::concat);                // stream
    }
}

