class TextMatchWordzMiddle {
    /**
     * * Write a function that matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // \B before 'z' -> 'z' is NOT the first character of the word
        // \B after  'z' -> 'z' is NOT the last  character of the word
        Pattern pattern = Pattern.compile("\\Bz\\B");
        Matcher matcher = pattern.matcher(text);

        if (matcher.find()) {
            return "Found a match!";
        } else {
            return "Not matched!";
        }
    }

    // quick self-test
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));     // Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));    // Not matched!
        System.out.println(textMatchWordzMiddle("zabc"));        // Not matched! (leading z)
        System.out.println(textMatchWordzMiddle("abcz"));        // Not matched! (trailing z)
        System.out.println(textMatchWordzMiddle("ab z cd"));     // Not matched! (standalone z)
    }
}

public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
    // DP table: dp[i][j] = max sum to reach (i,j)
    int[][] dp = new int[n][n];
    dp[0][0] = cost.get(0).get(0);

    // First row: can only come from the left
    for (int j = 1; j < n; j++) {
        dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
    }

    // First column: can only come from above
    for (int i = 1; i < n; i++) {
        dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
    }

    // Fill rest: come from either above or left, pick max
    for (int i = 1; i < n; i++) {
        for (int j = 1; j < n; j++) {
            dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
        }
    }

    // Path length from (0,0) to (n-1,n-1) is always 2n-1
    double pathLength = 2 * n - 1;
    return dp[n - 1][n - 1] / pathLength;
}

