import java.lang.*;
import java.util.*;
import java.math.*;


class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Trivial / degenerate input
        if (cost == null || n <= 0 || cost.isEmpty()) {
            return 0.0;
        }

        // Every path from (0,0) to (n-1,n-1) using only right/down moves
        // visits exactly (2n - 1) cells, so the denominator is constant:
        //   maxAverage = maxPathSum / (2n - 1)
        // Therefore we only need the maximum path SUM (classic O(n^2) DP).
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                long cell = 0;
                List<Integer> row = cost.get(i);
                if (row != null && j < row.size() && row.get(j) != null) {
                    cell = row.get(j);
                }

                if (i == 0 && j == 0) {
                    dp[i][j] = cell;
                } else if (i == 0) {
                    dp[i][j] = cell + dp[i][j - 1];      // only from the left
                } else if (j == 0) {
                    dp[i][j] = cell + dp[i - 1][j];      // only from above
                } else {
                    dp[i][j] = cell + Math.max(dp[i - 1][j], dp[i][j - 1]);
                }
            }
        }

        long maxSum = dp[n - 1][n - 1];
        int pathLength = 2 * n - 1;

        return (double) maxSum / pathLength;
    }
}

