        }
        Matcher matcher = Z_MIDDLE.matcher(text);
        // Sequential scan: the input is a single short string, so a
        // parallel pipeline would only add overhead (see Item 48).
        if (matcher.find()) {
            return "Found a match!";
        }
        return "Not matched!";
    }

