class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Trivial / degenerate inputs.
        if (cost == null || cost.isEmpty() || n <= 0) {
            return 0.0;
        }

        // Safe accessor: returns the cell value, or 0 if out of range.
        int rows = cost.size();
        int cols = cost.get(0).size();
        int size = Math.min(n, Math.min(rows, cols));
        if (size <= 0) {
            return 0.0;
        }

        // dp[i][j] = maximum SUM of a path from (0,0) to (i,j) using only
        // right / down moves. Every such path has the same length,
        // so maximizing the average == maximizing the sum.
        long[][] dp = new long[size][size];

        dp[0][0] = cost.get(0).get(0);

        // First row: can only come from the left.
        for (int j = 1; j < size; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column: can only come from above.
        for (int i = 1; i < size; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Interior cells: best of "from above" vs. "from left".
        for (int i = 1; i < size; i++) {
            List<Integer> row = cost.get(i);
            for (int j = 1; j < size; j++) {
                long fromAbove = dp[i - 1][j];
                long fromLeft  = dp[i][j - 1];
                dp[i][j] = (fromAbove >= fromLeft ? fromAbove : fromLeft) + row.get(j);
            }
        }

        // Any path from (0,0) to (size-1,size-1) visits exactly 2*size-1 cells,
        // so the maximum average = maxSum / (2*size - 1).
        double pathLength = (double) (2 * size - 1);
        return dp[size - 1][size - 1] / pathLength;
    }

    // ---- small demo harness (optional) ----
    public static void main(String[] args) {
        System.out.println(maxaverageofpath(
                Arrays.asList(Arrays.asList(1, 2, 3),
                              Arrays.asList(6, 5, 4),
                              Arrays.asList(7, 3, 9)), 3));   // 5.2

        System.out.println(maxaverageofpath(
                Arrays.asList(Arrays.asList(2, 3, 4),
                              Arrays.asList(7, 6, 5),
                              Arrays.asList(8, 4, 10)), 3));  // 6.2

        System.out.println(maxaverageofpath(
                Arrays.asList(Arrays.asList(3, 4, 5),
                              Arrays.asList(8, 7, 6),
                              Arrays.asList(9, 5, 11)), 3));  // 7.2
    }
}

