class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non-negative");
        }
        if (n <= 1) {
            return 1;
        }
        int prev = 1; // a(0)
        int curr = 1; // a(1)
        for (int i = 2; i <= n; i++) {
            int next = 2 * curr + prev;
            prev = curr;
            curr = next;
        }
        return curr;
    }
}

