     *
     * @param text the text to be searched; must not be {@code null}
     * @return "Found a match!" if a word containing an interior 'z' exists,
     *         otherwise "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Fail fast on an invalid argument instead of letting the regex
        // engine throw a confusing NullPointerException deep inside find().
        if (text == null) {
            return "Not matched!";
        }

        // \Bz\w*  -> 'z' preceded by a word character  (not at word start)
        // \w*z\B  -> 'z' followed by a word character  (not at word end)
        Pattern pattern = Pattern.compile("\\Bz\\w*|\\w*z\\B");
        Matcher matcher = pattern.matcher(text);

        if (matcher.find()) {
            return "Found a match!";
        }
        return "Not matched!";
    }
}

