     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        if (cost == null || n <= 0) {
            throw new IllegalArgumentException("Matrix must be non-null and n must be positive");
        }

        // dp[i][j] = maximum sum of a path from (0,0) to (i,j)
        int[][] dp = new int[n][n];

        // Initialize starting cell
        dp[0][0] = cost.get(0).get(0);

        // Fill first column (only reachable by moving down)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill first row (only reachable by moving right)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill rest of the table: come from either top or left
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
            }
        }

        // Path length is always (2n - 1) cells; average = total sum / path length
        double maxSum = dp[n - 1][n - 1];
        int pathLength = 2 * n - 1;

        return maxSum / pathLength;
    }
}

