class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Check parameters for validity
        Objects.requireNonNull(cost, "cost must not be null");
        if (n <= 0) {
            throw new IllegalArgumentException("n must be a positive integer, got: " + n);
        }
        if (cost.size() < n) {
            throw new IllegalArgumentException("cost matrix has fewer than " + n + " rows");
        }

        // dp[i][j] = maximum path sum from (0,0) to (i,j)
        int[][] dp = new int[n][n];

        // Base cases: first row and first column
        dp[0][0] = cost.get(0).get(0);
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill remaining cells: come from either top or left, pick the max
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
            }
        }

        // All paths from (0,0) to (n-1,n-1) have exactly (2n-1) elements,
        // so max average = max sum / (2n - 1)
        int pathLength = 2 * n - 1;
        return dp[n - 1][n - 1] / (double) pathLength;
    }
}

