     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Explicit up-front check: the method is documented never to throw,
        // so guard against the one value the regex engine cannot handle.
        if (text == null) {
            return "Not matched!";
        }

        // \b  \w+   z   \w+  \b
        //  ^   ^     ^    ^    ^
        //  |   |     |    |    +-- ends the word
        //  |   |     |    +------- >= 1 char AFTER  'z'  -> z is not last
        //  |   |     +------------ the literal 'z'
        //  |   +------------------ >= 1 char BEFORE 'z'  -> z is not first
        //  +---------------------- starts the word
        Pattern pattern = Pattern.compile("\\b\\w+z\\w+\\b");
        Matcher matcher = pattern.matcher(text);

        if (matcher.find()) {
            return "Found a match!";
        }
        return "Not matched!";
    }

    // Quick self-test
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));  // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));      // Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));    // Not matched!
        System.out.println(textMatchWordzMiddle("zabc"));         // Not matched! (z at start)
        System.out.println(textMatchWordzMiddle("abcz"));         // Not matched! (z at end)
        System.out.println(textMatchWordzMiddle("a z b"));        // Not matched! (z alone)
        System.out.println(textMatchWordzMiddle("foo baz bar"));  // Found a match!
