                "expected " + n + " rows but got " + cost.size());
        }
        for (int i = 0; i < n; i++) {
            List<Integer> row = cost.get(i);
            if (row == null || row.size() != n) {
                throw new IllegalArgumentException(
                    "row " + i + " must contain exactly " + n + " entries");
            }
            for (int j = 0; j < n; j++) {
                if (row.get(j) == null) {
                    throw new IllegalArgumentException(
                        "cell (" + i + ", " + j + ") must not be null");
                }
            }
        }

        // --- Dynamic programming: best sum reaching cell (i, j) ---
        long[][] dp = new long[n][n];
        dp[0][0] = cost.get(0).get(0);

        // First column: can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }
        // First row: can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }
        // Interior cells
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j)
                        + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // Every path visits exactly (2n - 1) cells, so the average is
        // totalSum / (2n - 1).
        int length = 2 * n - 1;
        return dp[n - 1][n - 1] / (double) length;
    }
}

