     * Matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */

    // Compiled once: \Bz\B  ==  z with a word character on BOTH sides,
    // i.e. z is strictly inside a word (not at its first or last position).
    private static final Pattern Z_IN_WORD_MIDDLE = Pattern.compile("\\Bz\\B");

    public static String textMatchWordzMiddle(String text) {
        // String is immutable, so no defensive copy is needed (unlike java.util.Date);
        // we only need to guard against a null argument.
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        Matcher matcher = Z_IN_WORD_MIDDLE.matcher(text);
        return matcher.find() ? "Found a match!" : "Not matched!";
    }

    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));     // Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));    // Not matched!

        // Extra sanity checks
        System.out.println(textMatchWordzMiddle("za."));          // Not matched!  (z at start)
        System.out.println(textMatchWordzMiddle("az."));          // Not matched!  (z at end)
        System.out.println(textMatchWordzMiddle(".z."));          // Not matched!  (z is whole word)
        System.out.println(textMatchWordzMiddle("a-z."));         // Not matched!  (z at end of "z")
        System.out.println(textMatchWordzMiddle("he_llo_zz_ok")); // Found a match!
