class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Defensive handling: nothing from the caller's structure is retained.
        if (cost == null || n <= 0) {
            return 0.0;
        }

        // Every right/down path from (0,0) to (n-1,n-1) visits exactly 2n-1 cells,
        // so maximizing the average == maximizing the sum.
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                long value = (long) cost.get(i).get(j);
                long fromTop = (i > 0) ? dp[i - 1][j] : Long.MIN_VALUE / 4;
                long fromLeft = (j > 0) ? dp[i][j - 1] : Long.MIN_VALUE / 4;

                if (i == 0 && j == 0) {
                    dp[i][j] = value;
                } else {
                    dp[i][j] = value + Math.max(fromTop, fromLeft);
                }
            }
        }

        long maxSum = dp[n - 1][n - 1];
        int steps = 2 * n - 1;   // number of cells on every such path

        return (double) maxSum / (double) steps;
    }
}

