class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n <= 0) throw new IllegalArgumentException("n must be positive");
        if (n == 1) return 1;
        if (n == 2) return 3;

        int prev = 1; // f(1)
        int curr = 3; // f(2)

        for (int i = 3; i <= n; i++) {
            int next = 2 * curr + prev;
            prev = curr;
            curr = next;
        }
        return curr;
    }
}

