     */
    public static int newmanPrime(int n) {
        if (n <= 1) {
            return 1;
        }
        // S(0) = 1, S(1) = 1, S(n) = 2*S(n-1) + S(n-2)
        int prev2 = 1; // S(n-2)
        int prev1 = 1; // S(n-1)
        int current = 1;
        for (int i = 2; i <= n; i++) {
            current = 2 * prev1 + prev2;
            prev2 = prev1;
            prev1 = current;
        }
        return current;
    }

    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

