     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against a degenerate matrix.
        if (cost == null || cost.isEmpty() || n <= 0) {
            return 0.0;
        }

        // dp[i][j] = maximum sum of any valid path from (0,0) to (i,j)
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                long current = cost.get(i).get(j);

                long fromTop = (i > 0) ? dp[i - 1][j] : Long.MIN_VALUE / 4;
                long fromLeft = (j > 0) ? dp[i][j - 1] : Long.MIN_VALUE / 4;

                if (i == 0 && j == 0) {
                    dp[i][j] = current;                 // starting cell
                } else {
                    dp[i][j] = current + Math.max(fromTop, fromLeft);
                }
            }
        }

        // Every top-left -> bottom-right path visits exactly (2n - 1) cells,
        // so maximizing the sum also maximizes the average.
        long pathLength = 2L * n - 1L;
        double maxSum = (double) dp[n - 1][n - 1];

        return maxSum / pathLength;
    }
}

