class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            return 0;                      // undefined for negative indices
        }

        // Base values of the recurrence  a(k) = 2*a(k-1) + a(k-2)
        //   a(0) = 1, a(1) = 1  ->  1, 1, 3, 7, 17, 41, 99, 239, ...
        long prev = 1;                     // a(k-2)
        long curr = 1;                     // a(k-1)

        // Advance the pair until it holds a(n)
        for (int k = 2; k <= n; k++) {
            long next = 2L * curr + prev;  // a(k)
            prev = curr;
            curr = next;
        }

        return (int) curr;                 // a(n)
    }
}

