     */
    public static int countVowels(String testStr) {
        // Guard against null / trivially short inputs
        if (testStr == null || testStr.length() < 2) {
            return 0;
        }

        int len = testStr.length();
        int count = 0;

        for (int i = 0; i < len; i++) {
            char current = testStr.charAt(i);

            // Only consonants (non-vowels) are candidates for being counted
            if (isVowel(current)) {
                continue;
            }

            // Look at the left neighbour (if any)
            boolean leftNeighborIsVowel = (i > 0) && isVowel(testStr.charAt(i - 1));

            // Look at the right neighbour (if any)
            boolean rightNeighborIsVowel = (i < len - 1) && isVowel(testStr.charAt(i + 1));

            if (leftNeighborIsVowel || rightNeighborIsVowel) {
                count++;
            }
        }

        return count;
    }

    /**
     * Helper: returns true if the given character is an English vowel
     * (case-insensitive).
     */
    private static boolean isVowel(char c) {
        switch (Character.toLowerCase(c)) {
            case 'a':
            case 'e':
            case 'i':
            case 'o':
            case 'u':
                return true;
            default:
                return false;
        }
    }
}

