            boolean leftIsVowel  = (i - 1 >= 0) && isVowel(testStr.charAt(i - 1));
            boolean rightIsVowel = (i + 1 < len) && isVowel(testStr.charAt(i + 1));

            if (leftIsVowel || rightIsVowel) {
                count++;
            }
        }
        return count;
    }

    private static boolean isVowel(char ch) {
        switch (Character.toLowerCase(ch)) {
            case 'a':
            case 'e':
            case 'i':
            case 'o':
            case 'u':
                return true;
            default:
                return false;
        }
    }
}

