class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Base cases of the recurrence S(0) = S(1) = 1
        if (n <= 1) {
            return 1;
        }

        // Use BigInteger while iterating because the sequence grows like (1+sqrt(2))^n
        BigInteger a = BigInteger.ONE;   // S(i-2)
        BigInteger b = BigInteger.ONE;   // S(i-1)

        for (int i = 2; i <= n; i++) {
            // S(i) = 2*S(i-1) + S(i-2)
            BigInteger c = b.shiftLeft(1).add(a);
            a = b;
            b = c;
        }

        // Narrow back down to int as required by the signature
        return b.intValue();
    }

    // Quick self-check against the documented examples
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

