class TextMatchWordzMiddle {
    /**
     * * Write a function that matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null) {
            return "Not matched!";
        }

        /*
         *  \Bz\B  ==  (?<=\w)z(?=\w)
         *
         *  \B before 'z' : the position in front of 'z' is NOT a word boundary,
         *                  therefore a word character precedes 'z'  -> z is not first.
         *  \B after  'z' : the position after 'z' is NOT a word boundary,
         *                  therefore a word character follows 'z'  -> z is not last.
         *
         *  (No extra escaping is needed: '.' at the end of the samples is a
         *   non-word character, so it never gets swallowed into the word.)
         */
        Pattern pattern = Pattern.compile("\\Bz\\B");
        Matcher matcher = pattern.matcher(text);

        if (matcher.find()) {          // same behaviour as Python's re.search(...)
            return "Found a match!";
        }
        return "Not matched!";
    }

    // ------------------------------------------------------------------
    // quick self-test
    // ------------------------------------------------------------------
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));  // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));      // Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));    // Not matched!

        // extra sanity checks
        System.out.println(textMatchWordzMiddle("zab"));          // Not matched! (z first)
        System.out.println(textMatchWordzMiddle("abcz"));         // Not matched! (z last)
        System.out.println(textMatchWordzMiddle("a z b"));        // Not matched! (whole word)
        System.out.println(textMatchWordzMiddle("zzz"));          // Found a match! (middle z)
        System.out.println(textMatchWordzMiddle("snake_case_zed"));// Found a match!
    }
}

