     */

    /** Deterministic trial-division primality test (input fits comfortably in long). */
    private static boolean isPrime(long num) {
        if (num < 2) return false;
        if (num == 2 || num == 3) return true;
        if (num % 2 == 0 || num % 3 == 0) return false;
        for (long i = 5; i * i <= num; i += 6) {
            if (num % i == 0 || num % (i + 2) == 0) return false;
        }
        return true;
    }

    public static int newmanPrime(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        // NSW primes: primes belonging to the sequence
        //   a(0)=2, a(1)=3, a(k)=2*a(k-1)+a(k-2)  ->  2, 3, 7, 17, 41, 99, 239, ...
        List<Long> nswPrimes = new ArrayList<Long>();
        nswPrimes.add(2L);          // a(0)
        nswPrimes.add(3L);          // a(1)

        long prev = 2L;
        long cur  = 3L;

        while (nswPrimes.size() < n) {
            long next = 2L * cur + prev;
            if (next <= cur) {      // overflow guard, keeps the loop terminating
                throw new ArithmeticException("sequence overflowed long");
            }
            prev = cur;
            cur  = next;
            if (isPrime(cur)) {
                nswPrimes.add(cur);
            }
        }

        return nswPrimes.get(n - 1).intValue();
    }

    // Quick self-check of the documented examples
    public static void main(String[] args) {
        System.out.println(newmanPrime(1));  // 2
        System.out.println(newmanPrime(2));  // 3
        System.out.println(newmanPrime(3));  // 7
        System.out.println(newmanPrime(4));  // 17
        System.out.println(newmanPrime(5));  // 41
        System.out.println(newmanPrime(6));  // 239  (99 is skipped: not prime)
    }
}

