class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        if (cost == null || cost.isEmpty() || n <= 0)
            return 0.0;

        // the matrix is n x n (be tolerant if the supplied data is smaller/larger)
        int size = Math.min(n, cost.size());

        // dp[i][j] = maximum sum of a path (0,0) -> (i,j) using only right / down moves
        long[][] dp = new long[size][size];
        dp[0][0] = cell(cost, 0, 0);

        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (i == 0 && j == 0)
                    continue;

                long best;
                if (i > 0 && j > 0)
                    best = maxOf(dp[i - 1][j], dp[i][j - 1]);   // one mandatory + one optional arg
                else if (i > 0)
                    best = dp[i - 1][j];                        // first row/column
                else
                    best = dp[i][j - 1];

                dp[i][j] = best + cell(cost, i, j);
            }
        }

        // every such path visits exactly (2n - 1) cells
        int length = 2 * size - 1;
        return dp[size - 1][size - 1] / (double) length;
    }

    /**
     * Maximum of one or more values.
     * Declared as (first, rest...) so that a call with no arguments is a COMPILE-time
     * error instead of a runtime failure, and so that a for-each loop can be used.
     */
    private static long maxOf(long first, long... rest) {
        long max = first;
        for (long v : rest)
            if (v > max)
                max = v;
        return max;
    }

    /** Null-/bounds-tolerant accessor for matrix element (i, j). */
    private static long cell(List<List<Integer>> cost, int i, int j) {
        if (i < 0 || j < 0 || i >= cost.size())
            return 0L;
        List<Integer> row = cost.get(i);
        if (row == null || j >= row.size())
            return 0L;
        Integer v = row.get(j);
        return v == null ? 0L : v.longValue();
    }
}

