        // is flanked by word characters on BOTH sides (i.e. never first/last of a word).
        Matcher matcher = Z_IN_MIDDLE.matcher(text);
        return matcher.find() ? "Found a match!" : "Not matched!";
    }

    /* ------------------------------------------------------------------
     * Bulk helpers: fixed-arity overloads for the common cases plus ONE
     * varargs overload, so the implicit array is allocated only when more
     * than three texts are passed (the performance pattern from Ch. 8).
     * ------------------------------------------------------------------ */

    public static List<String> textMatchWordzMiddleAll(String t1) {
        List<String> out = new ArrayList<String>(1);
        out.add(textMatchWordzMiddle(t1));
        return out;
    }

    public static List<String> textMatchWordzMiddleAll(String t1, String t2) {
        List<String> out = new ArrayList<String>(2);
        out.add(textMatchWordzMiddle(t1));
        out.add(textMatchWordzMiddle(t2));
        return out;
    }

    public static List<String> textMatchWordzMiddleAll(String t1, String t2, String t3) {
        List<String> out = new ArrayList<String>(3);
        out.add(textMatchWordzMiddle(t1));
        out.add(textMatchWordzMiddle(t2));
        out.add(textMatchWordzMiddle(t3));
        return out;
    }

    public static List<String> textMatchWordzMiddleAll(String t1, String t2, String t3, String... rest) {
        List<String> out = textMatchWordzMiddleAll(t1, t2, t3);
        for (String t : rest) {
            out.add(textMatchWordzMiddle(t));
        }
        return out;
    }

    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));   // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));       // Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));     // Not matched!
        // sanity checks for the boundary rules
        System.out.println(textMatchWordzMiddle("az."));           // Not matched! (z at end)
        System.out.println(textMatchWordzMiddle(".za"));           // Not matched! (z at start)
        System.out.println(textMatchWordzMiddle("say zebra now"));// Not matched!
        System.out.println(textMatchWordzMiddle("buzzzzle"));      // Not matched!
        System.out.println(textMatchWordzMiddle("a z b"));         // Not matched! (z alone)
        System.out.println(textMatchWordzMiddle("coziness"));      // Found a match!
    }
}

