class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */

    /* Helper: returns the larger of the supplied candidate values.
       Following the varargs guidance, a mandatory parameter comes first,
       then the optional ones, so no empty-array allocation happens for the
       common (one/two argument) calls. */
    private static int bestOf(int first, int... rest) {
        int best = first;
        for (int v : rest) {
            if (v > best) best = v;
        }
        return best;
    }

    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against degenerate input
        if (cost == null || cost.isEmpty() || n <= 0) {
            return 0.0;
        }

        // dp[i][j] = maximum sum of any path from (0,0) to (i,j)
        int[][] dp = new int[n][n];

        for (int i = 0; i < n; i++) {
            List<Integer> row = cost.get(i);
            for (int j = 0; j < n; j++) {
                int value = row.get(j);

                if (i == 0 && j == 0) {
                    dp[i][j] = value;                       // start cell
                } else if (i == 0) {
                    dp[i][j] = value + dp[i][j - 1];        // only from the left
                } else if (j == 0) {
                    dp[i][j] = value + dp[i - 1][j];        // only from above
                } else {
                    // come either from the cell above or the cell on the left
                    dp[i][j] = value + bestOf(dp[i - 1][j], dp[i][j - 1]);
                }
            }
        }

        // Every corner-to-corner path has exactly (2n - 1) cells
        double maxSum = dp[n - 1][n - 1];
        double pathLength = 2.0 * n - 1.0;

        return maxSum / pathLength;
    }

    // Quick self-test
    public static void main(String[] args) {
        System.out.println(maxaverageofpath(
            Arrays.asList(Arrays.asList(1, 2, 3),
                          Arrays.asList(6, 5, 4),
                          Arrays.asList(7, 3, 9)), 3));   // 5.2

        System.out.println(maxaverageofpath(
            Arrays.asList(Arrays.asList(2, 3, 4),
                          Arrays.asList(7, 6, 5),
                          Arrays.asList(8, 4, 10)), 3));  // 6.2

        System.out.println(maxaverageofpath(
            Arrays.asList(Arrays.asList(3, 4, 5),
                          Arrays.asList(8, 7, 6),
                          Arrays.asList(9, 5, 11)), 3));  // 7.2
    }
}

