class SeriesSum {
    /**
     * * Write a function to calculate the sum of series 1²+2²+3²+….+n².
     *
     * > seriesSum(6)
     * 91
     * > seriesSum(7)
     * 140
     * > seriesSum(12)
     * 650
     */
    public static int seriesSum(int number) {
        // No terms to add for non-positive input: return the empty sum (0),
        // never a "special" value that clients would have to test for.
        if (number <= 0) {
            return 0;
        }

        // Closed form: 1^2 + 2^2 + ... + n^2 = n * (n + 1) * (2n + 1) / 6
