class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Never return null for "nothing to compute": return a valid number instead.
        if (cost == null || cost.isEmpty() || n <= 0) {
            return 0.0;
        }

        // Work with the real dimensions of the matrix (defensive against mismatched input).
        int rows = Math.min(n, cost.size());
        int cols = rows;
        for (List<Integer> row : cost) {
            if (row != null) {
                cols = Math.min(cols, row.size());
            }
        }
        if (rows == 0 || cols == 0) {
            return 0.0;
        }

        // dp[i][j] = maximum sum of any down/right path ending at (i, j)
        double[][] dp = new double[rows][cols];
        dp[0][0] = (double) cost.get(0).get(0);

        for (int i = 0; i < rows; i++) {
            List<Integer> row = cost.get(i);
            for (int j = 0; j < cols; j++) {
                if (i == 0 && j == 0) {
                    continue;
                }
                double best = Double.NEGATIVE_INFINITY;
                if (i > 0) {
                    best = Math.max(best, dp[i - 1][j]);      // came from above
                }
                if (j > 0) {
                    best = Math.max(best, dp[i][j - 1]);      // came from the left
                }
                Integer val = (row == null) ? null : row.get(j);
                dp[i][j] = best + (val == null ? 0 : val.doubleValue());
            }
        }

        // Every such path visits exactly (2n - 1) cells.
        int pathLength = rows + cols - 1;
        if (pathLength <= 0) {
            return 0.0;
        }
        double average = dp[rows - 1][cols - 1] / pathLength;

        // Round to one decimal place to match the expected output format.
        average = Math.round(average * 10.0) / 10.0;
        return average;
    }

    // Simple driver for local testing
    public static void main(String[] args) {
        List<List<Integer>> m1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9));
        List<List<Integer>> m2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10));
        List<List<Integer>> m3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11));

        System.out.println(maxaverageofpath(m1, 3)); // 5.2
        System.out.println(maxaverageofpath(m2, 3)); // 6.2
        System.out.println(maxaverageofpath(m3, 3)); // 7.2
    }
}

