class TextMatchWordzMiddle {
    /**
     * * Write a function that matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null) {
            return "Not matched!";
        }

        // \b      -> start of a word
        // \w+     -> at least one character BEFORE 'z'  (z is not first)
        // z       -> the letter we are looking for
        // \w+     -> at least one character AFTER  'z'  (z is not last)
        // \b      -> end of the word
        String regex = "\\b\\w+z\\w+\\b";

        Pattern pattern = Pattern.compile(regex);
        Matcher matcher = pattern.matcher(text);

        // Express the outcome with an Optional instead of returning null:
        //   Optional.of(group)  -> a match was found (group is never null here)
        //   Optional.empty()    -> no match at all
        Optional<String> matchedWord = matcher.find()
                ? Optional.of(matcher.group())
                : Optional.<String>empty();

        return matchedWord.isPresent() ? "Found a match!" : "Not matched!";
    }

    // Simple driver to exercise the examples above
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));     // Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));   // Not matched!
        System.out.println(textMatchWordzMiddle("abcz."));       // Not matched!
        System.out.println(textMatchWordzMiddle("zabc."));       // Not matched!
        System.out.println(textMatchWordzMiddle("a z b."));      // Not matched!
        System.out.println(textMatchWordzMiddle("ab_z_c."));     // Found a match!
    }
}

