class NewmanPrime {
    /**
     * Returns the nth Newman&ndash;Shanks&ndash;Williams (NSW) prime number.
     *
     * <p>The NSW numbers are generated by the recurrence
     * <pre>
     *   S(0) = 1, S(1) = 1, S(k) = 2 * S(k-1) + S(k-2)
     * </pre>
     * which produces <code>1, 1, 3, 7, 17, 41, 99, 239, ...</code>; the prime
     * members of that sequence are the Newman&ndash;Shanks&ndash;Williams primes
     * <code>7, 17, 41, ...</code>.
     *
     * <p><b>Precondition:</b> {@code n >= 0}. Each unchecked exception thrown by
     * this method corresponds to a violation of that precondition.
     *
     * <p><b>Postcondition:</b> on successful completion the nth NSW number is
     * returned; e.g. {@code newmanPrime(3) == 7}, {@code newmanPrime(4) == 17},
     * {@code newmanPrime(5) == 41}.
     *
     * <p><b>Side effects:</b> none &mdash; the method performs no I/O, starts no
     * threads, and mutates no state outside its own activation record, so it is
     * safe to call concurrently.
     *
     * @param n the 1-based index of the NSW prime to compute; must not be negative
     * @return the nth Newman&ndash;Shanks&ndash;Williams prime number
     * @throws IllegalArgumentException if {@code n} is negative
     */
    public static int newmanPrime(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must not be negative: " + n);
        }
        if (n <= 1) {
            return 1;                       // S(0) = S(1) = 1
        }

        long prev = 1;                      // S(i-2)
        long curr = 1;                      // S(i-1)
        for (int i = 2; i <= n; i++) {
            long next = 2L * curr + prev;   // S(i) = 2*S(i-1) + S(i-2)
            prev = curr;
            curr = next;
        }
        return (int) curr;
    }
}

