class TextMatchWordzMiddle {
    /**
     * Returns {@code "Found a match!"} if the given text contains a word
     * that holds the letter {@code 'z'} in a position that is neither the
     * first nor the last character of that word, otherwise returns
     * {@code "Not matched!"}.
     *
     * <p>A "word" is any maximal run of {@code \w} characters
     * (letters, digits and underscores), so punctuation and whitespace
     * act as word separators. The search relies on the fact that the
     * regular expression {@code \w+z\w+} can only match when a word
     * character occurs immediately before and immediately after the
     * {@code 'z'}, and since {@code \w} cannot cross a separator, both
     * neighbours belong to the very same word.
     *
     * <p>Examples:
     *
     * <pre>{@code
     * textMatchWordzMiddle("pythonzabc.")   // "Found a match!"
     * textMatchWordzMiddle("xyzabc.")       // "Found a match!"
     * textMatchWordzMiddle("  lang  .")     // "Not matched!"
     * }</pre>
     *
     * @param text the possibly empty text to be searched; may be {@code null},
     *             in which case the result is {@code "Not matched!"}
     * @return {@code "Found a match!"} when a word containing {@code 'z'}
     *         strictly in its interior exists, else {@code "Not matched!"}
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null) {
            return "Not matched!";
        }

        // \w+z\w+  =>  a word character, then 'z', then a word character,
        //              all inside a single word (separators break the run).
        Pattern pattern = Pattern.compile("\\w+z\\w+");
        Matcher matcher = pattern.matcher(text);

        if (matcher.find()) {
            return "Found a match!";
        }
        return "Not matched!";
    }
}

public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
    // Dynamic programming table to store maximum sum to each cell
    int[][] dp = new int[n][n];
    dp[0][0] = cost.get(0).get(0);

    // Fill first row (can only come from left)
    for (int j = 1; j < n; j++) {
        dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
    }

    // Fill first column (can only come from above)
    for (int i = 1; i < n; i++) {
        dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
    }

    // Fill remaining cells: choose max from above or left
    for (int i = 1; i < n; i++) {
        for (int j = 1; j < n; j++) {
            dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
        }
    }

    // Every path visits exactly 2n-1 cells, so average = maxSum / (2n-1)
    return (double) dp[n - 1][n - 1] / (2 * n - 1);
}

