    public static int countVowels(String testStr) {
        // Fewer than two characters -> nobody can have a neighbour.
        if (testStr == null || testStr.length() < 2) {
            return 0;
        }

        String str = testStr.toLowerCase();
        int n = str.length();
        int count = 0;

        for (int i = 0; i < n; i++) {
            char current = str.charAt(i);

            // Vowels themselves are never counted; only their neighbours are.
            if (isVowel(current)) {
                continue;
            }

            boolean leftIsVowel  = (i > 0)     && isVowel(str.charAt(i - 1));
            boolean rightIsVowel = (i < n - 1) && isVowel(str.charAt(i + 1));

            if (leftIsVowel || rightIsVowel) {
                count++;
            }
        }

        return count;
    }

    /** Returns true when {@code ch} is one of a, e, i, o, u. */
    private static boolean isVowel(char ch) {
        return ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u';
    }

    // Quick self-check against the documented examples.
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

