/**
 * Utility class providing a single regular-expression based text check:
 * whether a word contains the letter 'z' somewhere strictly inside the word.
 *
 * <p><b>Thread safety:</b> every member of this class is {@code static} and
 * stateless, therefore this class is thread-safe. No synchronization is needed
 * by callers.</p>
 *
 * @author Expert Java Developer
 * @since 1.0
 */
class TextMatchWordzMiddle {
    /**
     * Matches a word containing the letter {@code 'z'}, where the {@code 'z'}
     * is neither at the start nor at the end of that word.
     *
     * <p>The detection uses the regular expression {@code (?<=\w)z(?=\w)},
     * i.e. a {@code 'z'} that is immediately preceded by a word character and
     * immediately followed by a word character. Both look-arounds are
     * zero-width and fixed-length, which keeps the pattern linear-time and
     * portable across regex engines.</p>
     *
     * <p>Examples:</p>
     * <blockquote><pre>
     * textMatchWordzMiddle("pythonzabc.")  &rarr; "Found a match!"
     * textMatchWordzMiddle("xyzabc.")      &rarr; "Found a match!"
     * textMatchWordzMiddle("  lang  .")     &rarr; "Not matched!"
     * </pre></blockquote>
     *
     * @param text the text to inspect; may be {@code null} or empty, in which
     *             case {@code "Not matched!"} is returned
     * @return the string {@code "Found a match!"} when at least one word holds
     *         an interior {@code 'z'}, otherwise {@code "Not matched!"};
     *         never {@code null}
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        // 'z' bounded by word characters on BOTH sides => interior of a word.
        Pattern pattern = Pattern.compile("(?<=\\w)z(?=\\w)");
        Matcher matcher = pattern.matcher(text);

        return matcher.find() ? "Found a match!" : "Not matched!";
    }
}

