/**
 * Utility for computing path statistics over square matrices.
 *
 * <p><b>Thread safety:</b> All methods of this class are stateless and
 * therefore thread-safe; they perform no shared mutable access.</p>
 */
class Maxaverageofpath {
    /**
     * Writes a function to find a path with the maximum average over all
     * existing paths for the given square matrix of size n*n.
     *
     * <p>A path starts at the top-left cell {@code (0,0)} and ends at the
     * bottom-right cell {@code (n-1,n-1)}, moving only right or down at each
     * step. Because every such path visits exactly {@code 2n - 1} cells,
     * maximizing the average is equivalent to maximizing the total sum, which
     * is solved here with a dynamic program running in {@code O(n^2)} time
     * and {@code O(n^2)} space.</p>
     *
     * <p>This method is thread-safe (it touches no shared state).</p>
     *
     * <blockquote><pre>
     * &gt; maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * &gt; maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * &gt; maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     * </pre></blockquote>
     *
     * @param cost the square matrix of non-null row lists to traverse;
     *             row {@code i} is {@code cost.get(i)}
     * @param n    the dimension of the square matrix ({@code n >= 1})
     * @return the largest possible average over all top-left to bottom-right
     *         right/down paths, as a {@link Double}; {@code 0.0} if {@code n}
     *         is zero
     * @throws IndexOutOfBoundsException if {@code cost} holds fewer than
     *                                   {@code n} rows or a row holds fewer
     *                                   than {@code n} elements
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        if (n <= 0) {
            return 0.0;
        }

        // dp[i][j] = maximum sum of any path from (0,0) to (i,j)
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                long bestFromTop = (i > 0) ? dp[i - 1][j] : Long.MIN_VALUE / 4;
                long bestFromLeft = (j > 0) ? dp[i][j - 1] : Long.MIN_VALUE / 4;

                long incoming;
                if (i == 0 && j == 0) {
                    incoming = 0L;
                } else if (i == 0) {
                    incoming = bestFromLeft;
                } else if (j == 0) {
                    incoming = bestFromTop;
                } else {
                    incoming = Math.max(bestFromTop, bestFromLeft);
                }

                dp[i][j] = incoming + cost.get(i).get(j).longValue();
            }
        }

        // Every right/down path visits exactly (2n - 1) cells.
        double count = (double) (2L * n - 1L);
        return dp[n - 1][n - 1] / count;
    }
}

