class SeriesSum {
    /**
     * * Write a function to calculate the sum of series 1²+2²+3²+….+n².
     *
     * > seriesSum(6)
     * 91
     * > seriesSum(7)
     * 140
     * > seriesSum(12)
     * 650
     *
     * <p>Computes the sum of the squares of the first {@code number}
     * positive integers using the closed form
     * {@code n(n+1)(2n+1)/6}. Intermediate products are evaluated in
     * {@code long} to avoid overflow before the division is applied.
     * For any non-positive {@code number} there are no terms to add,
     * so {@code 0} is returned.</p>
     *
     * @param number the upper bound of the series; the sum runs from
     *               {@code 1} up to and including {@code number}
     * @return the value of {@code 1² + 2² + ... + number²}, or
     *         {@code 0} if {@code number <= 0}
     */
    public static int seriesSum(int number) {
        if (number <= 0) {
            return 0;
        }
        // n(n+1)(2n+1)/6, computed in long to keep the product exact.
        long n = number;
        long sum = n * (n + 1) * (2 * n + 1) / 6;
        return (int) sum;
    }
}

