import java.math.*;


/**
 * Utility methods for computing statistics of monotone (right/down) paths
 * through a square matrix.
 *
 * <p>The single entry point of this class is {@link #maxaverageofpath(List, int)},
 * which finds the path from the top-left corner to the bottom-right corner
 * having the largest arithmetic mean over all its visited cells.</p>
 */
class Maxaverageofpath {
    /**
     * Finds a path with the maximum average over all existing paths for the
     * given square matrix of size {@code n * n}.
     *
     * <p>A path starts at cell {@code (0, 0)} and ends at cell
     * {@code (n-1, n-1)}, moving only one step to the right or one step down
     * at a time. Every such path visits exactly {@code 2n - 1} cells, so the
     * path with the maximum average is simply the path with the maximum sum,
     * divided by {@code 2n - 1}. The optimal sum is obtained with the classic
     * dynamic program
     * {@code dp[i][j] = cost[i][j] + max(dp[i-1][j], dp[i][j-1])}.</p>
     *
     * <p>Example:</p>
     * <blockquote><pre>
     * maxaverageofpath([[1, 2, 3],
     *                   [6, 5, 4],
     *                   [7, 3, 9]], 3)  &rarr; 5.2
     * </pre></blockquote>
     *
     * @param cost a non-null {@code n x n} matrix of cell costs; the element
     *             at row {@code i}, column {@code j} is {@code cost.get(i).get(j)}
     * @param n    the side length of the square matrix, {@code n >= 1}
     * @return the maximum achievable average as a {@link Double}; returns
     *         {@code 0.0} if {@code cost} is {@code null} or {@code n <= 0}
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard clauses: nothing to average over.
        if (cost == null || n <= 0 || cost.isEmpty()) {
            return 0.0;
        }

        // dp[i][j] = largest sum of any right/down path ending at (i, j).
        double[][] dp = new double[n][n];

        for (int i = 0; i < n; i++) {
            List<Integer> row = cost.get(i);
            for (int j = 0; j < n; j++) {
                double value = (row != null ? row.get(j) : 0);

                if (i == 0 && j == 0) {
                    // Starting cell: the path consists of this cell alone.
                    dp[i][j] = value;
                } else if (i == 0) {
                    // First row: can only come from the left.
                    dp[i][j] = dp[i][j - 1] + value;
                } else if (j == 0) {
                    // First column: can only come from above.
                    dp[i][j] = dp[i - 1][j] + value;
                } else {
                    // Interior cell: take the better of the two predecessors.
                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + value;
                }
            }
        }

        // Every valid path has exactly (2n - 1) cells, so the average is
        // simply the maximal sum divided by the (constant) path length.
        double pathLength = 2.0 * n - 1.0;
        return dp[n - 1][n - 1] / pathLength;
    }

    /**
     * Self-check entry point exercising the documented examples.
     *
     * @param args unused command line arguments
     */
    public static void main(String[] args) {
        System.out.println(maxaverageofpath(
                Arrays.asList(Arrays.asList(1, 2, 3),
                              Arrays.asList(6, 5, 4),
                              Arrays.asList(7, 3, 9)), 3));   // 5.2

        System.out.println(maxaverageofpath(
                Arrays.asList(Arrays.asList(2, 3, 4),
                              Arrays.asList(7, 6, 5),
                              Arrays.asList(8, 4, 10)), 3));  // 6.2

        System.out.println(maxaverageofpath(
                Arrays.asList(Arrays.asList(3, 4, 5),
                              Arrays.asList(8, 7, 6),
                              Arrays.asList(9, 5, 11)), 3));  // 7.2
    }
}

