class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Degenerate case: nothing to traverse.
        if (n <= 0 || cost == null || cost.isEmpty()) {
            return 0.0;
        }

        // dp[i][j] holds the maximum SUM of any path from (0,0) to (i,j).
        int[][] dp = new int[n][n];

        // Fill the table row by row; every loop variable keeps the smallest
        // possible scope (it exists only inside its own for statement).
        for (int i = 0; i < n; i++) {
            List<Integer> row = cost.get(i);           // fetched once, not per element
            for (int j = 0; j < n; j++) {
                if (i == 0 && j == 0) {
                    dp[i][j] = row.get(j);             // start cell
                    continue;
                }
                int bestFromAbove = (i > 0) ? dp[i - 1][j] : Integer.MIN_VALUE;
                int bestFromLeft  = (j > 0) ? dp[i][j - 1] : Integer.MIN_VALUE;
                dp[i][j] = Math.max(bestFromAbove, bestFromLeft) + row.get(j);
            }
        }

        // Every valid path visits exactly (2n - 1) cells, so maximizing the
        // average is the same as maximizing the sum.
        return dp[n - 1][n - 1] / (double) (2 * n - 1);
    }

    // Small, focused driver kept separate from the algorithm itself.
    private static void runExample(int[][] matrix) {
        int n = matrix.length;
        List<List<Integer>> grid = new ArrayList<>();
        for (int[] r : matrix) {                       // fresh loop variable, no clash
            grid.add(new ArrayList<>());
            for (int v : r) {
                grid.get(grid.size() - 1).add(v);
            }
        }
        System.out.println(maxaverageofpath(grid, n));
    }

    public static void main(String[] args) {
        runExample(new int[][]{{1, 2, 3}, {6, 5, 4}, {7, 3, 9}});   // 5.2
        runExample(new int[][]{{2, 3, 4}, {7, 6, 5}, {8, 4, 10}});  // 6.2
        runExample(new int[][]{{3, 4, 5}, {8, 7, 6}, {9, 5, 11}});  // 7.2
    }
}

