class TextMatchWordzMiddle {

    /**
     * Compiled once and reused: Pattern.compile() is relatively costly,
     * so we never build it inside the method.
     *   \B   -> we are NOT at a word boundary, therefore the character
     *           immediately before 'z' is a word character  => 'z' is not
     *           the first character of the word.
     *   z    -> the literal letter we look for.
     *   \w*  -> the rest of the word ([A-Za-z0-9_]).
     */
    private static final Pattern WORD_WITH_Z_IN_MIDDLE = Pattern.compile("\\Bz\\w*");

    /**
     * * Write a function that matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }
        // find() scans for the first occurrence anywhere in the input,
        // unlike matches() which would require the entire input to match.
        Matcher matcher = WORD_WITH_Z_IN_MIDDLE.matcher(text);
        return matcher.find() ? "Found a match!" : "Not matched!";
    }

    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));  // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));      // Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));    // Not matched!
    }
}

