class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // dp[i][j] stores the maximum sum to reach cell (i, j)
        int[][] dp = new int[n][n];

        dp[0][0] = cost.get(0).get(0);

        // Fill first column (only reachable by moving down)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill first row (only reachable by moving right)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill rest of the table: come from above or left, whichever gives larger sum
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
            }
        }

        // Total path length is always 2n - 1 (n-1 down + n-1 right + starting cell)
        int pathLength = 2 * n - 1;
        return dp[n - 1][n - 1] / (double) pathLength;
    }
}

public static int countVowels(String testStr) {
    String vowels = "aeiouAEIOU";
    int count = 0;
    char[] chars = testStr.toCharArray();
    for (int i = 0; i < chars.length; i++) {
        // Only count non-vowel characters
        if (vowels.indexOf(chars[i]) != -1) continue;
        // Check left neighbor
        if (i > 0 && vowels.indexOf(chars[i - 1]) != -1) {
            count++;
        }
        // Check right neighbor
        else if (i < chars.length - 1 && vowels.indexOf(chars[i + 1]) != -1) {
            count++;
        }
    }
    return count;
}

