class CountVowels {
    /** true if the character is a vowel (case insensitive) */
    private static boolean isVowel(char ch) {
        switch (ch) {
            case 'a': case 'e': case 'i': case 'o': case 'u':
            case 'A': case 'E': case 'I': case 'O': case 'U':
                return true;
            default:
                return false;
        }
    }

    /**
     * * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        char[] chars = testStr.toCharArray();
        int n = chars.length;
        int count = 0;

        for (int i = 0; i < n; i++) {
            char current = chars[i];

            // Only non-vowel characters can contribute to the count
            if (isVowel(current)) {
                continue;
            }

            // Check the left neighbour (if any)
            boolean leftIsVowel  = (i > 0)     && isVowel(chars[i - 1]);
            // Check the right neighbour (if any)
            boolean rightIsVowel = (i < n - 1) && isVowel(chars[i + 1]);

            if (leftIsVowel || rightIsVowel) {
                count++;   // plain primitive increment – no boxing, no identity checks
            }
        }

        return count;
    }

    // quick self-test
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));           // 7
        System.out.println(countVowels("partofthejourneyistheend"));  // 12
        System.out.println(countVowels("amazonprime"));               // 5
    }
}

