import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n == 1) return 2;

        int count = 1; // already counted 2
        long q0 = 1, q1 = 1;

        while (true) {
            long q = 2 * q1 + q0;
            q0 = q1;
            q1 = q;

            if (isPrime((int) q)) {
                count++;
                if (count == n) return (int) q;
            }
        }
    }

    private static boolean isPrime(int num) {
        if (num < 2) return false;
        if (num == 2) return true;
        if (num % 2 == 0) return false;
        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) return false;
        }
        return true;
    }
}

