class CountVowels {
    /**
     * * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        // Guard against null / strings too short to have any neighbours
        if (testStr == null) {
            return 0;
        }

        final String vowels = "aeiouAEIOU";
        final int n = testStr.length();          // primitive int, never Integer -> no unboxing NPE
        int count = 0;

        for (int i = 0; i < n; i++) {
            char c = testStr.charAt(i);

            // A vowel itself is not "having a vowel as a neighbour"; skip it.
            if (vowels.indexOf(c) >= 0) {
                continue;
            }

            boolean leftIsVowel  = (i > 0)      && (vowels.indexOf(testStr.charAt(i - 1)) >= 0);
            boolean rightIsVowel = (i < n - 1)   && (vowels.indexOf(testStr.charAt(i + 1)) >= 0);

            if (leftIsVowel || rightIsVowel) {
                count++;                          // primitive increment, no boxing involved
            }
        }

        return count;                             // auto-unboxed safely: always a real int
    }

    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));              // 7
        System.out.println(countVowels("partofthejourneyistheend"));    // 12
        System.out.println(countVowels("amazonprime"));                 // 5
    }
}

