     */
    public static int newmanPrime(int n) {
        if (n <= 1) return 1;
        int prev2 = 1; // a(0)
        int prev1 = 1; // a(1)
        for (int i = 2; i <= n; i++) {
            int current = 2 * prev1 + prev2;
            prev2 = prev1;
            prev1 = current;
        }
        return prev1;
    }
}

