class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths
     * for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Degenerate input: nothing to average.
        if (cost == null || n <= 0 || cost.size() < n) {
            return Double.valueOf(0.0d);
        }

        // Every top-left -> bottom-right path (only right/down moves) visits
        // exactly (2n - 1) cells, so the denominators are identical for all
        // paths. Maximizing the average == maximizing the sum.
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            List<Integer> row = cost.get(i);
            for (int j = 0; j < n; j++) {
                long value = row.get(j).intValue();   // primitive long, no boxing

                if (i == 0 && j == 0) {
                    dp[i][j] = value;
                } else if (i == 0) {
                    dp[i][j] = dp[i][j - 1] + value;
                } else if (j == 0) {
                    dp[i][j] = dp[i - 1][j] + value;
                } else {
                    long up = dp[i - 1][j];
                    long left = dp[i][j - 1];
                    dp[i][j] = (up > left ? up : left) + value;
                }
            }
        }

        // Primitive arithmetic throughout; the single required boxing
        // (Long -> Double) happens only here at the return.
        double cells = (double) (2 * n - 1);
        double average = dp[n - 1][n - 1] / cells;

        return Double.valueOf(average);
    }

    // Small driver to demonstrate the given examples.
    public static void main(String[] args) {
        System.out.println(maxaverageofpath(
                Arrays.asList(Arrays.asList(1, 2, 3),
                              Arrays.asList(6, 5, 4),
                              Arrays.asList(7, 3, 9)), 3));   // 5.2

        System.out.println(maxaverageofpath(
                Arrays.asList(Arrays.asList(2, 3, 4),
                              Arrays.asList(7, 6, 5),
                              Arrays.asList(8, 4, 10)), 3));  // 6.2

        System.out.println(maxaverageofpath(
                Arrays.asList(Arrays.asList(3, 4, 5),
                              Arrays.asList(8, 7, 6),
                              Arrays.asList(9, 5, 11)), 3));   // 7.2
    }
}

