class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        if (cost == null || n <= 0 || cost.isEmpty() || cost.get(0).isEmpty()) {
            return null;
        }

        // Every right/down path visits exactly (2n - 1) cells,
        // so maximizing the average == maximizing the total sum.
        int[][] dp = new int[n][n];

        dp[0][0] = cost.get(0).get(0);

        // Only reachable from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Only reachable from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Best of "come from above" vs "come from the left"
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        int cellsOnPath = 2 * n - 1;
        return dp[n - 1][n - 1] / (double) cellsOnPath;
    }

    public static void main(String[] args) {
        System.out.println(maxaverageofpath(
                Arrays.asList(Arrays.asList(1, 2, 3), Arrays.asList(6, 5, 4), Arrays.asList(7, 3, 9)), 3)); // 5.2
        System.out.println(maxaverageofpath(
                Arrays.asList(Arrays.asList(2, 3, 4), Arrays.asList(7, 6, 5), Arrays.asList(8, 4, 10)), 3)); // 6.2
        System.out.println(maxaverageofpath(
                Arrays.asList(Arrays.asList(3, 4, 5), Arrays.asList(8, 7, 6), Arrays.asList(9, 5, 11)), 3)); // 7.2
    }
}

