class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // DP table to store maximum sum path ending at each cell
        int[][] dp = new int[n][n];

        // Initialize base cases
        dp[0][0] = cost.get(0).get(0);

        // Fill first row (only reachable by moving right)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill first column (only reachable by moving down)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill rest of the table: each cell takes max from above or left
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }

        // All paths from (0,0) to (n-1,n-1) visit exactly (2n-1) cells
        // So max average = max sum / (2n - 1)
        int pathLength = 2 * n - 1;
        return (double) dp[n - 1][n - 1] / pathLength;
    }
}

class CountVowels {
    /**
     * * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        int count = 0;
        for (int i = 0; i < testStr.length(); i++) {
            char c = testStr.charAt(i);
            // Skip vowels — we only count non-vowel characters
            if (isVowel(c)) {
                continue;
            }
            // Check if at least one neighbor (left or right) is a vowel
            boolean hasVowelNeighbor = false;
            if (i > 0 && isVowel(testStr.charAt(i - 1))) {
                hasVowelNeighbor = true;
            }
            if (i < testStr.length() - 1 && isVowel(testStr.charAt(i + 1))) {
                hasVowelNeighbor = true;
            }
            if (hasVowelNeighbor) {
                count++;
            }
        }
        return count;
    }

    private static boolean isVowel(char c) {
        c = Character.toLowerCase(c);
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }
}

