            return cost.get(0).get(0).doubleValue();
        }

        // dp[i][j] = maximum sum of any right/down path ending at cell (i, j)
        List<List<Integer>> dp = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            List<Integer> row = new ArrayList<>(Collections.nCopies(n, 0));
            dp.add(row);
        }

        dp.get(0).set(0, cost.get(0).get(0));

        // First column: can only come from above
        for (int i = 1; i < n; i++) {
            dp.get(i).set(0, cost.get(i).get(0) + dp.get(i - 1).get(0));
        }

        // First row: can only come from the left
        for (int j = 1; j < n; j++) {
            dp.get(0).set(j, cost.get(0).get(j) + dp.get(0).get(j - 1));
        }

        // Interior cells: best of "from above" vs "from left"
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                int best = Math.max(dp.get(i - 1).get(j), dp.get(i).get(j - 1));
                dp.get(i).set(j, cost.get(i).get(j) + best);
            }
        }

        int maxSum = dp.get(n - 1).get(n - 1);
        int steps = 2 * n - 1;              // every path has exactly this many cells
        return maxSum / (double) steps;
    }
}

