class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // --- basic sanity checks -------------------------------------------------
        if (cost == null || cost.isEmpty() || n <= 0) {
            return 0.0;
        }
        int size = Math.min(n, cost.size());
        if (size == 1) {
            return (double) cost.get(0).get(0);
        }

        // --- DP: maximum path sum from (0,0) to (i,j) ----------------------------
        // Moves allowed: only RIGHT and DOWN, therefore every path contains
        // exactly (2*size - 1) cells, so maximizing the sum == maximizing the
        // average (average = sum / (2*size - 1)).
        int[][] dp = new int[size][size];

        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                int value = cost.get(i).get(j);

                if (i == 0 && j == 0) {
                    dp[i][j] = value;                       // start cell
                } else if (i == 0) {
                    dp[i][j] = dp[i][j - 1] + value;        // first row: come from the left
                } else if (j == 0) {
                    dp[i][j] = dp[i - 1][j] + value;        // first column: come from above
                } else {
                    dp[i][j] = Math.max(dp[i - 1][j],       // from above
                                        dp[i][j - 1]) + value; // or from the left
                }
            }
        }

        // --- average of the best path -------------------------------------------
        int pathCells = 2 * size - 1;   // number of cells in any valid path
        double bestSum = dp[size - 1][size - 1];

        return bestSum / pathCells;
    }

    // quick self-test
    public static void main(String[] args) {
        System.out.println(maxaverageofpath(
                Arrays.asList(Arrays.asList(1, 2, 3),
                              Arrays.asList(6, 5, 4),
                              Arrays.asList(7, 3, 9)), 3));   // 5.2
        System.out.println(maxaverageofpath(
                Arrays.asList(Arrays.asList(2, 3, 4),
                              Arrays.asList(7, 6, 5),
                              Arrays.asList(8, 4, 10)), 3));  // 6.2
        System.out.println(maxaverageofpath(
                Arrays.asList(Arrays.asList(3, 4, 5),
                              Arrays.asList(8, 7, 6),
                              Arrays.asList(9, 5, 11)), 3));  // 7.2
    }
}

