class SeriesSum {
    /**
     * * Write a function to calculate the sum of series 1²+2²+3²+….+n².
     *
     * > seriesSum(6)
     * 91
     * > seriesSum(7)
     * 140
     * > seriesSum(12)
     * 650
     */
    public static int seriesSum(int number) {
        // Base case: empty series sums to 0
        if (number <= 0) {
            return 0;
        }

        // Closed form: 1^2 + 2^2 + ... + n^2 = n(n+1)(2n+1)/6
        // Compute in long so the product cannot overflow before the division,
        // then divide exactly (the product is always divisible by 6).
        long n = number;
        long sum = n * (n + 1) * (2 * n + 1) / 6;

        return (int) sum;
    }

    // Simple, obviously-correct reference implementation (the "unoptimized"
    // baseline we compare against before optimizing).
    private static int seriesSumLoop(int number) {
        int sum = 0;
        for (int i = 1; i <= number; i++) {
            sum += i * i;
        }
        return sum;
    }

    public static void main(String[] args) {
        System.out.println(seriesSum(6));   // 91
        System.out.println(seriesSum(7));   // 140
        System.out.println(seriesSum(12));  // 650

        // Sanity check: formula matches the straightforward loop.
        for (int i = -5; i <= 2000; i++) {
            assert seriesSum(i) == seriesSumLoop(Math.max(i, 0));
        }
    }
}

