class CountVowels {
    /**
     * * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */

    /** Returns true if the character is an English vowel (case insensitive). */
    private static boolean isVowel(char ch) {
        switch (Character.toLowerCase(ch)) {
            case 'a':
            case 'e':
            case 'i':
            case 'o':
            case 'u':
                return true;
            default:
                return false;
        }
    }

    public static int countVowels(String testStr) {
        // A string shorter than 2 characters cannot have any neighbours.
        if (testStr == null || testStr.length() < 2) {
            return 0;
        }

        int n = testStr.length();
        int count = 0;

        for (int i = 0; i < n; i++) {
            char current = testStr.charAt(i);

            // Vowels themselves are never counted; only their neighbours are.
            if (isVowel(current)) {
                continue;
            }

            boolean hasLeftVowel  = (i > 0)      && isVowel(testStr.charAt(i - 1));
            boolean hasRightVowel = (i < n - 1)  && isVowel(testStr.charAt(i + 1));

            if (hasLeftVowel || hasRightVowel) {
                count++;
            }
        }

        return count;
    }

    // Quick self-check against the documented examples.
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

