class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        if (cost == null || n <= 0 || cost.isEmpty()) {
            return 0.0;
        }

        // Every right/down path from (0,0) to (n-1,n-1) has exactly (2n-1) cells,
        // so maximizing the average is identical to maximizing the sum.
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                long best = Long.MIN_VALUE;

                if (i > 0) {
                    best = Math.max(best, dp[i - 1][j]);   // came from above
                }
                if (j > 0) {
                    best = Math.max(best, dp[i][j - 1]);   // came from the left
                }

                long value = (cost.get(i) != null && j < cost.get(i).size())
                        ? cost.get(i).get(j)
                        : 0;

                dp[i][j] = (best == Long.MIN_VALUE) ? value : best + value;
            }
        }

        long maxSum = dp[n - 1][n - 1];
        int pathLength = 2 * n - 1;

        return ((double) maxSum) / pathLength;
    }
}

