    public static int newmanPrime(int n) {
        if (n == 1) return 1;
        if (n == 2) return 3;

        int a = 1;  // a[1]
        int b = 3;  // a[2]

        for (int i = 3; i <= n; i++) {
            int next = 2 * b + a;
            a = b;
            b = next;
        }
        return b;
    }

