import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard clauses: nothing to average over.
        if (cost == null || cost.isEmpty() || n <= 0) {
            return 0.0;
        }

        // Every path from (0,0) to (n-1,n-1) using only right/down moves
        // visits exactly 2n-1 cells, so maximizing the average is the same
        // as maximizing the sum of the visited cells.
        int[][] dp = new int[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int current = cost.get(i).get(j);

                if (i == 0 && j == 0) {
                    // Starting cell.
                    dp[i][j] = current;
                } else if (i == 0) {
                    // First row: can only come from the left.
                    dp[i][j] = dp[i][j - 1] + current;
                } else if (j == 0) {
                    // First column: can only come from above.
                    dp[i][j] = dp[i - 1][j] + current;
                } else {
                    // Take the better of "from above" and "from the left".
                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + current;
                }
            }
        }

        double total = dp[n - 1][n - 1];
        double length = 2 * n - 1;

        return total / length;
    }

    // Simple driver to exercise the examples above.
    public static void main(String[] args) {
        List<List<Integer>> first = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9));
        List<List<Integer>> second = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10));
        List<List<Integer>> third = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11));

        System.out.println(maxaverageofpath(first, 3));   // 5.2
        System.out.println(maxaverageofpath(second, 3));  // 6.2
        System.out.println(maxaverageofpath(third, 3));   // 7.2
    }
}

