class CountVowels {
    /** The set of characters regarded as vowels (both cases). */
    private static final String VOWEL_CHARS = "aeiouAEIOU";

    /**
     * * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        if (testStr == null || testStr.isEmpty()) {
            return 0;
        }

        int vowelNeighborCount = 0;
        int strLength = testStr.length();

        for (int index = 0; index < strLength; index++) {
            char currentChar = testStr.charAt(index);

            // Only consonants are candidates: a vowel itself is never counted.
            if (isVowel(currentChar)) {
                continue;
            }

            boolean hasLeftVowelNeighbor =
                    index > 0 && isVowel(testStr.charAt(index - 1));
            boolean hasRightVowelNeighbor =
                    index < strLength - 1 && isVowel(testStr.charAt(index + 1));

            if (hasLeftVowelNeighbor || hasRightVowelNeighbor) {
                vowelNeighborCount++;
            }
        }

        return vowelNeighborCount;
    }

    /** Returns true when the given character is one of a, e, i, o, u (case insensitive). */
    private static boolean isVowel(char character) {
        return VOWEL_CHARS.indexOf(character) >= 0;
    }

    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

