public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
    // DP table where dp[i][j] = max sum to reach cell (i,j) from (0,0)
    int[][] dp = new int[n][n];

    dp[0][0] = cost.get(0).get(0);

    // Fill first row (only reachable by moving right)
    for (int j = 1; j < n; j++) {
        dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
    }

    // Fill first column (only reachable by moving down)
    for (int i = 1; i < n; i++) {
        dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
    }

    // Fill rest of the table: each cell takes max from above or left
    for (int i = 1; i < n; i++) {
        for (int j = 1; j < n; j++) {
            dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
        }
    }

    // All paths visit exactly (2n - 1) cells
    int pathLength = 2 * n - 1;

    return (double) dp[n - 1][n - 1] / pathLength;
}

