        // Trivial / invalid input guard: nothing sensible to average.
        if (cost == null || cost.isEmpty() || n <= 0) {
            return 0.0;
        }

        // dp[i][j] = maximum sum of any path from (0,0) to (i,j),
        // moving only right or down.
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                long fromTop = (i > 0) ? dp[i - 1][j] : Long.MIN_VALUE / 4;
                long fromLeft = (j > 0) ? dp[i][j - 1] : Long.MIN_VALUE / 4;

                if (i == 0 && j == 0) {
                    dp[i][j] = cost.get(0).get(0);
                } else if (i == 0) {
                    dp[i][j] = fromLeft + cost.get(i).get(j);
                } else if (j == 0) {
                    dp[i][j] = fromTop + cost.get(i).get(j);
                } else {
                    dp[i][j] = Math.max(fromTop, fromLeft) + cost.get(i).get(j);
                }
            }
        }

        // Every top-left -> bottom-right path visits exactly (2n - 1) cells,
        // so the average equals the maximum path sum divided by that count.
        int steps = 2 * n - 1;
        return (double) dp[n - 1][n - 1] / steps;
    }
}

