class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against degenerate input (state testing, not exception-driven control flow)
        if (cost == null || cost.isEmpty() || n <= 0) {
            return 0.0;
        }

        // Work with the usable dimension of the matrix
        int size = Math.min(n, cost.size());
        for (List<Integer> row : cost) {
            if (row != null) {
                size = Math.min(size, row.size());
            }
        }
        if (size <= 0) {
            return 0.0;
        }

        // dp[i][j] = maximum sum of any path from (0,0) to (i,j)
        long[][] dp = new long[size][size];

        for (int i = 0; i < size; i++) {
            List<Integer> row = cost.get(i);
            if (row == null) {
                continue;
            }
            for (int j = 0; j < size && j < row.size(); j++) {
                Integer cell = row.get(j);
                long value = (cell == null) ? 0L : cell.longValue();

                if (i == 0 && j == 0) {
                    dp[i][j] = value;
                } else {
                    long best = Long.MIN_VALUE;
                    if (i > 0) {                       // coming from above
                        best = Math.max(best, dp[i - 1][j]);
                    }
                    if (j > 0) {                       // coming from the left
                        best = Math.max(best, dp[i][j - 1]);
                    }
                    dp[i][j] = best + value;
                }
            }
        }

        // Every path from (0,0) to (n-1,n-1) visiting only right/down steps
        // contains exactly (2n - 1) cells, so max average <=> max sum.
        int pathLength = 2 * size - 1;
        return dp[size - 1][size - 1] / (double) pathLength;
    }

    // Quick self-check
    public static void main(String[] args) {
        System.out.println(maxaverageofpath(
            Arrays.asList(Arrays.asList(1, 2, 3), Arrays.asList(6, 5, 4), Arrays.asList(7, 3, 9)), 3)); // 5.2
        System.out.println(maxaverageofpath(
            Arrays.asList(Arrays.asList(2, 3, 4), Arrays.asList(7, 6, 5), Arrays.asList(8, 4, 10)), 3)); // 6.2
        System.out.println(maxaverageofpath(
            Arrays.asList(Arrays.asList(3, 4, 5), Arrays.asList(8, 7, 6), Arrays.asList(9, 5, 11)), 3)); // 7.2
    }
}

