    // DP table where dp[i][j] = max sum to reach cell (i, j)
    int[][] dp = new int[n][n];

    // Base cases
    dp[0][0] = cost.get(0).get(0);

    // First column: can only come from above
    for (int i = 1; i < n; i++) {
        dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
    }

    // First row: can only come from left
    for (int j = 1; j < n; j++) {
        dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
    }

    // Fill remaining cells: max of coming from top or left
    for (int i = 1; i < n; i++) {
        for (int j = 1; j < n; j++) {
            dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
        }
    }

    // Total path length is always 2n - 1
    int pathLength = 2 * n - 1;
    return dp[n - 1][n - 1] / (double) pathLength;
}

