class CountVowels {
    /** Set of vowels (case insensitive handled explicitly). */
    private static final String VOWELS = "aeiouAEIOU";

    /**
     * * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        // Nothing to compare against: empty / null / single character strings.
        if (testStr == null || testStr.length() < 2) {
            return 0;
        }

        int len = testStr.length();
        int count = 0;

        for (int i = 0; i < len; i++) {
            char current = testStr.charAt(i);

            // Only characters that are NOT vowels are candidates:
            // a vowel itself does not "have a vowel as its neighbor" for this problem.
            if (isVowel(current)) {
                continue;
            }

            boolean leftIsVowel  = (i > 0)      && isVowel(testStr.charAt(i - 1));
            boolean rightIsVowel = (i < len - 1) && isVowel(testStr.charAt(i + 1));

            if (leftIsVowel || rightIsVowel) {
                count++;
            }
        }

        return count;
    }

    private static boolean isVowel(char c) {
        return VOWELS.indexOf(c) >= 0;
    }

    // Quick self-test / demo
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));            // 7
        System.out.println(countVowels("partofthejourneyistheend"));   // 12
        System.out.println(countVowels("amazonprime"));               // 5
        System.out.println(countVowels(""));                          // 0
        System.out.println(countVowels("a"));                         // 0
        System.out.println(countVowels("bae"));                       // 1  (b touches 'a')
    }
}

