class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Item 72: favor standard exceptions.
        // An index that must be >= 1 but isn't -> illegal argument.
        if (n < 1) {
            throw new IllegalArgumentException(
                "Index must be positive, but was: " + n);
        }

        // NSW recurrence: S(k) = 2*S(k-1) + S(k-2), with S(1) = S(2) = 1
        int prev = 1; // S(k-2)
        int curr = 1; // S(k-1)

        for (int i = 2; i <= n; i++) {
            int next = 2 * curr + prev;
            prev = curr;
            curr = next;
        }

        // curr now holds S(n):  1, 3, 7, 17, 41, 99, 239, ...
        return curr;
    }

    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

