class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Validate the input at this abstraction level rather than letting
        // lower layers fail obscurely (prevention beats exception translation).
        if (cost == null || n <= 0) {
            throw new IllegalArgumentException("Matrix must be non-null and of positive size");
        }
        if (cost.size() < n) {
            throw new IllegalArgumentException("Matrix has fewer than " + n + " rows");
        }
        for (int i = 0; i < n; i++) {
            List<Integer> row = cost.get(i);
            if (row == null || row.size() < n) {
                throw new IllegalArgumentException("Row " + i + " has fewer than " + n + " columns");
            }
        }

        // dp[i][j] = maximum sum of any path from (0,0) to (i,j)
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                long best = Long.MIN_VALUE;

                if (i == 0 && j == 0) {
                    best = 0L;
                } else {
                    if (i > 0) {
                        best = Math.max(best, dp[i - 1][j]);
                    }
                    if (j > 0) {
                        best = Math.max(best, dp[i][j - 1]);
                    }
                }

                Integer value = cost.get(i).get(j);
                if (value == null) {
                    throw new IllegalArgumentException("Null entry at (" + i + ", " + j + ")");
                }
                dp[i][j] = best + value.longValue();
            }
        }

        // Every path from (0,0) to (n-1,n-1) visits exactly 2n-1 cells,
        // so the denominator is the same for all paths.
        int steps = 2 * n - 1;
        double average = (double) dp[n - 1][n - 1] / steps;

        return average;
    }
}

