public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
    /**
     * Find the path with maximum average from top-left to bottom-right
     * moving only right or down.
     *
     * @param cost the n*n matrix of costs
     * @param n    the dimension of the square matrix
     * @return the maximum average over all existing paths
     * @throws IllegalArgumentException if n is less than 1
     */
    if (n < 1) {
        throw new IllegalArgumentException("Matrix size must be at least 1, got " + n);
    }

    int[][] dp = new int[n][n];
    dp[0][0] = cost.get(0).get(0);

    // Fill first column
    for (int i = 1; i < n; i++) {
        dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
    }

    // Fill first row
    for (int j = 1; j < n; j++) {
        dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
    }

    // Fill rest of the table
    for (int i = 1; i < n; i++) {
        for (int j = 1; j < n; j++) {
            dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
        }
    }

    // Every path has exactly (2n-1) cells
    int pathLength = 2 * n - 1;
    return dp[n - 1][n - 1] / (double) pathLength;
}

