import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


/**
 * Utility class that computes the maximum-average path through a square matrix.
 *
 * <p><b>Exception policy for this class:</b> all methods in this class throw a
 * {@link NullPointerException} if a {@code null} object reference is passed in
 * any parameter, and an {@link IllegalArgumentException} if a numeric parameter
 * does not satisfy the preconditions stated in the individual method
 * documentation. These unchecked exceptions are declared here once so that they
 * need not be repeated in the {@code throws} clause of every method (unchecked
 * exceptions are never declared there).</p>
 */
class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     *
     * <p>A path starts at cell {@code [0][0]}, ends at cell {@code [n-1][n-1]}
     * and may move only one cell at a time to the right or downward. Every such
     * path contains exactly {@code 2n - 1} cells, so the average of a path is its
     * sum divided by {@code 2n - 1}; maximizing the average therefore reduces to
     * maximizing the sum, which is solved by dynamic programming.</p>
     *
     * @param cost the {@code n} x {@code n} matrix of path costs; must contain at
     *             least {@code n} rows, each row at least {@code n} non-null
     *             {@link Integer} entries
     * @param n    the side length of the square submatrix to consider; must be
     *             positive and no larger than the dimensions of {@code cost}
     * @return the maximum path average, as a {@link Double}; {@code 0.0} is never
     *         returned for a valid positive-sized matrix because all cells are
     *         visited at least once
     * @throws NullPointerException     if {@code cost} is {@code null}, if any row
     *                                  of {@code cost} is {@code null}, or if any
     *                                  inspected element is {@code null} (see the
     *                                  class documentation)
     * @throws IllegalArgumentException if {@code n <= 0}, or if {@code cost} does
     *                                  not hold an {@code n} x {@code n} block of
     *                                  values (see the class documentation)
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // --- Validate arguments and document the resulting unchecked exceptions ---
        if (cost == null) {
            throw new NullPointerException("The cost matrix must not be null.");
        }
        if (n <= 0) {
            throw new IllegalArgumentException(
                    "The matrix size n must be positive, but was " + n + ".");
        }
        if (cost.size() < n) {
            throw new IllegalArgumentException(
                    "The cost matrix has only " + cost.size()
                            + " rows, but n = " + n + " rows are required.");
        }

        // --- DP table: dp[i][j] = best sum of a path from (0,0) to (i,j) ---
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            List<Integer> row = cost.get(i);
            if (row == null) {
                throw new NullPointerException(
                        "Row " + i + " of the cost matrix must not be null.");
            }
            if (row.size() < n) {
                throw new IllegalArgumentException(
                        "Row " + i + " has only " + row.size()
                                + " columns, but n = " + n + " columns are required.");
            }

            for (int j = 0; j < n; j++) {
                Integer value = row.get(j);
                if (value == null) {
                    throw new NullPointerException(
                            "Element [" + i + "][" + j + "] must not be null.");
                }

                long bestFromAbove = (i > 0) ? dp[i - 1][j] : Long.MIN_VALUE;
                long bestFromLeft  = (j > 0) ? dp[i][j - 1] : Long.MIN_VALUE;

                long bestPredecessor;
                if (i == 0 && j == 0) {
                    bestPredecessor = 0L;              // starting cell has no predecessor
                } else if (i == 0) {
                    bestPredecessor = bestFromLeft;    // first row: only from the left
                } else if (j == 0) {
                    bestPredecessor = bestFromAbove;   // first column: only from above
                } else {
                    bestPredecessor = Math.max(bestFromAbove, bestFromLeft);
                }

                dp[i][j] = bestPredecessor + value;
            }
        }

        // Every path visits exactly (2n - 1) cells, so the average is sum / (2n - 1).
        long pathLength = 2L * n - 1L;
        return dp[n - 1][n - 1] / (double) pathLength;
    }

    /** Simple self-check against the documented examples. */
    public static void main(String[] args) {
        System.out.println(maxaverageofpath(
                Arrays.asList(Arrays.asList(1, 2, 3),
                              Arrays.asList(6, 5, 4),
                              Arrays.asList(7, 3, 9)), 3));   // 5.2

        System.out.println(maxaverageofpath(
                Arrays.asList(Arrays.asList(2, 3, 4),
                              Arrays.asList(7, 6, 5),
                              Arrays.asList(8, 4, 10)), 3));  // 6.2

        System.out.println(maxaverageofpath(
                Arrays.asList(Arrays.asList(3, 4, 5),
                              Arrays.asList(8, 7, 6),
                              Arrays.asList(9, 5, 11)), 3));   // 7.2
    }
}

