class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("Matrix size n must be positive, but received: " + n);
        }
        if (cost == null || cost.size() != n) {
            throw new IllegalArgumentException("Matrix row count must equal n=" + n + ", but received: "
                    + (cost == null ? "null" : cost.size()) + " rows");
        }

        // dp[i][j] = maximum sum path from (0,0) to (i,j)
        long[][] dp = new long[n][n];

        dp[0][0] = cost.get(0).get(0);

        // Fill first row (only reachable by moving right)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill first column (only reachable by moving down)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill remaining cells: max from above or left, plus current cell value
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
            }
        }

        // All paths have exactly (2n - 1) elements, so max sum / (2n-1) = max average
        double pathLength = 2.0 * n - 1.0;
        return dp[n - 1][n - 1] / pathLength;
    }
}

