class CountVowels {
    /** The set of characters treated as vowels. */
    private static final String VOWELS = "aeiouAEIOU";

    /** Returns true iff {@code c} is one of a, e, i, o, u (either case). */
    private static boolean isVowel(char c) {
        return VOWELS.indexOf(c) >= 0;
    }

    /**
     * * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        // Failure-capture: the detail message records the parameter name and value,
        // so the stack trace alone identifies the bad argument (Item 75).
        if (testStr == null) {
            throw new NullPointerException(
                    "countVowels(String testStr): testStr must not be null, got null");
        }

        int count = 0;
        final int n = testStr.length();

        for (int i = 0; i < n; i++) {
            char c = testStr.charAt(i);

            // Vowels themselves are never counted; only non-vowels that touch a vowel.
            if (isVowel(c)) {
                continue;
            }

            boolean hasVowelNeighbor =
                    (i > 0 && isVowel(testStr.charAt(i - 1)))          // left neighbour
                 || (i < n - 1 && isVowel(testStr.charAt(i + 1)));     // right neighbour

            if (hasVowelNeighbor) {
                count++;
            }
        }

        return count;
    }

    // Quick self-check of the documented examples.
