class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // --- Failure atomicity (Item 76): validate everything BEFORE computing ---
        if (cost == null) {
            throw new IllegalArgumentException("cost matrix must not be null");
        }
        if (n <= 0) {
            throw new IllegalArgumentException("matrix size must be positive, got " + n);
        }
        if (cost.size() < n) {
            throw new IllegalArgumentException(
                "matrix has " + cost.size() + " rows but n = " + n);
        }
        for (int i = 0; i < n; i++) {
            List<Integer> row = cost.get(i);
            if (row == null || row.size() < n) {
                throw new IllegalArgumentException(
                    "row " + i + " does not contain " + n + " columns");
            }
            for (int j = 0; j < n; j++) {
                if (row.get(j) == null) {
                    throw new IllegalArgumentException(
                        "cell (" + i + ", " + j + ") is null");
                }
            }
        }

        // --- Computation: maximize sum, then divide by the fixed path length ---
        long[][] dp = new long[n][n];
        dp[0][0] = cost.get(0).get(0);

        // First row: can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }
        // First column: can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }
        // Interior cells: best of "from above" vs "from left"
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                long fromTop = dp[i - 1][j];
                long fromLeft = dp[i][j - 1];
                dp[i][j] = cost.get(i).get(j) + Math.max(fromTop, fromLeft);
            }
        }

        // Every valid path contains exactly (2n - 1) cells.
        int pathLength = 2 * n - 1;
        return dp[n - 1][n - 1] / (double) pathLength;
    }
}

