    // Use DP to find the maximum sum path from top-left to bottom-right
    // Every valid path has exactly (2n-1) elements
    int[][] dp = new int[n][n];

    // Base case: first cell
    dp[0][0] = cost.get(0).get(0);

    // Fill first row (can only come from left)
    for (int j = 1; j < n; j++) {
        dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
    }

    // Fill first column (can only come from above)
    for (int i = 1; i < n; i++) {
        dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
    }

    // Fill rest of the table
    for (int i = 1; i < n; i++) {
        for (int j = 1; j < n; j++) {
            dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
        }
    }

    // Maximum sum path ends at bottom-right corner
    int maxSum = dp[n - 1][n - 1];

    // Number of cells in any such path
    int numCells = 2 * n - 1;

    return (double) maxSum / numCells;
}

