class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        if (n <= 0 || cost == null || cost.isEmpty()) {
            return 0.0;
        }

        // Number of cells on any top-left -> bottom-right path (moves: down / right).
        int cellsOnPath = 2 * n - 1;

        // dp[i][j] = maximum sum of a path ending at cell (i, j).
        int[][] dp = new int[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int fromTop  = (i > 0) ? dp[i - 1][j] : Integer.MIN_VALUE / 2;
                int fromLeft = (j > 0) ? dp[i][j - 1] : Integer.MIN_VALUE / 2;

                if (i == 0 && j == 0) {
                    dp[i][j] = cost.get(i).get(j);
                } else if (i == 0) {
                    dp[i][j] = cost.get(i).get(j) + fromLeft;
                } else if (j == 0) {
                    dp[i][j] = cost.get(i).get(j) + fromTop;
                } else {
                    dp[i][j] = cost.get(i).get(j) + Math.max(fromTop, fromLeft);
                }
            }
        }

        double maxSum = dp[n - 1][n - 1];
        return maxSum / cellsOnPath;
    }
}

