class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Base cases of the Newman-Shanks-Williams / Pell companion sequence:
        //   a(1) = 1, a(2) = 3, a(n) = 2*a(n-1) + a(n-2)
        if (n <= 0) {
            return 0;          // no nth element defined
        }
        if (n == 1) {
            return 1;
        }
        if (n == 2) {
            return 3;
        }

        // Iterative (O(n) time, O(1) space) evaluation of the recurrence.
        int prevPrev = 1;      // a(n-2)
        int prev     = 3;      // a(n-1)
        for (int i = 3; i <= n; i++) {
            int current = 2 * prev + prevPrev;   // a(i) = 2*a(i-1) + a(i-2)
            prevPrev = prev;
            prev     = current;
        }
        return prev;
    }

    // Quick self-check of the documented examples
    public static void main(String[] args) {
        System.out.println(newmanPrime(3));   // 7
        System.out.println(newmanPrime(4));   // 17
        System.out.println(newmanPrime(5));   // 41
        System.out.println(newmanPrime(6));   // 99
        System.out.println(newmanPrime(7));   // 239
    }
}

