class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        if (n == 0 || n == 1) return 1;
        int sPrev = 1;
        int sCurr = 1;
        for (int i = 2; i <= n; i++) {
            int sNext = 2 * sCurr + sPrev;
            sPrev = sCurr;
            sCurr = sNext;
        }
        return sCurr;
    }

    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

