class CountVowels {
    /** The set of vowels (both cases) used by the counter. */
    private static final String VOWELS = "aeiouAEIOU";

    /**
     * Write a function to count those characters which have vowels as their
     * neighbors in the given string.
     *
     * A character is counted when
     *   1) it is NOT itself a vowel, and
     *   2) at least one of its immediate neighbours (left or right) is a vowel.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     *
     * This method performs no shared-state updates, so it needs no
     * synchronization: it is safe to invoke concurrently from any thread.
     */
    public static int countVowels(String testStr) {
        // Degenerate inputs: nothing can have a vowel neighbour.
        if (testStr == null || testStr.length() < 2) {
            return 0;
        }

        final int len = testStr.length();
        int count = 0;

        for (int i = 0; i < len; i++) {
            char current = testStr.charAt(i);

            // Rule 1: vowels themselves are never counted.
            if (isVowel(current)) {
                continue;
            }

            // Rule 2: at least one neighbour must be a vowel.
            boolean leftIsVowel  = (i > 0)          && isVowel(testStr.charAt(i - 1));
            boolean rightIsVowel = (i < len - 1)    && isVowel(testStr.charAt(i + 1));

            if (leftIsVowel || rightIsVowel) {
                count++;
            }
        }

        return count;
    }

    /** Helper: true iff {@code c} is one of a, e, i, o, u (upper or lower case). */
    private static boolean isVowel(char c) {
        return VOWELS.indexOf(c) >= 0;
    }

    // Quick self-check against the documented examples.
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));            // 7
        System.out.println(countVowels("partofthejourneyistheend"));   // 12
        System.out.println(countVowels("amazonprime"));               // 5
    }
}

