            char current = testStr.charAt(i);

            // A vowel itself is never counted; we only count characters *adjacent*
            // to vowels (consonants / other symbols).
            if (isVowel(current)) {
                continue;
            }

            // Check the left neighbor (exists only when i > 0) ...
            boolean leftNeighborIsVowel = (i > 0) && isVowel(testStr.charAt(i - 1));
            // ... and the right neighbor (exists only when i < length - 1).
            boolean rightNeighborIsVowel = (i < length - 1) && isVowel(testStr.charAt(i + 1));

            if (leftNeighborIsVowel || rightNeighborIsVowel) {
                count++;
            }
        }

        return count;
    }

