class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Guard against empty / mismatched input
        if (cost == null || cost.isEmpty() || n <= 0) {
            return 0.0;
        }
        int size = Math.min(n, cost.size());
        if (size == 0) {
            return 0.0;
        }

        // dp[i][j] = maximum sum of a path from (0,0) to (i,j) moving only down/right
        int[][] dp = new int[size][size];

        // First column: can only come from above
        dp[0][0] = cost.get(0).get(0);
        for (int i = 1; i < size; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // First row: can only come from the left
        for (int j = 1; j < size; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the rest: best of (from above, from left) plus current cell
        for (int i = 1; i < size; i++) {
            List<Integer> row = cost.get(i);
            for (int j = 1; j < size; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + row.get(j);
            }
        }

        // Every valid path visits exactly (2*size - 1) cells,
        // so maximizing the sum also maximizes the average.
        int steps = 2 * size - 1;
        return (double) dp[size - 1][size - 1] / steps;
    }

    // Quick self-test
    public static void main(String[] args) {
        System.out.println(maxaverageofpath(Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)), 3));   // 5.2

        System.out.println(maxaverageofpath(Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)), 3));  // 6.2

        System.out.println(maxaverageofpath(Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)), 3));  // 7.2
    }
}

