        // \Bz\B : 'z' preceded by a word character AND followed by a word character,
        // i.e. 'z' occurs strictly inside a word (never at its start or end).
        Pattern pattern = Pattern.compile("\\Bz\\B");
        Matcher matcher = pattern.matcher(text);
        if (matcher.find()) {
            return "Found a match!";
        }
        return "Not matched!";
    }
}

