class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        if (cost == null || cost.isEmpty() || n <= 0) {
            return 0.0;
        }

        // Every path from (0,0) to (n-1,n-1) moving only right/down has
        // exactly (2n - 1) cells, so the average is maximized by maximizing
        // the total sum of the path.
        int[][] dp = new int[n][n];
        final int UNREACHABLE = Integer.MIN_VALUE;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i == 0 && j == 0) {
                    dp[i][j] = cost.get(0).get(0);          // starting cell
                    continue;
                }
                int fromTop  = (i > 0) ? dp[i - 1][j] : UNREACHABLE;
                int fromLeft = (j > 0) ? dp[i][j - 1] : UNREACHABLE;
                int best = (fromTop >= fromLeft) ? fromTop : fromLeft;
                dp[i][j] = best + cost.get(i).get(j);
            }
        }

        int maxSum = dp[n - 1][n - 1];
        double length = (double) (2 * n - 1);
        return maxSum / length;
    }
}

