class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Base cases of the NSW recurrence: S(0) = 1, S(1) = 1
        if (n <= 1) {
            return 1;
        }

        // Bottom-up evaluation of S(n) = 2*S(n-1) + S(n-2).
        // Only the two most recent terms are needed -> O(n) time, O(1) space,
        // no recursion depth issues and no shared mutable state.
        int prev2 = 1; // S(i-2)
        int prev1 = 1; // S(i-1)
        int current = 1;

        for (int i = 2; i <= n; i++) {
            current = 2 * prev1 + prev2;
            prev2 = prev1;
            prev1 = current;
        }

        return current;
    }
}

