class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     *
     * <p><b>Thread safety:</b> unconditionally thread-safe. This method is
     * stateless: it performs no mutation of shared/static state and touches only
     * its parameters, so concurrent invocations from multiple threads require no
     * external synchronization (provided the caller does not concurrently mutate
     * {@code cost}).</p>
     *
     * @param cost the n x n matrix of costs (must contain at least n rows/columns)
     * @param n    the dimension of the square matrix
     * @return the maximum average over all top-left to bottom-right paths
     *         (moving only right or down); {@code 0.0} if the input is invalid
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        if (cost == null || n <= 0 || cost.size() < n) {
            return 0.0;
        }

        // dp[i][j] = maximum sum of any path from (0,0) to (i,j)
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            List<Integer> row = cost.get(i);
            if (row == null || row.size() < n) {
                return 0.0;
            }
            for (int j = 0; j < n; j++) {
                long best;
                if (i == 0 && j == 0) {
                    best = 0L;                       // start cell contributes itself below
                } else if (i == 0) {
                    best = dp[i][j - 1];             // can only come from the left
                } else if (j == 0) {
                    best = dp[i - 1][j];             // can only come from above
                } else {
                    best = Math.max(dp[i - 1][j], dp[i][j - 1]);
                }
                dp[i][j] = best + row.get(j);
            }
        }

        // Every path visits exactly (2n - 1) cells, so maximizing the sum
        // maximizes the average.
        int steps = 2 * n - 1;
        double total = (double) dp[n - 1][n - 1];
        return total / steps;
    }

    public static void main(String[] args) {
        List<List<Integer>> m1 = Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9));
        List<List<Integer>> m2 = Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10));
        List<List<Integer>> m3 = Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11));

        System.out.println(maxaverageofpath(m1, 3)); // 5.2
        System.out.println(maxaverageofpath(m2, 3)); // 6.2
        System.out.println(maxaverageofpath(m3, 3)); // 7.2
    }
}

