class SeriesSum {
    /**
     * * Write a function to calculate the sum of series 1²+2²+3²+….+n².
     *
     * > seriesSum(6)
     * 91
     * > seriesSum(7)
     * 140
     * > seriesSum(12)
     * 650
     *
     * <p><b>Thread safety:</b> Unconditionally thread-safe. This method is
     * {@code static} and completely stateless — it reads only its parameter and
     * writes only its local accumulator — so no external synchronization is
     * required and multiple threads may invoke it concurrently.</p>
     *
     * <p><b>Range:</b> for {@code number <= 0} the sum is empty and {@code 0}
     * is returned. For large {@code number} the result may overflow {@code int}
     * (the series reaches Integer.MAX_VALUE at n = 46340).</p>
     *
     * @param number upper bound {@code n} of the series (inclusive)
     * @return 1² + 2² + ... + n², computed as the accumulated sum of squares
     */
    public static int seriesSum(int number) {
        // Accumulate 1² + 2² + ... + n² iteratively.
        // Equivalent closed form: number * (number + 1) * (2 * number + 1) / 6,
        // but the loop avoids the larger intermediate product of that formula.
        int sum = 0;
        for (int i = 1; i <= number; i++) {
            sum += i * i;
        }
        return sum;
    }

