class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        if (n == 0) return 0.0;

        int[][] dp = new int[n][n];
        dp[0][0] = cost.get(0).get(0);

        // Fill first column (only reachable from above)
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Fill first row (only reachable from left)
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill remaining cells: max from top or left
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
            }
        }

        // Total path length is always 2n-1
        int pathLength = 2 * n - 1;
        return (double) dp[n - 1][n - 1] / pathLength;
    }
}

class CountVowels {

    // Lazy-initialized vowel lookup table using holder class idiom (per ITEM 83 for static fields)
    private static class VowelHolder {
        static final boolean[] VOWEL_TABLE = new boolean[128];
        static {
            VOWEL_TABLE['a'] = VOWEL_TABLE['A'] = true;
            VOWEL_TABLE['e'] = VOWEL_TABLE['E'] = true;
            VOWEL_TABLE['i'] = VOWEL_TABLE['I'] = true;
            VOWEL_TABLE['o'] = VOWEL_TABLE['O'] = true;
            VOWEL_TABLE['u'] = VOWEL_TABLE['U'] = true;
        }
    }

    private static boolean isVowel(char c) {
        return c < 128 && VowelHolder.VOWEL_TABLE[c];
    }

    public static int countVowels(String testStr) {
        if (testStr == null || testStr.length() <= 1) {
            return 0;
        }
        int count = 0;
        int len = testStr.length();
        for (int i = 0; i < len; i++) {
            char c = testStr.charAt(i);
            if (isVowel(c)) {
                continue; // skip vowels — only count non-vowel characters
            }
            boolean hasVowelNeighbor = false;
            if (i > 0 && isVowel(testStr.charAt(i - 1))) {
                hasVowelNeighbor = true;
            }
            if (i < len - 1 && isVowel(testStr.charAt(i + 1))) {
                hasVowelNeighbor = true;
            }
            if (hasVowelNeighbor) {
                count++;
            }
        }
        return count;
    }
}

