public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
    // dp[i][j] = max sum path from (0,0) to (i,j)
    int[][] dp = new int[n][n];

    dp[0][0] = cost.get(0).get(0);

    // Fill first column
    for (int i = 1; i < n; i++) {
        dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
    }

    // Fill first row
    for (int j = 1; j < n; j++) {
        dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
    }

    // Fill rest of dp table
    for (int i = 1; i < n; i++) {
        for (int j = 1; j < n; j++) {
            dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
        }
    }

    // All paths have exactly (2*n - 1) elements
    double totalLength = 2 * n - 1;
    return dp[n - 1][n - 1] / totalLength;
}

