class TextMatchWordzMiddle {
    /**
     * * Write a function that matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // Guard against null / empty input (also keeps us from feeding
        // unexpected data into the pattern engine).
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        // \b   -> start of a word
        // \w   -> at least ONE character BEFORE the 'z'
        // \w*  -> optional extra characters before the 'z'
        // z    -> the letter we are looking for
        // \w*  -> optional characters right after the 'z'
        // \w   -> at least ONE character AFTER the 'z'
        // \b   -> end of a word
        //
        // Because of the mandatory \w on both sides, 'z' can never sit at
        // the very beginning or the very end of the word.
        Pattern pattern = Pattern.compile("\\b\\w\\w*z\\w\\w*\\b");
        Matcher matcher = pattern.matcher(text);

        if (matcher.find()) {
            return "Found a match!";
        }
        return "Not matched!";
    }

    // Quick self-test
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));  // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));      // Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));     // Not matched!
        System.out.println(textMatchWordzMiddle("zabc"));          // Not matched! (z at start)
        System.out.println(textMatchWordzMiddle("abcz"));          // Not matched! (z at end)
        System.out.println(textMatchWordzMiddle("a_z b"));         // Not matched! (_ is not \w... actually _ IS \w)
    }
}

public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
    // DP table: dp[i][j] = max sum path from (0,0) to (i,j)
    int[][] dp = new int[n][n];
    dp[0][0] = cost.get(0).get(0);

    // Fill first column (only reachable from above)
    for (int i = 1; i < n; i++) {
        dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
    }

    // Fill first row (only reachable from left)
    for (int j = 1; j < n; j++) {
        dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
    }

    // Fill rest of the table
    for (int i = 1; i < n; i++) {
        for (int j = 1; j < n; j++) {
            dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
        }
    }

    // Every path from (0,0) to (n-1,n-1) has exactly (2n-1) elements
    int pathLength = 2 * n - 1;
    return (double) dp[n - 1][n - 1] / pathLength;
}

