import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;
import java.util.regex.*;          // Pattern / Matcher


class TextMatchWordzMiddle {
    /**
     * * Write a function that matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null) {
            return "Not matched!";
        }
        // 'z' must sit INSIDE a word: a word character immediately before and after it.
        //   (?<=\w)  -> look-behind: preceding character is a word character  (not start of word)
        //   (?=\w)   -> look-ahead : following character is a word character  (not end of word)
        Pattern pattern = Pattern.compile("(?<=\\w)z(?=\\w)");
        Matcher matcher = pattern.matcher(text);

        return matcher.find() ? "Found a match!" : "Not matched!";
    }

    // Demonstration / self-test
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));  // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));      // Found a match!
