class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Base cases of the Newman–Shanks–Williams recurrence:
        // a(0) = 1, a(1) = 1
        if (n <= 0) {
            return 1;
        }

        // Iterate a(i) = 2 * a(i-1) + a(i-2)
        long prev = 1L; // a(i-2)
        long curr = 1L; // a(i-1)

        for (int i = 2; i <= n; i++) {
            long next = 2L * curr + prev;
            prev = curr;
            curr = next;
        }

        return (int) curr;
    }

    // Quick self-check against the documented examples
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
    }
}

