     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null) {
            return "Not matched!";
        }
        // (?<=\w)  -> a word character must precede the 'z'  (not at the start of the word)
        // [zZ]     -> the letter 'z' itself
        // (?=\w)   -> a word character must follow the 'z'  (not at the end of the word)
        java.util.regex.Pattern p = java.util.regex.Pattern.compile("(?<=\\w)[zZ](?=\\w)");
        java.util.regex.Matcher m = p.matcher(text);
        if (m.find()) {
            return "Found a match!";
        }
        return "Not matched!";
    }
}

