class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Degenerate inputs
        if (cost == null || cost.isEmpty() || n <= 0) {
            return 0.0;
        }

        // dp[i][j] = maximum sum of any path from (0,0) to (i,j) moving only right or down
        int[][] dp = new int[n][n];

        for (int i = 0; i < n; i++) {
            List<Integer> row = cost.get(i);
            for (int j = 0; j < n; j++) {
                int cur = (row != null && j < row.size()) ? row.get(j) : 0;

                if (i == 0 && j == 0) {
                    dp[0][0] = cur;
                    continue;
                }

                // Value coming from the cell above (if any)
                int fromTop = (i > 0) ? dp[i - 1][j] : Integer.MIN_VALUE / 2;
                // Value coming from the cell to the left (if any)
                int fromLeft = (j > 0) ? dp[i][j - 1] : Integer.MIN_VALUE / 2;

                dp[i][j] = Math.max(fromTop, fromLeft) + cur;
            }
        }

        // Every top-left -> bottom-right path in an n x n grid has exactly (2n - 1) cells,
        // so maximizing the sum maximizes the average.
        int pathLength = 2 * n - 1;
        return dp[n - 1][n - 1] / (double) pathLength;
    }

    // Quick self-check
    public static void main(String[] args) {
        System.out.println(maxaverageofpath(Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)), 3));   // 5.2

        System.out.println(maxaverageofpath(Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)), 3));  // 6.2

        System.out.println(maxaverageofpath(Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)), 3));  // 7.2
    }
}

