class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Degenerate cases: nothing to traverse.
        if (cost == null || cost.isEmpty() || n <= 0) {
            return 0.0;
        }

        // dp[i][j] = maximum sum of a path from (0,0) to (i,j)
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                long current = (long) cost.get(i).get(j);

                long best = Long.MIN_VALUE;
                if (i > 0) {
                    best = Math.max(best, dp[i - 1][j]);   // came from above
                }
                if (j > 0) {
                    best = Math.max(best, dp[i][j - 1]);   // came from the left
                }

                dp[i][j] = (best == Long.MIN_VALUE) ? current : current + best;
            }
        }

        // Every valid path visits exactly (2n - 1) cells,
        // so maximizing the average == maximizing the sum.
        int cells = 2 * n - 1;
        double maxSum = (double) dp[n - 1][n - 1];
        double maxAverage = maxSum / cells;

        // Round to one decimal place so results print like 5.2, 6.2, 7.2
        maxAverage = Math.round(maxAverage * 10.0) / 10.0;

        return maxAverage;
    }
}

