class RemoveOdd {
    /**
     * * Write a function to remove odd characters in a string.
     *
     * > removeOdd("python")
     * "yhn"
     * > removeOdd("program")
     * "rga"
     * > removeOdd("language")
     * "agae"
     */
    public static String removeOdd(String str1) {
        // Guard against null / empty input
        if (str1 == null || str1.isEmpty()) {
            return "";
        }

        StringBuilder sb = new StringBuilder();

        // Keep only characters located at odd indices (1, 3, 5, ...);
        // equivalently, discard the characters at even indices (0, 2, 4, ...).
        for (int i = 1; i < str1.length(); i += 2) {
            sb.append(str1.charAt(i));
        }

        return sb.toString();
    }

    // Quick self-test of the documented examples
    public static void main(String[] args) {
        System.out.println(removeOdd("python"));   // yhn
        System.out.println(removeOdd("program"));  // rga
        System.out.println(removeOdd("language")); // agae
        System.out.println(removeOdd("a"));        // "" (single char -> nothing left)
        System.out.println(removeOdd(""));         // ""
    }
}

