public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
    // DP table: dp[i][j] = maximum sum to reach cell (i, j)
    double[][] dp = new double[n][n];

    // Initialize starting cell
    dp[0][0] = cost.get(0).get(0);

    // Fill first row (can only come from left)
    for (int j = 1; j < n; j++) {
        dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
    }

    // Fill first column (can only come from above)
    for (int i = 1; i < n; i++) {
        dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
    }

    // Fill rest of the table
    for (int i = 1; i < n; i++) {
        for (int j = 1; j < n; j++) {
            dp[i][j] = cost.get(i).get(j) + Math.max(dp[i - 1][j], dp[i][j - 1]);
        }
    }

    // Total path length is always 2n - 1
    int pathLength = 2 * n - 1;
    return dp[n - 1][n - 1] / pathLength;
}

public static int countVowels(String testStr) {
    if (testStr == null || testStr.isEmpty()) return 0;

    String vowels = "aeiouy";
    int count = 0;
    char[] chars = testStr.toCharArray();

    for (int i = 0; i < chars.length; i++) {
        char c = Character.toLowerCase(chars[i]);
        if (vowels.indexOf(c) != -1) continue; // skip vowels themselves

        // Check left neighbor
        if (i > 0 && vowels.indexOf(Character.toLowerCase(chars[i - 1])) != -1) {
            count++;
            continue;
        }
        // Check right neighbor
        if (i < chars.length - 1 && vowels.indexOf(Character.toLowerCase(chars[i + 1])) != -1) {
            count++;
        }
    }
    return count;
}

