            alpha++;
        } else if (c >= '0' && c <= '9') {
            digit++;
        } else {
            special++;
        }
    }
    List<Integer> result = new ArrayList<>();
    result.add(alpha);
    result.add(digit);
    result.add(special);
    return result;
}
}

