class TextMatchWordzMiddle {
    /**
     * * Write a function that matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null) {
            return "Not matched!";
        }
        // 'z' must have a word character both before and after it,
        // which guarantees it lies strictly inside a word.
        Pattern pattern = Pattern.compile("(?<=\\w)z(?=\\w)");
        Matcher matcher = pattern.matcher(text);
        return matcher.find() ? "Found a match!" : "Not matched!";
    }

    // Quick self-test mirroring the doc examples
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc.")); // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));     // Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));   // Not matched!

        // extra sanity checks
        System.out.println(textMatchWordzMiddle("az"));          // Not matched!
        System.out.println(textMatchWordzMiddle("za"));          // Not matched!
        System.out.println(textMatchWordzMiddle("azb"));         // Found a match!
        System.out.println(textMatchWordzMiddle("a z b"));       // Not matched!
        System.out.println(textMatchWordzMiddle("foo bar baz")); // Not matched!
    }
}

public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
    double[][] dp = new double[n][n];
    dp[0][0] = cost.get(0).get(0);

    for (int j = 1; j < n; j++) {
        dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
    }

    for (int i = 1; i < n; i++) {
        dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
    }

    for (int i = 1; i < n; i++) {
        for (int j = 1; j < n; j++) {
            dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cost.get(i).get(j);
        }
    }

    return dp[n - 1][n - 1] / (2 * n - 1);
}

