class CountVowels {
    /**
     * * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */
    public static int countVowels(String testStr) {
        // Guard against null / too-short inputs: nothing can have a neighbor.
        if (testStr == null || testStr.length() < 2) {
            return 0;
        }

        int n = testStr.length();
        int count = 0;

        for (int i = 0; i < n; i++) {
            char current = testStr.charAt(i);

            // Only consonants (non-vowels) are candidates for the count.
            if (isVowel(current)) {
                continue;
            }

            // Look at the left neighbour (if any).
            boolean leftIsVowel = (i > 0) && isVowel(testStr.charAt(i - 1));

            // Look at the right neighbour (if any).
            boolean rightIsVowel = (i < n - 1) && isVowel(testStr.charAt(i + 1));

            if (leftIsVowel || rightIsVowel) {
                count++;
            }
        }

        return count;
    }

    /** Returns true if the given character is one of a, e, i, o, u (case-insensitive). */
    private static boolean isVowel(char c) {
        switch (Character.toLowerCase(c)) {
            case 'a':
            case 'e':
            case 'i':
            case 'o':
            case 'u':
                return true;
            default:
                return false;
        }
    }

    // Quick self-check against the documented examples.
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));          // 7
        System.out.println(countVowels("partofthejourneyistheend")); // 12
        System.out.println(countVowels("amazonprime"));             // 5
    }
}

