class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        if (n <= 0 || cost == null || cost.isEmpty()) {
            return 0.0;
        }

        // Every top-left -> bottom-right path (right/down moves) has exactly 2n-1 cells,
        // so maximizing the average is equivalent to maximizing the total sum.
        long[][] dp = new long[n][n];

        // Base cell
        dp[0][0] = cost.get(0).get(0);

        // First column: can only come from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // First row: can only come from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Fill the rest of the table
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                long fromTop = dp[i - 1][j];
                long fromLeft = dp[i][j - 1];
                dp[i][j] = cost.get(i).get(j) + Math.max(fromTop, fromLeft);
            }
        }

        // Number of cells visited on any such path
        int pathLength = 2 * n - 1;

        double maxSum = (double) dp[n - 1][n - 1];
        return maxSum / pathLength;
    }

    public static void main(String[] args) {
        System.out.println(maxaverageofpath(Arrays.asList(
                Arrays.asList(1, 2, 3),
                Arrays.asList(6, 5, 4),
                Arrays.asList(7, 3, 9)), 3));   // 5.2

        System.out.println(maxaverageofpath(Arrays.asList(
                Arrays.asList(2, 3, 4),
                Arrays.asList(7, 6, 5),
                Arrays.asList(8, 4, 10)), 3));  // 6.2

        System.out.println(maxaverageofpath(Arrays.asList(
                Arrays.asList(3, 4, 5),
                Arrays.asList(8, 7, 6),
                Arrays.asList(9, 5, 11)), 3));  // 7.2
    }
}

