class TextMatchWordzMiddle {
    /**
     * * Write a function that matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null || text.isEmpty())
            return "Not matched!";

        final int n = text.length();
        int i = 0;

        while (i < n) {
            // skip everything that is not part of a word
            if (!isWordChar(text.charAt(i))) {
                i++;
                continue;
            }

            // mark the beginning of a word and consume the whole word
            int start = i;
            while (i < n && isWordChar(text.charAt(i)))
                i++;
            int end = i;                 // exclusive

            // look for 'z' strictly between the first and the last char of the word
            for (int j = start + 1; j < end - 1; j++) {
                if (text.charAt(j) == 'z')
                    return "Found a match!";
            }
        }

        return "Not matched!";
    }

    /** A word character: letter, digit or underscore (same as \w in a regex). */
    private static boolean isWordChar(char c) {
        return Character.isLetterOrDigit(c) || c == '_';
    }
}

