            // Look at the left neighbor (if it exists)
            boolean leftIsVowel = (i > 0) && isVowel(str.charAt(i - 1));

            // Look at the right neighbor (if it exists)
            boolean rightIsVowel = (i < n - 1) && isVowel(str.charAt(i + 1));

            if (leftIsVowel || rightIsVowel) {
                count++;
            }
        }

        return count;
    }

    /** Returns true if the given character is a lowercase vowel (a, e, i, o, u). */
    private static boolean isVowel(char ch) {
        return ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u';
    }

