class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // --- Defensive validation of the arguments (do not trust the caller) ---
        if (cost == null || n <= 0) {
            return null;
        }
        if (cost.size() < n) {
            return null;
        }

        // Work on a private defensive copy of the matrix: never expose or mutate
        // the caller's data structures (same principle as Item 88's readObject).
        int[][] grid = new int[n][n];
        for (int i = 0; i < n; i++) {
            List<Integer> row = cost.get(i);
            if (row == null || row.size() < n) {
                return null;               // malformed input
            }
            for (int j = 0; j < n; j++) {
                Integer v = row.get(j);
                if (v == null) {
                    return null;
                }
                grid[i][j] = v.intValue();
            }
        }

        // dp[i][j] = maximum sum of any right/down path from (0,0) to (i,j)
        int[][] dp = new int[n][n];
        dp[0][0] = grid[0][0];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i == 0 && j == 0) {
                    continue;
                }
                int best = Integer.MIN_VALUE;
                if (i > 0) {
                    best = Math.max(best, dp[i - 1][j]);   // came from above
                }
                if (j > 0) {
                    best = Math.max(best, dp[i][j - 1]);   // came from the left
                }
                dp[i][j] = best + grid[i][j];
            }
        }

        // Every valid path visits exactly (2n - 1) cells, so the maximum average
        // equals the maximum sum divided by the path length.
        int pathLength = 2 * n - 1;
        return dp[n - 1][n - 1] / (double) pathLength;
    }

    // ---- Small driver used to reproduce the doctest outputs ----
    public static void main(String[] args) {
        System.out.println(maxaverageofpath(
                Arrays.asList(Arrays.asList(1, 2, 3),
                              Arrays.asList(6, 5, 4),
                              Arrays.asList(7, 3, 9)), 3));   // 5.2

        System.out.println(maxaverageofpath(
                Arrays.asList(Arrays.asList(2, 3, 4),
                              Arrays.asList(7, 6, 5),
                              Arrays.asList(8, 4, 10)), 3));  // 6.2

        System.out.println(maxaverageofpath(
                Arrays.asList(Arrays.asList(3, 4, 5),
                              Arrays.asList(8, 7, 6),
                              Arrays.asList(9, 5, 11)), 3));  // 7.2
    }
}

