class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        if (n <= 0 || cost == null || cost.isEmpty()) {
            return 0.0;
        }

        // dp[i][j] = maximum sum of any down/right path from (0,0) to (i,j)
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                long best;
                if (i == 0 && j == 0) {
                    best = 0L;                       // starting cell
                } else {
                    long fromTop  = (i > 0) ? dp[i - 1][j] : Long.MIN_VALUE;
                    long fromLeft = (j > 0) ? dp[i][j - 1] : Long.MIN_VALUE;
                    best = Math.max(fromTop, fromLeft);
                }
                dp[i][j] = best + (long) cost.get(i).get(j);
            }
        }

        // Every legal path visits exactly (2n - 1) cells,
        // so maximizing the sum also maximizes the average.
        long totalSteps = 2L * n - 1L;
        return (double) dp[n - 1][n - 1] / (double) totalSteps;
    }
}

