     * * Write a function to calculate volume of a tetrahedron.
     *
     * > volumeTetrahedron(10)
     * 117.85
     * > volumeTetrahedron(15)
     * 397.75
     * > volumeTetrahedron(20)
     * 942.81
     */
    public static Double volumeTetrahedron(int num) {
        double edge = num;
        double volume = Math.pow(edge, 3) / (6 * Math.sqrt(2));
        BigDecimal bd = new BigDecimal(volume).setScale(2, RoundingMode.HALF_UP);
        return bd.doubleValue();
    }
}

