class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths
     * for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Trivial matrix of size 1x1
        if (n <= 1) {
            return (double) cost.get(0).get(0);
        }

        // dp[i][j] = maximum sum of a path from (0,0) to (i,j) moving only down/right
        int[][] dp = new int[n][n];
        dp[0][0] = cost.get(0).get(0);

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i == 0 && j == 0) {
                    continue; // already initialised
                }
                int best = Integer.MIN_VALUE;
                if (i > 0) {                       // came from above
                    best = Math.max(best, dp[i - 1][j]);
                }
                if (j > 0) {                       // came from the left
                    best = Math.max(best, dp[i][j - 1]);
                }
                dp[i][j] = cost.get(i).get(j) + best;
            }
        }

        // Every valid path contains exactly (2n - 1) cells,
        // so the average = maxSum / (2n - 1)
        double maxSum   = dp[n - 1][n - 1];
        double pathLen  = 2.0 * n - 1.0;

        return maxSum / pathLen;
    }

    // quick self-check
    public static void main(String[] args) {
        List<List<Integer>> a = Arrays.asList(Arrays.asList(1, 2, 3),
                                              Arrays.asList(6, 5, 4),
                                              Arrays.asList(7, 3, 9));
        List<List<Integer>> b = Arrays.asList(Arrays.asList(2, 3, 4),
                                              Arrays.asList(7, 6, 5),
                                              Arrays.asList(8, 4, 10));
        List<List<Integer>> c = Arrays.asList(Arrays.asList(3, 4, 5),
                                              Arrays.asList(8, 7, 6),
                                              Arrays.asList(9, 5, 11));
        System.out.println(maxaverageofpath(a, 3)); // 5.2
        System.out.println(maxaverageofpath(b, 3)); // 6.2
        System.out.println(maxaverageofpath(c, 3)); // 7.2
    }
}

public static int countVowels(String testStr) {
    String vowels = "aeiouAEIOU";
    int count = 0;
    for (int i = 0; i < testStr.length(); i++) {
