public static int newmanPrime(int n) {
        if (n <= 1) return 1;
        int a = 1, b = 1; // S(0), S(1)
        for (int i = 2; i <= n; i++) {
            int c = 2 * b + a;
            a = b;
            b = c;
        }
        return b;
    }
}

