class TextMatchWordzMiddle {
    /**
     * * Write a function that matches a word containing 'z', not at the start or end of the word.
     *
     * > textMatchWordzMiddle("pythonzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("xyzabc.")
     * "Found a match!"
     * > textMatchWordzMiddle("  lang  .")
     * "Not matched!"
     */
    public static String textMatchWordzMiddle(String text) {
        // \b      -> start of a word
        // \w+     -> >=1 word char BEFORE the 'z'  (so 'z' is not first)
        // z       -> the letter we are looking for
        // \w+     -> >=1 word char AFTER  the 'z'  (so 'z' is not last)
        // \b      -> end of the word
        Pattern pattern = Pattern.compile("\\b\\w+z\\w+\\b");
        Matcher matcher = pattern.matcher(text == null ? "" : text);

        if (matcher.find()) {
            return "Found a match!";
        }
        return "Not matched!";
    }

    // quick self-test
    public static void main(String[] args) {
        System.out.println(textMatchWordzMiddle("pythonzabc."));   // Found a match!
        System.out.println(textMatchWordzMiddle("xyzabc."));       // Found a match!
        System.out.println(textMatchWordzMiddle("  lang  ."));     // Not matched!
        System.out.println(textMatchWordzMiddle("za"));           // Not matched!
        System.out.println(textMatchWordzMiddle("az"));           // Not matched!
        System.out.println(textMatchWordzMiddle("zaz"));          // Found a match!
        System.out.println(textMatchWordzMiddle("zzz"));          // Found a match!
    }
}

import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Degenerate case: empty matrix
        if (n <= 0 || cost == null || cost.isEmpty()) {
            return 0.0;
        }

        // dp[i][j] = maximum sum of a path from (0,0) to (i,j)
        long[][] dp = new long[n][n];

        dp[0][0] = cost.get(0).get(0);

        // First row: can only be reached from the left
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // First column: can only be reached from above
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // Interior cells: come from above or from the left
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                long fromTop = dp[i - 1][j];
                long fromLeft = dp[i][j - 1];
                dp[i][j] = cost.get(i).get(j) + Math.max(fromTop, fromLeft);
            }
        }

        // Every path from (0,0) to (n-1,n-1) visits exactly 2n-1 cells,
        // so the average = bestSum / (2n - 1).
        double pathLength = 2.0 * n - 1.0;
        return dp[n - 1][n - 1] / pathLength;
    }
}

