final class NewmanPrime {

    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Check parameter for validity.
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive, got: " + n);
        }

        // NSW numbers: S(1) = 1, S(2) = 3, S(k) = 2*S(k-1) + S(k-2)
        //   -> 1, 3, 7, 17, 41, 97, 239, 577, ...
        long prev = 1; // S(k-1)
        long curr = 1; // S(k)   (k = 1)

        for (int k = 2; k <= n; k++) {
            long next = 2L * curr + prev;
            prev = curr;
            curr = next;
        }

        return (int) curr;
    }

    public static void main(String[] args) {
        // Quick self-check against the documented examples.
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
        System.out.println(newmanPrime(6)); // 97
        System.out.println(newmanPrime(7)); // 239
    }
}

