class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths
     * for the given square matrix of size n*n.
     *
     * Moves allowed: right or down only (every path therefore visits 2n-1 cells,
     * so maximizing the average is equivalent to maximizing the path sum).
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // --- Check parameters for validity ---------------------------------
        if (cost == null) {
            throw new IllegalArgumentException("cost matrix must not be null");
        }
        if (n <= 0) {
            throw new IllegalArgumentException("n must be a positive integer");
        }
        if (cost.size() < n) {
            throw new IllegalArgumentException("cost matrix must contain at least n rows");
        }

        // --- DP table: best[i][j] = max sum of a path ending at (i, j) ------
        List<List<Integer>> best = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            List<Integer> row = cost.get(i);
            if (row == null || row.size() < n) {
                throw new IllegalArgumentException("each row must contain at least n columns");
            }
            best.add(new ArrayList<>(Collections.nCopies(n, 0)));
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int here = cost.get(i).get(j);

                int previous;
                if (i == 0 && j == 0) {
                    previous = 0;                       // start cell
                } else if (i == 0) {
                    previous = best.get(0).get(j - 1);   // came from the left
                } else if (j == 0) {
                    previous = best.get(i - 1).get(0);   // came from above
                } else {
                    previous = Math.max(best.get(i - 1).get(j),   // from above
                                        best.get(i).get(j - 1));   // from the left
                }
                best.get(i).set(j, here + previous);
            }
        }

        // --- Every admissible path contains exactly 2n - 1 cells ------------
        int cellsOnPath = 2 * n - 1;
        return best.get(n - 1).get(n - 1) / (double) cellsOnPath;
    }
}

