class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        if (cost == null || n <= 0) {
            return 0.0;
        }
        // n == 1 : the only cell is the whole path
        if (n == 1) {
            return (double) cost.get(0).get(0);
        }

        // dp[i][j] = maximum sum of any right/down path ending at (i, j)
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                long best = 0;
                boolean hasPrev = false;
                if (i > 0) {                       // came from above
                    best = dp[i - 1][j];
                    hasPrev = true;
                }
                if (j > 0) {                       // came from the left
                    long fromLeft = dp[i][j - 1];
                    if (!hasPrev || fromLeft > best) {
                        best = fromLeft;
                    }
                    hasPrev = true;
                }
                dp[i][j] = cost.get(i).get(j) + (hasPrev ? best : 0L);
            }
        }

        // Every valid path visits exactly (2n - 1) cells,
        // so max average = max sum / (2n - 1)
        double length = 2.0 * n - 1.0;
        return dp[n - 1][n - 1] / length;
    }
}

