class CountVowels {
    /**
     * * Write a function to count those characters which have vowels as their neighbors in the given string.
     *
     * > countVowels("bestinstareels")
     * 7
     * > countVowels("partofthejourneyistheend")
     * 12
     * > countVowels("amazonprime")
     * 5
     */

    /** Helper: is this character a vowel (a, e, i, o, u - case insensitive)? */
    private static boolean isVowel(char c) {
        switch (Character.toLowerCase(c)) {
            case 'a':
            case 'e':
            case 'i':
            case 'o':
            case 'u':
                return true;
            default:
                return false;
        }
    }

    public static int countVowels(String testStr) {
        if (testStr == null || testStr.length() < 2) {
            // A single character (or nothing) can never have a vowel neighbour
            return 0;
        }

        int count = 0;
        int len = testStr.length();

        for (int i = 0; i < len; i++) {
            char current = testStr.charAt(i);

            // Only non-vowel characters are counted; a vowel itself is skipped
            // (its own neighbours are generally not vowels).
            if (isVowel(current)) {
                continue;
            }

            boolean hasVowelNeighbour = false;

            // left neighbour
            if (i > 0 && isVowel(testStr.charAt(i - 1))) {
                hasVowelNeighbour = true;
            }

            // right neighbour
            if (!hasVowelNeighbour && i < len - 1 && isVowel(testStr.charAt(i + 1))) {
                hasVowelNeighbour = true;
            }

            if (hasVowelNeighbour) {
                count++;
            }
        }

        return count;
    }

    // Simple driver to demonstrate the three given examples
    public static void main(String[] args) {
        System.out.println(countVowels("bestinstareels"));              // 7
        System.out.println(countVowels("partofthejourneyistheend"));    // 12
        System.out.println(countVowels("amazonprime"));                 // 5
    }
}

