class SeriesSum {
    /**
     * * Write a function to calculate the sum of series 1²+2²+3²+….+n².
     *
     * > seriesSum(6)
     * 91
     * > seriesSum(7)
     * 140
     * > seriesSum(12)
     * 650
     */
    public static int seriesSum(int number) {
        // Sum of squares of the first 'number' natural numbers:
        //   1² + 2² + ... + n² = n * (n + 1) * (2n + 1) / 6
        if (number <= 0) {
            return 0;
        }

        // Use BigInteger to avoid any intermediate overflow,
        // then convert back to int as required by the signature.
        BigInteger n = BigInteger.valueOf(number);
        BigInteger sum = n.multiply(n.add(BigInteger.ONE))
                           .multiply(n.shiftLeft(1).add(BigInteger.ONE))
                           .divide(BigInteger.valueOf(6));

        return sum.intValue();
    }
}

