class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Base cases: S(0) = 1, S(1) = 1
        if (n <= 1) {
            return 1;
        }

        // Iterative version of the NSW recurrence:
        //   S(k) = 2*S(k-1) + S(k-2)
        // a holds S(i-2), b holds S(i-1); after each step they roll forward.
        int a = 1; // S(0)
        int b = 1; // S(1)

        for (int i = 2; i <= n; i++) {
            int c = 2 * b + a; // S(i)
            a = b;
            b = c;
        }

        return b;
    }

    // Quick self-check against the documented examples
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
        System.out.println(newmanPrime(6)); // 97
    }
}

