class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Base cases: T(0) = T(1) = 1
        if (n <= 1) {
            return 1;
        }

        // Recurrence: T(k) = 2*T(k-1) + T(k-2)
        int prevPrev = 1; // T(k-2)
        int prev     = 1; // T(k-1)

        for (int k = 2; k <= n; k++) {
            int current = 2 * prev + prevPrev;
            prevPrev = prev;
