class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Degenerate input: no cells, no path.
        if (n <= 0 || cost == null || cost.isEmpty()) {
            return 0.0;
        }

        // Every top-left -> bottom-right path visits exactly (2n - 1) cells,
        // so the average is maximized exactly when the sum is maximized.
        int[][] dp = new int[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int cell = cost.get(i).get(j);

                if (i == 0 && j == 0) {
                    // Starting cell: no predecessor.
                    dp[i][j] = cell;
                } else if (i == 0) {
                    // First row: can only come from the left.
                    dp[i][j] = dp[i][j - 1] + cell;
                } else if (j == 0) {
                    // First column: can only come from above.
                    dp[i][j] = dp[i - 1][j] + cell;
                } else {
                    // Otherwise take the better of "from above" / "from left".
                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + cell;
                }
            }
        }

        double maxSum = dp[n - 1][n - 1];
        double cellsInPath = 2 * n - 1;

        return maxSum / cellsInPath;
    }

