class SeriesSum {
    /**
     * * Write a function to calculate the sum of series 1²+2²+3²+….+n².
     *
     * > seriesSum(6)
     * 91
     * > seriesSum(7)
     * 140
     * > seriesSum(12)
     * 650
     */
    public static int seriesSum(int number) {
        // Empty series (n <= 0) contributes nothing.
        if (number <= 0) {
            return 0;
        }

        // Closed form: n * (n + 1) * (2n + 1) / 6
        // n*(n+1) is always even, so dividing by 2 first keeps the intermediate
        // value smaller and the final division by 3 exact for reasonable n.
        long half = ((long) number * (number + 1)) / 2;   // n(n+1)/2
        long result = half * (2L * number + 1) / 3;       // * (2n+1) / 3

        return (int) result;
    }
}

