class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Degenerate case: empty matrix
        if (n <= 0 || cost == null || cost.isEmpty()) {
            return 0.0;
        }

        // dp[i][j] holds the maximum path SUM from (0,0) to (i,j)
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            List<Integer> row = cost.get(i);
            for (int j = 0; j < n; j++) {
                int cell = row.get(j);

                long bestPrev;
                if (i == 0 && j == 0) {
                    bestPrev = 0L;                 // starting cell
                } else if (i == 0) {
                    bestPrev = dp[i][j - 1];       // only from the left
                } else if (j == 0) {
                    bestPrev = dp[i - 1][j];       // only from above
                } else {
                    bestPrev = Math.max(dp[i - 1][j], dp[i][j - 1]);
                }

                dp[i][j] = bestPrev + cell;
            }
        }

        // Every path contains exactly (2n - 1) cells, so the average
        // is maximized exactly when the total sum is maximized.
        double pathLength = (2.0 * n) - 1.0;
        return dp[n - 1][n - 1] / pathLength;
    }
}

