class SeriesSum {
    /**
     * * Write a function to calculate the sum of series 1²+2²+3²+….+n².
     *
     * > seriesSum(6)
     * 91
     * > seriesSum(7)
     * 140
     * > seriesSum(12)
     * 650
     */
    public static int seriesSum(int number) {
        if (number <= 0) {
            return 0;
        }
        // Closed form: n(n+1)(2n+1)/6 -- exact integer division,
        // one of the three consecutive factors is always divisible by 3
        // and another by 2, so no rounding occurs for any integer n.
        long n = number;
        return (int) ((n * (n + 1) * (2 * n + 1)) / 6);
    }

    // Optional: iterative equivalent (useful as a sanity check)
    public static int seriesSumIterative(int number) {
        int sum = 0;
        for (int i = 1; i <= number; i++) {
            sum += i * i;
        }
        return sum;
    }

    public static void main(String[] args) {
        System.out.println(seriesSum(6));   // 91
        System.out.println(seriesSum(7));   // 140
        System.out.println(seriesSum(12));  // 650
    }
}

