class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Every right/down path through an n*n grid visits exactly (2n - 1) cells,
        // so maximizing the average == maximizing the total sum.
        if (n <= 0) {
            return 0.0;
        }

        int[][] dp = new int[n][n];

        // Seed with the starting cell itself -- it belongs to every path.
        dp[0][0] = cost.get(0).get(0);

        // First column: can only arrive from above.
        for (int i = 1; i < n; i++) {
            dp[i][0] = dp[i - 1][0] + cost.get(i).get(0);
        }

        // First row: can only arrive from the left.
        for (int j = 1; j < n; j++) {
            dp[0][j] = dp[0][j - 1] + cost.get(0).get(j);
        }

        // Interior cells: best of (from above, from left) plus current value.
        for (int i = 1; i < n; i++) {
            for (int j = 1; j < n; j++) {
                int best = Math.max(dp[i - 1][j], dp[i][j - 1]);
                dp[i][j] = best + cost.get(i).get(j);
            }
        }

        double maxSum = dp[n - 1][n - 1];
        int pathLength = 2 * n - 1;

        return maxSum / pathLength;
    }
}

