class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Base cases of the Newman-Shanks-Williams recurrence:
        //   S(1) = 1, S(2) = 3, S(k) = 2*S(k-1) + S(k-2)
        if (n <= 1) {
            return 1;
        }
        if (n == 2) {
            return 3;
        }

        // Iterative evaluation of the recurrence (O(n) time, O(1) space).
        // long is used internally because the sequence grows roughly by a factor
        // of (1 + sqrt(2)) ~ 2.414 at each step and quickly exceeds int range.
        long prev = 1L;   // S(k-2)
        long curr = 3L;   // S(k-1)

        for (int k = 3; k <= n; k++) {
            long next = 2L * curr + prev;  // S(k)
            prev = curr;
            curr = next;
        }

        return (int) curr;
    }

    // Quick self-check of the documented examples
    public static void main(String[] args) {
        System.out.println(newmanPrime(3)); // 7
        System.out.println(newmanPrime(4)); // 17
        System.out.println(newmanPrime(5)); // 41
        System.out.println(newmanPrime(6)); // 97
        System.out.println(newmanPrime(7)); // 167
    }
}

