     * * Write a function to calculate the sum of series 1²+2²+3²+….+n².
     *
     * > seriesSum(6)
     * 91
     * > seriesSum(7)
     * 140
     * > seriesSum(12)
     * 650
     */
    public static int seriesSum(int number) {
        // Empty series (n <= 0) contributes nothing.
        if (number <= 0) {
            return 0;
        }

        // Closed form: 1^2 + 2^2 + ... + n^2 = n(n+1)(2n+1)/6
        // The numerator is always divisible by 6 for integer n,
        // so dividing first keeps intermediate values small.
        long n = number;
        long numerator = n * (n + 1) * (2 * n + 1);

        return (int) (numerator / 6);
    }
}

