class Maxaverageofpath {
    /**
     * * Write a function to find a path with the maximum average over all existing paths for the given square matrix of size n*n.
     *
     * > maxaverageofpath([[1, 2, 3], [6, 5, 4], [7, 3, 9]], 3)
     * 5.2
     * > maxaverageofpath([[2, 3, 4], [7, 6, 5], [8, 4, 10]], 3)
     * 6.2
     * > maxaverageofpath([[3, 4, 5], [8, 7, 6], [9, 5, 11]], 3)
     * 7.2
     */
    public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
        // Trivial / degenerate cases
        if (cost == null || n <= 0 || cost.isEmpty()) {
            return 0.0;
        }
        if (n == 1) {
            return cost.get(0).get(0).doubleValue();
        }

        // dp[i][j] = maximum sum of any path from (0,0) to (i,j)
        long[][] dp = new long[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                long value = cost.get(i).get(j);

                if (i == 0 && j == 0) {
                    dp[i][j] = value;                       // start cell
                } else if (i == 0) {
                    dp[i][j] = dp[i][j - 1] + value;        // first row: only from left
                } else if (j == 0) {
                    dp[i][j] = dp[i - 1][j] + value;        // first column: only from above
                } else {
                    // come from the better of the two legal predecessors (up / left)
                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]) + value;
                }
            }
        }

        // Every valid path contains exactly (2n - 1) cells, so the best average
        // is attained by the path with the greatest sum.
        int pathLength = 2 * n - 1;
        return dp[n - 1][n - 1] / (double) pathLength;
    }
}

