     * 91
     * > seriesSum(7)
     * 140
     * > seriesSum(12)
     * 650
     */
    public static int seriesSum(int number) {
        // Validity check the parameter before using it.
        if (number <= 0) {
            return 0;
        }

        // Closed form: 1^2 + 2^2 + ... + n^2 = n(n+1)(2n+1)/6
        // Compute in long so the intermediate product does not overflow,
        // then narrow back to int (the mathematical result still fits).
        long n = number;
        long sum = n * (n + 1) * (2 * n + 1) / 6;

        return (int) sum;
    }
}

