class NewmanPrime {
    /**
     * * Write a function to find the nth newman–shanks–williams prime number.
     *
     * > newmanPrime(3)
     * 7
     * > newmanPrime(4)
     * 17
     * > newmanPrime(5)
     * 41
     */
    public static int newmanPrime(int n) {
        // Base cases of the Newman-Shanks-Williams sequence:
        //   S(1) = 1, S(2) = 3
        if (n <= 0) {
            return 0;
        }
        if (n == 1) {
            return 1;
        }
        if (n == 2) {
            return 3;
        }

        // Recurrence: S(k) = 2 * S(k-1) + S(k-2)
        //   S: 1, 3, 7, 17, 41, 99, 239, ...
        long secondLast = 1L;   // S(k-2)
        long last       = 3L;   // S(k-1)

        for (int k = 3; k <= n; k++) {
            long current = 2L * last + secondLast;
            secondLast = last;
            last = current;
        }

        return (int) last;
    }
}

