     */
    public static String textMatchWordzMiddle(String text) {
        if (text == null || text.isEmpty()) {
            return "Not matched!";
        }

        // \b      -> word boundary (z cannot be the very first char of a word)
        // \w+     -> at least one character BEFORE the 'z'
        // z       -> the required letter
        // \w+     -> at least one character AFTER the 'z'  (z cannot be the last char)
        // \b      -> closing word boundary
        java.util.regex.Pattern pattern =
                java.util.regex.Pattern.compile("\\b\\w+z\\w+\\b");
        java.util.regex.Matcher matcher = pattern.matcher(text);

        if (matcher.find()) {
            return "Found a match!";
        }
        return "Not matched!";
    }
}

public static Double maxaverageofpath(List<List<Integer>> cost, int n) {
    int[][] dp = new int[n][n];
    dp[0][0] = cost.get(0).get(0);

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == 0 && j == 0) continue;
            int fromTop = (i > 0) ? dp[i - 1][j] : Integer.MIN_VALUE;
            int fromLeft = (j > 0) ? dp[i][j - 1] : Integer.MIN_VALUE;
            dp[i][j] = Math.max(fromTop, fromLeft) + cost.get(i).get(j);
        }
    }

    double totalSteps = 2 * n - 1;
    return dp[n - 1][n - 1] / totalSteps;
}

